window.HISN_DUAS = [{"id":"hisn-1","n":1,"title":"When waking up","chapter_en":"When waking up","chapter_ar":"أذكار الاستيقاظ من النوم","arabic":"الحَمْـدُ لِلّهِ الّذي أَحْـيانا بَعْـدَ ما أَماتَـنا وَإليه النُّـشور","transliteration":"Alḥamdu lillāhil-ladhī \u0027aḥyānā ba`da mā \u0027amātanā wa \u0027ilayhin-nushūr.","meaning_en":"Praise is to Allah Who gives us life after He has caused us to die and to Him is the return.","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 11/113; Muslim 4/2083","source":"Hisn al-Muslim 1 - Sunnah.com","source_url":"https://sunnah.com/hisn:1","tags":["daily","gratitude"]},{"id":"hisn-2","n":2,"title":"When waking up","chapter_en":"When waking up","chapter_ar":"أذكار الاستيقاظ من النوم","arabic":"لا إلهَ إلاّ اللّهُ وَحْـدَهُ لا شَـريكَ له، لهُ المُلـكُ ولهُ الحَمـد، وهوَ على كلّ شيءٍ قدير، سُـبْحانَ اللهِ، والحمْـدُ لله، ولا إلهَ إلاّ اللهُ واللهُ أكبَر، وَلا حَولَ وَلا قوّة إلاّ باللّهِ العليّ العظيم، رَبِّ اغْفرْ لي","transliteration":"Lā \u0027ilāha \u0027illallāhu waḥdahu la sharīka lahu, lahul-mulku wa lahul-ḥamdu, wa huwa \u0027alā kulli shay\u0027in qadīr Subḥānallāhi, walḥamdu lillāhi, wa lā \u0027ilāha \u0027illallāhu, wallāhu \u0027akbar, wa lā ḥaula wa lā quwwata \u0027illā billāhil-`aliyyil-`aẓīm, rabbighfir lī.","meaning_en":"There is none worthy of worship but Allah alone, Who has no partner, His is the dominion and to Him belongs all praise, and He is able to do all things. Glory is to Allah. Praise is to Allah. There is none worthy of worship but Allah. Allah is the Most Great. There is no might and no power except by Allah\u0027s leave, the Exalted, the Mighty. My Lord, forgive me.","meaning_dv":"","reference":"Whoever says this will be forgiven, and if he supplicates Allah, his prayer will be answered; if he performs ablution and prays, his prayer will be accepted. Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 3/39, among others. The wording here is from Ibn Majah 2/335.","source":"Hisn al-Muslim 2 - Sunnah.com","source_url":"https://sunnah.com/hisn:2","tags":["forgiveness","prayer","daily","gratitude"]},{"id":"hisn-3","n":3,"title":"When waking up","chapter_en":"When waking up","chapter_ar":"أذكار الاستيقاظ من النوم","arabic":"الحمدُ للهِ الذي عافاني في جَسَدي وَرَدّ عَليّ روحي وَأَذِنَ لي بِذِكْرِه","transliteration":"Al-ḥamdu lillāhil-ladhī `āfānī fī jasadī, wa radda `alayya rūḥī, wa \u0027adhina lī bidhikrihi.","meaning_en":"Praise is to Allah Who gave strength to my body and returned my soul to me and permitted me to remember Him.","meaning_dv":"","reference":"At-Tirmidhi 5/473. See Al-Albani\u0027s Sahih Tirmidhi 3/144.","source":"Hisn al-Muslim 3 - Sunnah.com","source_url":"https://sunnah.com/hisn:3","tags":["daily","gratitude"]},{"id":"hisn-4","n":4,"title":"When waking up","chapter_en":"When waking up","chapter_ar":"أذكار الاستيقاظ من النوم","arabic":"إِنَّ فِي خَلْقِ السَّمَوَاتِ وَالأَرْضِ وَاخْتِلاَفِ اللَّيْلِ وَالنَّهَارِ لآيَاتٍ لأُوْلِي الألْبَابِ {190} الَّذِينَ يَذْكُرُونَ اللهَ قِيَامًا وَقُعُودًا وَعَلَىَ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِي خَلْقِ السَّمَوَاتِ وَالأَرْضِ رَبَّنَا مَا خَلَقْتَ هَذا بَاطِلاً سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ {191} رَبَّنَا إِنَّكَ مَن تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ {192} رَّبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلإِيمَانِ أَنْ ءامِنُواْ بِرَبِّكُمْ فَآمَنَّا رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الأبْرَارِ {193} رَبَّنَا وَءاتِنَا مَا وَعَدتَّنَا عَلَى رُسُلِكَ وَلاَ تُخْزِنَا يَوْمَ الْقِيَامَةِ إِنَّكَ لاَ تُخْلِفُ الْمِيعَادَ {194} فَاسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّي لاَ أُضِيعُ عَمَلَ عَامِلٍ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَى بَعْضُكُم مِّن بَعْضٍ فَالَّذِينَ هَاجَرُواْ وَأُخْرِجُواْ مِن دِيَارِهِمْ وَأُوذُواْ فِي سَبِيلِي وَقَاتَلُواْ وَقُتِلُواْ لأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الأَنْهَارُ ثَوَابًا مِّن عِندِ اللهِ وَاللهُ عِندَهُ حُسْنُ الثَّوَابِ {195} لاَ يَغُرَّنَّكَ تَقَلُّبُ الَّذِينَ كَفَرُواْ فِي الْبِلاَدِ {196} مَتَاعٌ قَلِيلٌ ثُمَّ مَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمِهَادُ {197} لَكِنِ الَّذِينَ اتَّقَوْاْ رَبَّهُمْ لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الأَنْهَارُ خَالِدِينَ فِيهَا نُزُلاً مِّنْ عِندِ اللهِ وَمَا عِندَ اللهِ خَيْرٌ لِّلأَبْرَارِ {198} وَإِنَّ مِنْ أَهْلِ الْكِتَابِ لَمَن يُؤْمِنُ بِاللهِ وَمَا أُنزِلَ إِلَيْكُمْ وَمَآ أُنزِلَ إِلَيْهِمْ خَاشِعِينَ للهِ لاَ يَشْتَرُونَ بِآيَاتِ اللهِ ثَمَنًا قَلِيلاً أُوْلَئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ إِنَّ اللهَ سَرِيعُ الْحِسَابِ {199} يَا أَيُّهَا الَّذِينَ ءامَنُواْ اصْبِرُواْ وَصَابِرُواْ وَرَابِطُواْ وَاتَّقُواْ اللهَ لَعَلَّكُمْ تُفْلِحُونَ {200}","transliteration":"\u0027Inna fī khalqi-ssamāwāti wal-\u0027arđi wakhtilāfi-llayli wan-nahāri la\u0027āyātin li\u0027wlī-l-\u0027albāb. Al-ladhīna yadhkurūna-allaha qiyāman wa qu`ūdan wa `alā junūbihim wa yatafakkarūna fī Khalqi-ssamāwāti wal-\u0027arđi rabbanā mā khalaqta hādhā bāţilāan subĥānaka faqinā `adhāban-nār. Rabbanā \u0027innaka man tudkhili-nnāra faqad \u0027akhzaytahu wa mā li-žžālimīna min \u0027anşārin. Rabbanā \u0027innanā sami`nā munādīan yunādī lil\u0027īmāni \u0027an \u0027āminū birabbikum fa \u0027āmannā. Rabbanā fāghfirlanā dhunūbanā wa kaffir `annā sayyi\u0027ātinā wa tawaffanā ma`a al-\u0027abrāri. Rabbanā wa \u0027ātinā mā wa`adtanā `alá rusulika wa lā tukhzinā yawmal-qiyāmati \u0027innaka lā tukhliful-mī`ād. Fāstajāba lahum rabbuhum \u0027annī lā \u0027uđī`u `amala `āmilin minkum min dhakarin \u0027aw \u0027unthá ba`đukum min ba`đin fa-lladhīna hājarū wa \u0027ukhrijū min diyārihim wa \u0027ūdhū fī sabīlī wa qātalū wa qutilū la\u0027ukaffiranna `anhum sayyi\u0027ātihim wa la\u0027udkhilannahum jannātin tajrī min taĥtihāl-\u0027anhāru thawāban min `indil-lahi wal-lāhu `indahu ĥusnuth-thawāb. Lā yaghurrannaka taqallubu \u0027l-ladhīna kafarū fī l-bilādi. Matā`un qalīlun thumma ma\u0027wāhum jahannamu wa bi\u0027sa \u0027l-mihād. Lakini \u0027l-ladhīna \u0027ttaqaw rabbahum lahum jannātun tajrī min taĥtihā \u0027l-\u0027anhāru khālidīna fīhā nuzulan min `indi \u0027l-lahi wa mā `inda \u0027llahi khayrun li \u0027l-abrār. Wa \u0027inna min \u0027ahli \u0027l-kitābi laman yu\u0027minu bil-lahi wa mā \u0027unzila \u0027ilaykum wa mā \u0027unzila \u0027ilayhim khāshi`īna lillahi lā yashtarūna bi\u0027āyāti \u0027l-lahi thamanan qalīlāan \u0027ulā\u0027ika lahum \u0027ajruhum `inda rabbihim \u0027inna \u0027l-laha sarī`u al-ĥisāb. Yā \u0027ayyuhā \u0027l-ladhīna \u0027āmanū-şbirū wa şābirū wa rābiţū wa \u0027ttaqu \u0027l-laha la`allakum tufliĥūn.","meaning_en":"Indeed, in the creation of the heavens and the earth and the alternation of the day and night there are signs for people of reason. ˹They are˺ those who remember Allah while standing, sitting, and lying on their sides, and reflect on the creation of the heavens and the earth ˹and pray˺, “Our Lord! You have not created ˹all of˺ this without purpose. Glory be to You! Protect us from the torment of the Fire. Our Lord! Indeed, those You commit to the Fire will be ˹completely˺ disgraced! And the wrongdoers will have no helpers. Our Lord! We have heard the caller to ˹true˺ belief, ˹proclaiming,˺ ‘Believe in your Lord ˹alone˺,’ so we believed. Our Lord! Forgive our sins, absolve us of our misdeeds, and allow us ˹each˺ to die as one of the virtuous. Our Lord! Grant us what You have promised us through Your messengers and do not put us to shame on Judgment Day—for certainly You never fail in Your promise.” So their Lord responded to them:","meaning_dv":"","reference":"Qur\u0027an Āl-\u0027Imran 3: 190-200; Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 8/237; Muslim 1/530.","source":"Hisn al-Muslim 4 - Sunnah.com","source_url":"https://sunnah.com/hisn:4","tags":["forgiveness","daily"]},{"id":"hisn-5","n":5,"title":"When wearing a garment","chapter_en":"When wearing a garment","chapter_ar":"دعاء لبس الثوب","arabic":"الحمدُ للهِ الّذي كَساني هذا (الثّوب) وَرَزَقَنيه مِنْ غَـيـْرِ حَولٍ مِنّي وَلا قـوّة","transliteration":"Alḥamdu lillāhil-ladhī kasānī hādhā (aththawba) wa razaqanīhi min ghayri hawlim-minnī wa lā quwwah.","meaning_en":"Praise is to Allah Who has clothed me with this (garment) and provided it for me, though I was powerless myself and incapable","meaning_dv":"","reference":"Al-Bukhari, Muslim, Abu Dawud, Ibn Majah, At-Tirmidhi. See also \u0027Irwa\u0027ul-Ghalil 7/47.","source":"Hisn al-Muslim 5 - Sunnah.com","source_url":"https://sunnah.com/hisn:5","tags":["daily","gratitude"]},{"id":"hisn-6","n":6,"title":"When wearing a new garment","chapter_en":"When wearing a new garment","chapter_ar":"دعاء لبس الثوب الجديد","arabic":"اللّهُـمَّ لَـكَ الحَـمْـدُ أنْـتَ كَسَـوْتَنيهِ، أََسْأََلُـكَ مِـنْ خَـيرِهِ وَخَـيْرِ مَا صُنِعَ لَـه، وَأَعوذُ بِكَ مِـنْ شَـرِّهِ وَشَـرِّ مـا صُنِعَ لَـهُ","transliteration":"Allāhumma lakal-ḥamdu \u0027anta kasawtanīhi, \u0027as\u0027aluka min khayrihi wa khayri mā ṣuni`a lahu, wa \u0027a`oothu bika min sharrihi wa sharri mā ṣuni`a lahu.","meaning_en":"O Allah, praise is to You. You have clothed me. I ask You for its goodness and the goodness of what it has been made for, and I seek Your protection from the evil of it and the evil of what it has been made for.","meaning_dv":"","reference":"Abu Dawud and At-Tirmidhi. See also Al-Albani, Mukhtasar Shama\u0027il At-Tirmidhi, p. 47.","source":"Hisn al-Muslim 6 - Sunnah.com","source_url":"https://sunnah.com/hisn:6","tags":["protection","daily","gratitude"]},{"id":"hisn-7","n":7,"title":"To someone wearing a new garment","chapter_en":"To someone wearing a new garment","chapter_ar":"الدعاء لمن لبس ثوباً جديداً","arabic":"تُبْـلي وَيُـخْلِفُ اللهُ تَعَالى","transliteration":"Tublī wa yukhliful-lāhu ta`ālā.","meaning_en":"May Allah replace it when it is worn out.","meaning_dv":"","reference":"Abu Dawud 4/41. See also Al-Albani Sahih Abu Dawud 2/760.","source":"Hisn al-Muslim 7 - Sunnah.com","source_url":"https://sunnah.com/hisn:7","tags":["daily"]},{"id":"hisn-8","n":8,"title":"To someone wearing a new garment","chapter_en":"To someone wearing a new garment","chapter_ar":"الدعاء لمن لبس ثوباً جديداً","arabic":"اِلبَـس جَديـداً وَعِـشْ حَمـيداً وَمُـتْ شهيداً","transliteration":"Ilbas jadīdan, wa `ish ḥamīdan, wa mut shahīdan.","meaning_en":"Put on new clothes, live a praise-worthy life and die as a martyr.","meaning_dv":"","reference":"Ibn Majah 2/1178, Al-Baghawi 12/41. See also Al-Albani, Sahih Ibn Majah 2/275","source":"Hisn al-Muslim 8 - Sunnah.com","source_url":"https://sunnah.com/hisn:8","tags":["daily","gratitude"]},{"id":"hisn-9","n":9,"title":"Before undressing","chapter_en":"Before undressing","chapter_ar":"ما يقول إذا وضع الثوب","arabic":"بِسْمِ الله","transliteration":"Bismillāhi","meaning_en":"In the Name of Allah.","meaning_dv":"","reference":"At-Tirmidhi 2/505, among others. See \u0027Irwa\u0027ul Ghalil no. 49 and Sahihul-Jami\u0027 3/203","source":"Hisn al-Muslim 9 - Sunnah.com","source_url":"https://sunnah.com/hisn:9","tags":["forgiveness"]},{"id":"hisn-10","n":10,"title":"Before entering the bathroom","chapter_en":"Before entering the bathroom","chapter_ar":"دعاء دخول الخلاء","arabic":"(بِسْمِ الله) اللّهُـمَّ إِنِّـي أَعـوذُ بِـكَ مِـنَ الْخُـبْثِ وَالْخَبائِث","transliteration":"[Bismillāhi] Allāhumma \u0027innī \u0027a`ūdhu bika minal-khubthi walkhabā\u0027ith.","meaning_en":"[In the Name of Allah]. O Allah, I seek protection in You from evil and the evil ones (or, from the evil male and female Jinn).","meaning_dv":"","reference":"Al-Bukhari 1/45, Muslim 1/283. The addition of Bismillah at its beginning was reported by Said bin Mansur. See Fathul-Bari 1/244","source":"Hisn al-Muslim 10 - Sunnah.com","source_url":"https://sunnah.com/hisn:10","tags":["protection","daily"]},{"id":"hisn-11","n":11,"title":"After leaving the bathroom","chapter_en":"After leaving the bathroom","chapter_ar":"دعاء الخروج من الخلاء","arabic":"غُفْـرانَك","transliteration":"Ghufrānaka","meaning_en":"I seek Your forgiveness.","meaning_dv":"","reference":"Abu Dawud, Ibn Majah and At-Tirmidhi. An-Nasa\u0027i recorded it in \u0027Amalul-Yawm wal-Laylah. Also see the checking of Ibn Al-Qayyim\u0027s Zadul-Ma\u0027ad, 2/387.","source":"Hisn al-Muslim 11 - Sunnah.com","source_url":"https://sunnah.com/hisn:11","tags":["forgiveness","daily"]},{"id":"hisn-12","n":12,"title":"Before ablution","chapter_en":"Before ablution","chapter_ar":"الذكر قبل الوضوء","arabic":"بِسْمِ الله","transliteration":"Bismillāhi","meaning_en":"In the Name of Allah","meaning_dv":"","reference":"Abu Dawud, Ibn Majah, and Ahmad. See also Al-Albani, \u0027Irwa\u0027ul-Ghain 1/122.","source":"Hisn al-Muslim 12 - Sunnah.com","source_url":"https://sunnah.com/hisn:12","tags":["prayer"]},{"id":"hisn-13","n":13,"title":"Upon completing the ablution","chapter_en":"Upon completing the ablution","chapter_ar":"الذكر بعد الفراغ من الوضوء","arabic":"أَشْهَدُ أَنْ لا إِلَـهَ إِلاّ اللهُ وَحْدَهُ لا شَريـكَ لَـهُ وَأَشْهَدُأَنَّ مُحَمّـداً عَبْـدُهُ وَرَسـولُـه","transliteration":"\u0027Ash-hadu \u0027an lā \u0027ilāha \u0027illallāhu waḥdahu lā sharīka lahu wa \u0027ash-hadu \u0027anna Muḥammadan `abduhu wa Rasūluhu.","meaning_en":"I bear witness that none has the right to be worshipped but Allah alone, Who has no partner; and I bear witness that Muhammad is His slave and His Messenger.","meaning_dv":"","reference":"Muslim 1/209.","source":"Hisn al-Muslim 13 - Sunnah.com","source_url":"https://sunnah.com/hisn:13","tags":["prayer"]},{"id":"hisn-14","n":14,"title":"Upon completing the ablution","chapter_en":"Upon completing the ablution","chapter_ar":"الذكر بعد الفراغ من الوضوء","arabic":"اللّهُـمَّ اجْعَلنـي مِنَ التَّـوّابينَ وَاجْعَـلْني مِنَ المتَطَهّـرين.","transliteration":"Allāhummaj`alnī minat-tawwābīna waj`alnī minal-mutaṭahhirīn.","meaning_en":"O Allah, make me among those who turn to You in repentance, and make me among those who are purified.","meaning_dv":"","reference":"At-Tirmidhi 1/78. See also Al-Albani, Sahih At- Tirmidhi 1/18","source":"Hisn al-Muslim 14 - Sunnah.com","source_url":"https://sunnah.com/hisn:14","tags":["forgiveness","prayer"]},{"id":"hisn-15","n":15,"title":"Upon completing the ablution","chapter_en":"Upon completing the ablution","chapter_ar":"الذكر بعد الفراغ من الوضوء","arabic":"سُبْحـانَكَ اللّهُـمَّ وَبِحَمدِك أَشْهَـدُ أَنْ لا إِلهَ إِلاّ أَنْتَ أَسْتَغْفِرُكَ وَأَتوبُ إِلَـيْك","transliteration":"Subḥānaka Allāhumma wa biḥamdika, \u0027ash-hadu \u0027an lā \u0027ilāha \u0027illā \u0027Anta, \u0027astaghfiruka wa \u0027atūbu \u0027ilayk.","meaning_en":"Glory is to You, O Allah, and praise; I bear witness that there is none worthy of worship but You. I seek Your forgiveness and turn to You in repentance.","meaning_dv":"","reference":"An-Nasa\u0027i, \u0027Amalul-Yawm wal-Laylah, p. 173. See also Al-Albani, \u0027Irwa\u0027ul-Ghalil 1/135 and 2/94.","source":"Hisn al-Muslim 15 - Sunnah.com","source_url":"https://sunnah.com/hisn:15","tags":["forgiveness","prayer","gratitude"]},{"id":"hisn-16","n":16,"title":"Remembrance when leaving the home","chapter_en":"Remembrance when leaving the home","chapter_ar":"الذكر عند الخروج من المنزل","arabic":"بِسْمِ اللهِ ، تَوَكَّلْـتُ عَلى اللهِ وَلا حَوْلَ وَلا قُـوَّةَ إِلاّ بِالله","transliteration":"Bismillāhi, tawakkaltu `alallāhi, wa lā ḥawla wa lā quwwata illā billāh.","meaning_en":"In the Name of Allah, I have placed my trust in Allah, there is no might and no power except by Allah.","meaning_dv":"","reference":"Abu Dawud 4/325, At-Tirmidhi 5/490. See also Al-Albani, Sahih At-Tirmidhi 3/151","source":"Hisn al-Muslim 16 - Sunnah.com","source_url":"https://sunnah.com/hisn:16","tags":["daily"]},{"id":"hisn-17","n":17,"title":"Remembrance when leaving the home","chapter_en":"Remembrance when leaving the home","chapter_ar":"الذكر عند الخروج من المنزل","arabic":"اللّهُـمَّ إِنِّـي أَعـوذُ بِكَ أَنْ أَضِـلَّ أَوْ أُضَـل ، أَوْ أَزِلَّ أَوْ أُزَل ، أَوْ أَظْلِـمَ أَوْ أَُظْلَـم ، أَوْ أَجْهَلَ أَوْ يُـجْهَلَ عَلَـيّ","transliteration":"Allāhumma \u0027innī \u0027a`ūdhu bika \u0027an \u0027aḍilla, \u0027aw \u0027uḍalla, \u0027aw \u0027azilla, \u0027aw \u0027uzalla, \u0027aw \u0027aẓlima, \u0027aw \u0027uẓlama, \u0027aw \u0027ajhala \u0027aw yujhala `alayya.","meaning_en":"O Allah, I seek refuge in You lest I misguide others , or I am misguided by others , lest I cause others to err or I am caused to err , lest I abuse others or be abused, and lest I behave foolishly or meet with the foolishness of others.","meaning_dv":"","reference":"Abu Dawud, Ibn Majah, An-Nasa\u0027i, At-Tirmidhi. See also Al-Albani, Sahih At-Tirmidhi 3/152 and Sahih Ibn Majah 2/336","source":"Hisn al-Muslim 17 - Sunnah.com","source_url":"https://sunnah.com/hisn:17","tags":["protection","daily"]},{"id":"hisn-18","n":18,"title":"Remembrance upon entering the home","chapter_en":"Remembrance upon entering the home","chapter_ar":"الذكر عند الدخول المنزل","arabic":"بِسْـمِ اللهِ وَلَجْنـا، وَبِسْـمِ اللهِ خَـرَجْنـا، وَعَلـى رَبِّنـا تَوَكّلْـن (ثم ليسلم على أهله.)","transliteration":"Bismillāhi walajnā, wa bismillāhi kharajnā, wa `ala Rabbinā tawakkalnā","meaning_en":"In the Name of Allah we enter , in the Name of Allah we leave , and upon our Lord we depend [then say As-Salāmu `Alaykum to those present].","meaning_dv":"","reference":"Abu Dawud 4/325. Muslim {Hadith no. 2018) says that one should mention the Name of Allah when entering the home and when beginning to eat; and that the devil, hearing this, says: \"There is no shelter for us here tonight and no food.\"","source":"Hisn al-Muslim 18 - Sunnah.com","source_url":"https://sunnah.com/hisn:18","tags":["financial","protection","daily"]},{"id":"hisn-19","n":19,"title":"When going to the mosque","chapter_en":"When going to the mosque","chapter_ar":"دعاء الذهاب إلى المسجد","arabic":"اللّهُـمَّ اجْعَـلْ فِي قَلْبـي نُوراً ، وَفي لِسَـانِي نُوراً، وَفِي سَمْعِي نُوراً, وَفِي بَصَرِيِ نُوراً, وَمِنْ فََوْقِي نُوراً , وَ مِنْ تَحْتِي نُوراً, وَ عَنْ يَمِينيِ نُوراَ, وعَنْ شِمَالِي نُوراً, وَمْن أَماَمِي نُوراً, وَمِنْ خَلْفيِ نُوراَ, واجْعَلْ فِي نَفْسِي نُوراً, وأَعْظِمْ لِي نُوراً, وَعظِّمْ لِي نُوراً, وَاجْعَلْ لِي نُوراً, واجْعَلنِي نُوراً, أللَّهُمَّ أَعْطِنِي نُوراً, واجْعَلْ فِي عَصَبِي نُوراً, وَفِي لَحْمِي نُوراً, وَفِي دَمِي نُوراً وَفِي شَعْرِي نُوراً, وفِي بَشَرِي نُوراً (أَللَّهُمَّ اجِعَلْ لِي نُوراً فِي قّبْرِي وَ نُوراَ فِي عِظاَمِي) (وَزِدْنِي نُوراً, وَزِدْنِي نُوراَ , وَزِدْنِي نُوراً) (وَهَبْ لِي نُوراً عَلَى نُوراً )","transliteration":"Allāhummaj\u0027al fī qalbī nūran, wa fī lisānī nūran, wa fī sam`ī nūran, wa fī baṣarī nūran, wa min fawqī nūran, wa min taḥtī nūran, wa `an yamīnī nūran, wa `an shimālī nūran, wa min \u0027amāmī nūran, wa min khalfī nūran, waj`al fī nafsī nūran, wa \u0027a`ẓim lī nūran, wa `ẓẓim lī nūran, waj`allī nūran, waj`alnī nūran, Allāhumma \u0027a`tinī nūran, waj\u0027al fī `aṣabī nūran, wa fī laḥmī nūran, wa fī damī nūran, wa fī sha`rī nūran, wa fī basharī nūran. [Allāhummaj`allī nūran fī qabrī wa nūran fī `iẓāmī.] [Wa zidnī nūran, wa zidnī nūran, wa zidnī nūran.] [Wa hab lī nūran `alā nūr.]","meaning_en":"O Allah, place light in my heart, and on my tongue light, and in my ears light and in my sight light, and above me light, and below me light, and to my right light, and to my left light, and before me light and behind me light. Place in my soul light. Magnify for me light, and amplify for me light. Make for me light and make me a light. O Allah, grant me light, and place light in my nerves, and in my body light and in my blood light and in my hair light and in my skin light.1 [O Allah, make for me a light in my grave... and a light in my bones.] (At-Tirmidhi 5/483 (Hadith no. 3419).) [Increase me in light, increase me in light, increase me in light .] (Al-Bukhari in Al-\u0027Adab Al-Mufrad (Hadith no. 695), p. 258. See also Al-Albani, Sahih Al-\u0027Adab Al-Mufrad(no. 536).) [Grant me light upon light.] (Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 11/118.)","meaning_dv":"","reference":"1 Up to this point was reported by Al-Bukhari 11 / 116 (Hadith no. 6316) and by Muslim 1/526, 529-530 (Hadithno. 763).","source":"Hisn al-Muslim 19 - Sunnah.com","source_url":"https://sunnah.com/hisn:19","tags":["prayer","death"]},{"id":"hisn-20","n":20,"title":"Upon entering the mosque","chapter_en":"Upon entering the mosque","chapter_ar":"دعاء دخول المسجد","arabic":"أَعوذُ باللهِ العَظيـم وَبِوَجْهِـهِ الكَرِيـم وَسُلْطـانِه القَديـم مِنَ الشّيْـطانِ الرَّجـيم، [ بِسْـمِ الله، وَالصَّلاةُ وَالسَّلامُ عَلى رَسولِ الله]، اللّهُـمَّ افْتَـحْ لي أَبْوابَ رَحْمَتـِك","transliteration":"\u0027A`ūdhu billāhi l-`aẓīm, wa bi-wajhihil-karīm, wa sultānihil-qadīm, min ash-shaytānir-rajīm. [Bismillāhi, wassalātu wassalāmu `alā rasūlillāhi.] Allāhummaftaḥ lī \u0027abwāba raḥmatik.","meaning_en":"I seek refuge in Almighty Allah, By His Noble Face, By His primordial power, From Satan the outcast.1 [In the Name of Allah, and blessings 2 and peace be upon the Messenger of Allah.3 O Allah, open before me the doors of Your mercy.4","meaning_dv":"","reference":"1. Abu Dawud and Al-Albani, Sahihul-Jdmi\u0027 As-Saghir (Hadithno. 4591). 2. Ibn As-Sunni (Hadith no. 88), graded good by Al-Albani. 3. Abu Dawud 1/126, see also Al-Albani, Sahihul-Jami\u0027As-Saghir 1/528. 4. Muslim 1/494. There is also a report in Sunan Ibn Majah on the authority of Fatimah (RA), : \"O Allah, forgive me my sins and open for me the doors of Your mercy.\" It was graded authentic by Al-Albani due to supporting Ahadith. See Sahih Ibn Majah 1/128-9.","source":"Hisn al-Muslim 20 - Sunnah.com","source_url":"https://sunnah.com/hisn:20","tags":["forgiveness","protection","prayer","gratitude"]},{"id":"hisn-21","n":21,"title":"Upon leaving the mosque","chapter_en":"Upon leaving the mosque","chapter_ar":"دعاء الخروج من المسجد","arabic":"بِسمِ الله وَالصّلاةُ وَالسّلامُ عَلى رَسولِ الله، اللّهُـمَّ إِنّـي أَسْأَلُكَ مِـنْ فَضْـلِك، اللّهُـمَّ اعصِمْنـي مِنَ الشَّيْـطانِ الرَّجـيم","transliteration":"Bismillāhi waṣṣalātu wassalāmu \u0027alā Rasūlillāhi, Allāhumma \u0027innī \u0027as\u0027aluka min faḍlika, Allāhumma`ṣimnī min ash-shaytānir-rajīm.","meaning_en":"In the Name of Allah, and peace and blessings be upon the Messenger of Allah. O Allah, I ask for Your favor, O Allah, protect me from Satan the outcast.","meaning_dv":"","reference":"ibid.","source":"Hisn al-Muslim 21 - Sunnah.com","source_url":"https://sunnah.com/hisn:21","tags":["forgiveness","protection","prayer","gratitude"]},{"id":"hisn-22","n":22,"title":"Concerning the athan (the call to prayer)","chapter_en":"Concerning the athan (the call to prayer)","chapter_ar":"أذكار الأذان","arabic":"يقول مثل ما يقول المؤذن إلا في (حي على الصلاة ، وحي على الفلاح) فيقول لا حول ولا قوة إلا بالله.","transliteration":"Lā ḥawla wa lā quwwata \u0027illā billāh.","meaning_en":"Repeat what the Mu\u0027adh-dhin says, except for when he says:","meaning_dv":"","reference":"Al-Bukhari 1/152, Muslim 1/288.","source":"Hisn al-Muslim 22 - Sunnah.com","source_url":"https://sunnah.com/hisn:22","tags":["prayer"]},{"id":"hisn-23","n":23,"title":"Concerning the athan (the call to prayer)","chapter_en":"Concerning the athan (the call to prayer)","chapter_ar":"أذكار الأذان","arabic":"وَأَنا أَشْـهَدُ أَنْ لا إِلـهَ إِلاّ اللهُ وَحْـدَهُ لا شَـريكَ لَـه ، وَأَنَّ محَمّـداً عَبْـدُهُ وَرَسـولُه، رَضيـتُ بِاللهِ رَبَّاً ، وَبِمُحَمَّـدٍ رَسـولاً وَبِالإِسْلامِ دينَـاً","transliteration":"Wa \u0027anā \u0027ash-hadu \u0027an lā \u0027ilāha \u0027illallāhu waḥdahu lā sharīka lahu wa \u0027anna Muḥammadan \u0027abduhu wa rasūluhu, raḍītu billāhi rabban, wa bi Muḥammadin rasūlan wa bi \u0027l-islāmi dīnan.","meaning_en":"I bear witness that none has the right to be worshipped but Allah alone, Who has no partner, and that Muhammad is His slave and His Messenger. I am pleased with Allah as my Lord, with Muhammad as my Messenger and with Islam as my religion.1 [To be recited in Arabic after the mu\u0027adh-dhin\u0027s tashahhud or the words of affirmation of Faith] 2","meaning_dv":"","reference":"1. Muslim 1/290. 2. Ibn Khuzaymah 1/220.","source":"Hisn al-Muslim 23 - Sunnah.com","source_url":"https://sunnah.com/hisn:23","tags":["prayer"]},{"id":"hisn-24","n":24,"title":"Concerning the athan (the call to prayer)","chapter_en":"Concerning the athan (the call to prayer)","chapter_ar":"أذكار الأذان","arabic":"يُصَلِّي عَلَى النَّبِيِّ صلى الله عليه وسلم بَعْدَ فَرَاغِهِ مِنْ إِجَابَةِ الْمُؤَذِّنِ","transliteration":"","meaning_en":"After replying to the call of Mu\u0027adh-dhin. you should recite in Arabic Allah\u0027s blessings on the Prophet (ﷺ).","meaning_dv":"","reference":"Muslim 1/288","source":"Hisn al-Muslim 24 - Sunnah.com","source_url":"https://sunnah.com/hisn:24","tags":["forgiveness","prayer","gratitude"]},{"id":"hisn-25","n":25,"title":"Concerning the athan (the call to prayer)","chapter_en":"Concerning the athan (the call to prayer)","chapter_ar":"أذكار الأذان","arabic":"اللّهُـمَّ رَبَّ هَذِهِ الدّعْـوَةِ التّـامَّة وَالصّلاةِ القَـائِمَة آتِ محَـمَّداً الوَسيـلةَ وَالْفَضـيلَة وَابْعَـثْه مَقـامـاً مَحـموداً الَّذي وَعَـدْتَه [إِنَّـكَ لا تُـخْلِفُ الميـعاد]","transliteration":"Allāhumma rabba hādhihi \u0027d-da\u0027wati \u0027t-tāmmah waṣ-ṣalāti \u0027l-qā\u0027imah, \u0027āti Muhammadani \u0027l-wasīlata walfaḍīlata, wab \u0027ath-hu maqāma \u0027m-mahmūdani \u0027l-ladhī wa`adtahu, [\u0027innaka lā tukhliful-mī\u0027ād]","meaning_en":"O Allah , Lord of this perfect call and established prayer. Grant Muhammad the intercession and favor, and raise him to the honored station You have promised him, [verily You do not neglect promises].","meaning_dv":"","reference":"Al-Bukhari 1/152, and the addition between brackets is from Al-Bayhaqi 1/410 with a good (Hasan) chain of narration. See \u0027Abdul-Azlz bin Baz\u0027s Tuhfatul-\u0027Akhyar, pg. 38.","source":"Hisn al-Muslim 25 - Sunnah.com","source_url":"https://sunnah.com/hisn:25","tags":["prayer"]},{"id":"hisn-26","n":26,"title":"Concerning the athan (the call to prayer)","chapter_en":"Concerning the athan (the call to prayer)","chapter_ar":"أذكار الأذان","arabic":"يَدْعُو لِنَفسِهِ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ فَإِنَّ الدُّعَاءَ حِينَئِذٍ لاَ يُرَدُّ","transliteration":"","meaning_en":"Between the call to prayer and the \u0027Iqamah, you should supplicate Allah for yourself. Invocation during this time is not rejected.","meaning_dv":"","reference":"At-Tirmidhi, Abu Dawud, Ahmed. See Irwaa Al-Ghalil 1/262","source":"Hisn al-Muslim 26 - Sunnah.com","source_url":"https://sunnah.com/hisn:26","tags":["prayer"]},{"id":"hisn-27","n":27,"title":"At the start of the prayer (after takbeer)","chapter_en":"At the start of the prayer (after takbeer)","chapter_ar":"دعاء الاستفتاح","arabic":"اللّهُـمَّ باعِـدْ بَيـني وَبَيْنَ خَطـايايَ كَما باعَدْتَ بَيْنَ المَشْرِقِ وَالمَغْرِبْ ، اللّهُـمَّ نَقِّنـي مِنْ خَطايايَ كَمـا يُـنَقَّى الثَّـوْبُ الأَبْيَضُ مِنَ الدَّنَسْ ، اللّهُـمَّ اغْسِلْنـي مِنْ خَطايـايَ بِالثَّلـجِ وَالمـاءِ وَالْبَرَدْ.","transliteration":"Allāhumma bā\u0027id baynī wa bayna khatāyāya kamā bāa\u0027adta bayn al-mashriqi wal-maghribi, Allāhumma naqqinī min khatāyāya kamā yunaqqa \u0027th-thawbu \u0027l-\u0027abyaḍu min ad-danasi, Allāhumma \u0027ghsilnī min khatāyāya, bi \u0027th-thalji wal-mā\u0027i wal-barad.","meaning_en":"O Allah, separate me from my sins as You have separated the East from the West. O Allah, cleanse me of my transgressions as the white garment is cleansed of stains. O Allah, wash away my sins with ice and water and frost.","meaning_dv":"","reference":"Al-Bukhari 1/181, Muslim 1/419.","source":"Hisn al-Muslim 27 - Sunnah.com","source_url":"https://sunnah.com/hisn:27","tags":["forgiveness","prayer","daily"]},{"id":"hisn-28","n":28,"title":"At the start of the prayer (after takbeer)","chapter_en":"At the start of the prayer (after takbeer)","chapter_ar":"دعاء الاستفتاح","arabic":"سُبْـحانَكَ اللّهُـمَّ وَبِحَمْـدِكَ وَتَبارَكَ اسْمُـكَ وَتَعـالى جَـدُّكَ وَلا إِلهَ غَيْرُك","transliteration":"Subhānaka Allāhumma wa biḥamdika, wa tabāraka \u0027smuka, wa ta\u0027ālā jadduka, wa lā \u0027ilāha ghayruk.","meaning_en":"Glory is to You O Allah, and praise. Blessed is Your Name and Exalted is Your Majesty. There is none worthy of worship but You","meaning_dv":"","reference":"Abu Dawud, Ibn Majah, An-Nasa\u0027i, At-Tirmidhi. See Al-Albani, Sahih At-Tirmidhi 1/77 and Sahih Ibn Majah 1/135.","source":"Hisn al-Muslim 28 - Sunnah.com","source_url":"https://sunnah.com/hisn:28","tags":["prayer","gratitude"]},{"id":"hisn-29","n":29,"title":"At the start of the prayer (after takbeer)","chapter_en":"At the start of the prayer (after takbeer)","chapter_ar":"دعاء الاستفتاح","arabic":"وَجَّهـتُ وَجْهِـيَ لِلَّذي فَطَرَ السَّمـواتِ وَالأَرْضَ حَنـيفَاً وَمـا أَنا مِنَ المشْرِكين ، إِنَّ صَلاتـي ، وَنُسُكي ، وَمَحْـيايَ ، وَمَماتـي للهِ رَبِّ العالَمين ، لا شَريـكَ لَهُ وَبِذلكَ أُمِرْتُ وَأَنا مِنَ المسْلِـمين. اللّهُـمَّ أَنْتَ المَلِكُ لا إِلهَ إِلاّ أَنْت، أَنْتَ رَبِّـي وَأَنـا عَبْـدُك ، ظَلَمْـتُ نَفْسـي وَاعْـتَرَفْتُ بِذَنْبـي فَاغْفِرْ لي ذُنوبي جَميعاً إِنَّـه لا يَغْـفِرُ الذُّنـوبَ إلاّ أَنْت. وَاهْدِنـي لأَحْسَنِ الأَخْلاقِ لا يَهْـدي لأَحْسَـنِها إِلاّ أَنْـت ، وَاصْـرِف عَـنّْي سَيِّئَهـا، لا يَصْرِفُ عَـنّْي سَيِّئَهـا إِلاّ أَنْـت، لَبَّـيْكَ وَسَعْـدَيْك، وَالخَـيْرُ كُلُّـهُ بِيَـدَيْـك، وَالشَّرُّ لَيْـسَ إِلَـيْك ، أَنا بِكَ وَإِلَيْـك ، تَبـارَكْتَ وَتَعـالَيتَ أَسْتَغْـفِرُكَ وَأَتوبُ إِلَـيك","transliteration":"Wajjahtu wajhiya li \u0027l-ladhî faṭara s-samāwāti wa \u0027l-arḍa, ḥanīfan wa mā ana min al-mushrikīna. Inna salāti wa nusukī, wa mahyāya wa mamātī lillāhi rabbi \u0027l-`ālamīna, lā sharīka lahu. Wa bi dhālika umirtu wa ana min al-muslimīna. Allāhumma anta \u0027l-maliku lā ilāha illā anta. Anta rabbī wa ana `abduka, ẓalamtu nafsī wa`taraftu bi dhanbī. Faghfir lī dhunūbī jamī`an, innahu lā yaghfiru \u0027dh-dhunūba illā anta. Wahdinī li-aḥsani \u0027l-akhlāqi, lā yahdī li aḥsanihā illā anta. Waṣrif `annī sayyi\u0027ahā, lā yaṣrifu `annī sayyi\u0027ahā illā anta. Labbayka wa sa`dayka, wa \u0027l-khayru kulluhu bi yadayka, wa \u0027sh-sharru laysa ilayka, ana bika wa ilayka, tabārakta wa ta`ālayta, astaghfiruka wa atūbu ilayka.","meaning_en":"\"I have turned my face sincerely towards He who has brought forth the heavens and the Earth and I am not of those who associate (others with Allah). Indeed my prayer, my sacrifice, my life and my death are for Allah, Lord of the worlds, no partner has He, with this I am commanded and I am of the Muslims. O Allah, You are the Sovereign, none has the right to be worshipped except You. You are my Lord and I am Your servant, I have wronged my own soul and have acknowledged my sin, so forgive me all my sins for no one forgives sins except You. Guide me to the best of characters for none can guide to it other than You, and deliver me from the worst of characters for none can deliver me from it other than You. Here I am, in answer to Your call, happy to serve you. All good is within Your hands and evil does not stem from You. I exist by your will and will return to you. Blessed and High are You, I seek Your forgiveness and repent unto You.\"","meaning_dv":"","reference":"Muslim 1/534","source":"Hisn al-Muslim 29 - Sunnah.com","source_url":"https://sunnah.com/hisn:29","tags":["forgiveness","protection","prayer","death"]},{"id":"hisn-30","n":30,"title":"At the start of the prayer (after takbeer)","chapter_en":"At the start of the prayer (after takbeer)","chapter_ar":"دعاء الاستفتاح","arabic":"اللّهُـمَّ رَبَّ جِـبْرائيل ، وَميكـائيل ، وَإِسْـرافيل، فاطِـرَ السَّمواتِ وَالأَرْض ، عالـِمَ الغَيْـبِ وَالشَّهـادَةِ أَنْـتَ تَحْـكمُ بَيْـنَ عِبـادِكَ فيـما كانوا فيهِ يَخْتَلِفـون. اهدِنـي لِمـا اخْتُـلِفَ فيـهِ مِنَ الْحَـقِّ بِإِذْنِك ، إِنَّـكَ تَهْـدي مَنْ تَشـاءُ إِلى صِراطٍ مُسْتَقـيم","transliteration":"Allāhumma, rabba Jibrā\u0027īla, wa Mīkā\u0027īla, wa Isrāfīla Fāṭira \u0027s-samāwāti wa \u0027l-arḍi, ` ālima \u0027l-ghaybi wa \u0027sh-shahādati, anta taḥkumu bayna `ibādika fīmā kānū fīhi yakhtalifūna. Ihdinī li makhtulifa fīhi min al-ḥaqqi bi idhnika. Innaka tahdī man tashā\u0027u ilā ṣirāṭin mustaqīm.","meaning_en":"O Allah, Lord of Jibraīl, Mīkaīl and Israfīl (great angels), Creator of the heavens and the Earth, Knower of the seen and the unseen. You are the arbitrator between Your servants in that which they have disputed. Guide me to the truth by Your leave, in that which they have differed, for verily You guide whom You will to a straight path.\"","meaning_dv":"","reference":"Muslim 1/534","source":"Hisn al-Muslim 30 - Sunnah.com","source_url":"https://sunnah.com/hisn:30","tags":["prayer"]},{"id":"hisn-31","n":31,"title":"At the start of the prayer (after takbeer)","chapter_en":"At the start of the prayer (after takbeer)","chapter_ar":"دعاء الاستفتاح","arabic":"اللهُ أَكْبَـرُ كَبـيرا ، اللهُ أَكْبَـرُ كَبـيرا ، اللهُ أَكْبَـرُ كَبـيرا ، وَالْحَـمْدُ للهِ كَثـيرا ، وَالْحَـمْدُ للهِ كَثـيرا ، وَالْحَـمْدُ للهِ كَثـيرا ، وَسُبْـحانَ اللهِ بكْـرَةً وَأَصيـلا.( ثَلاثاً ) أَعـوذُ بِاللهِ مِنَ الشَّـيْطانِ مِنْ نَفْخِـهِ وَنَفْـثِهِ وَهَمْـزِه","transliteration":"Allāhu \u0027Akbar Kabīra, Allāhu \u0027Akbar Kabīra, Allāhu \u0027Akbar Kabīra, walḥamdu lillāhi kathīra, walḥamdu lillāhi kathīra, walḥamdu lillāhi kathīra, wa Subḥānallāhi bukratan wa\u0027aṣīla.","meaning_en":"Allah is the Greatest, Most Great. Allah is the Greatest, Most Great. Allah is the Greatest, Most Great. Praise is to Allah, abundantly. Praise is to Allah, abundantly. Praise is to Allah, abundantly. Glory is to Allah, at the break of day and at its end. [Recite three times in Arabic.] I seek refuge in Allah from Satan. From his breath, and from his voice, and from his whisper.","meaning_dv":"","reference":"Abu Dawud 1/203, Ibn Majah 1/265, ai Ahmad 4/85. Muslim recorded a similar Hadil 1/420.","source":"Hisn al-Muslim 31 - Sunnah.com","source_url":"https://sunnah.com/hisn:31","tags":["protection","prayer","gratitude"]},{"id":"hisn-32","n":32,"title":"At the start of the prayer (after takbeer)","chapter_en":"At the start of the prayer (after takbeer)","chapter_ar":"دعاء الاستفتاح","arabic":"اللّهُـمَّ لَكَ الْحَمْدُ أَنْتَ نـورُ السَّمـواتِ وَالأَرْضِ وَمَنْ فيـهِن ، وَلَكَ الْحَمْدُ أَنْتَ قَـيِّمُ السَّـمواتِ وَالأَرْضِ وَمَنْ فيـهِن ، [وَلَكَ الْحَمْدُ أَنْتَ رَبُّ السَّـمواتِ وَالأَرْضِ وَمَنْ فيـهِن] [وَلَكَ الْحَمْدُ لَكَ مُلْـكُ السَّـمواتِ وَالأَرْضِ وَمَنْ فيـهِن] [وَلَكَ الْحَمْدُ أَنْتَ مَلِـكُ السَّـمواتِ وَالأَرْضِ ] [وَلَكَ الْحَمْدُ] [أَنْتَ الْحَـقّ وَوَعْـدُكَ الْحَـق ، وَقَوْلُـكَ الْحَـق ، وَلِقـاؤُكَ الْحَـق ، وَالْجَـنَّةُحَـق ، وَالنّـارُ حَـق ، وَالنَّبِـيّونَ حَـق ، وَمـحَمَّدٌ حَـق ، وَالسّـاعَةُحَـق] [اللّهُـمَّ لَكَ أَسْلَمت ، وَعَلَـيْكَ تَوَكَّلْـت ، وَبِكَ آمَنْـت ، وَإِلَـيْكَ أَنَبْـت ، وَبِـكَ خاصَمْت ، وَإِلَـيْكَ حاكَمْـت . فاغْفِـرْ لي مـا قَدَّمْتُ ، وَما أَخَّـرْت ، وَما أَسْـرَرْت ، وَما أَعْلَـنْت ] [أَنْتَ المُقَـدِّمُ وَأَنْتَ المُـؤَخِّر ، لا إِاـهَ إِلاّ أَنْـت] [أَنْـتَ إِلـهي لا إِاـهَ إِلاّ أَنْـت","transliteration":"Allāhumma lakal-ḥamdu \u0027Anta nūrussamāwāti wal\u0027arḍhi wa man fīhinna, wa lakal-ḥamdu \u0027Anta qayyimus-samāwāti wal\u0027arḍi wa man fīhinna, [wa lakal-ḥamdu \u0027Anta Rabbus-samāwāti wal\u0027arḍi wa man fīhinna] [wa lakal-ḥamdu laka mulkus-samāwāti wal\u0027arḍi wa man fīhinna] [wa lakal-ḥamdu \u0027Anta Malikus-samāwāti wal\u0027arḍi] [wa lakal-ḥamdu] [\u0027Antal-ḥaqq, wa wa`dukal-ḥaqq, wa qawlukal-ḥaqq, wa liqā\u0027ukal-ḥaqq, waljannatu ḥaqq, wannāru ḥaqq, wannabiyyūna ḥaqq, wa Muḥammadun (sallallāhu \u0027alayhi wa sallam) ḥaqq, wassā`atu ḥaqq] [Allāhumma laka \u0027aslamtu, wa `alayka tawakkaltu, wa bika \u0027āmantu, wa \u0027ilayka \u0027anabtu, wa bika khāṣamtu, wa \u0027ilayka ḥākamtu. Faghfir lī maa qaddamtu, wa mā \u0027akhkhartu, wa mā \u0027asrartu, wa mā \u0027a`lantu [\u0027Antal-Muqaddimu, wa \u0027Antal-Mu\u0027akhkhiru laa \u0027ilāha \u0027illā \u0027Anta] [\u0027Anta \u0027ilāhī lā \u0027ilāha \u0027illā \u0027Anta].","meaning_en":"O Allah, praise is to You. You are the Light of the heavens and the earth and all that they contain. Praise is to You, You are the Sustainer of the heavens and the earth and all they contain. [Praise is to You, You are the Lord of the heavens and the earth and all they contain.] [Praise is to You, Yours is dominion of the heavens and the earth and all they contain.] [Praise is to You, You are the King of the heavens and the earth.] [And praise is to You.] [You are the Truth, Your Promise is true, Your Word is true, Your audience is true, Paradise is true, Hell is true, the Prophets are true, and Muhammad (peace and blessings be upon him) is true, and the Hour of Judgment is true.] [O Allah, to You I have submitted, and upon You I depend. I have believed in You and to You I turn in repentance . For Your sake I dispute and by Your standard I judge. Forgive me what I have sent before me and what I have left behind me, what I have concealed and what I have declared.] [You are the One Who sends forth and You are the One Who delays, there is none who has the right to be worshipped but You.] [You are my God, there is none who has the right to be worshipped but You.]","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 3/3 , 11/ 116, 13/371, 423, 465. See also Muslim for a shorter account, 1/532.","source":"Hisn al-Muslim 32 - Sunnah.com","source_url":"https://sunnah.com/hisn:32","tags":["forgiveness","prayer","gratitude"]},{"id":"hisn-33","n":33,"title":"While bowing in prayer","chapter_en":"While bowing in prayer","chapter_ar":"دعاء الركوع","arabic":"سُبْـحانَ رَبِّـيَ الْعَظـيم (ثلاث مرات)","transliteration":"Subḥāna Rabbiyal-`Aẓīm.","meaning_en":"Glory to my Lord the Exalted (three times in Arabic)","meaning_dv":"","reference":"Abu Dawud, Ibn Majah, An-Nasa\u0027i, At-Tirmidhi, and Ahmad. See Al-Albani\u0027s Sahih At-Tirmidhi 1/83.","source":"Hisn al-Muslim 33 - Sunnah.com","source_url":"https://sunnah.com/hisn:33","tags":["prayer"]},{"id":"hisn-34","n":34,"title":"While bowing in prayer","chapter_en":"While bowing in prayer","chapter_ar":"دعاء الركوع","arabic":"سُبْـحانَكَ اللّهُـمَّ رَبَّـنا وَبِحَـمْدِك ، اللّهُـمَّ اغْفِـرْ لي","transliteration":"Subḥānaka Allāhumma Rabbanā wa biḥamdika Allāhum-maghfir lī.","meaning_en":"Glory is to You , O Allah , our Lord , and praise is Yours . O Allah , forgive me.","meaning_dv":"","reference":"Al-Bukhari 1/99, Muslim 1/350.","source":"Hisn al-Muslim 34 - Sunnah.com","source_url":"https://sunnah.com/hisn:34","tags":["forgiveness","prayer","gratitude"]},{"id":"hisn-35","n":35,"title":"While bowing in prayer","chapter_en":"While bowing in prayer","chapter_ar":"دعاء الركوع","arabic":"سُبـّوحٌ قُـدّْوس ، رَبُّ الملائِكَـةِ وَالـرُّوح","transliteration":"Subbūḥun, Quddūsun, Rabbul-malā\u0027ikati warrūḥ.","meaning_en":"Glory (to You) , Most Holy (are You) , Lord of the angels and the Spirit.","meaning_dv":"","reference":"Muslim 1/353, Abu Dawud 1/230.","source":"Hisn al-Muslim 35 - Sunnah.com","source_url":"https://sunnah.com/hisn:35","tags":["prayer"]},{"id":"hisn-36","n":36,"title":"While bowing in prayer","chapter_en":"While bowing in prayer","chapter_ar":"دعاء الركوع","arabic":"اللّهُـمَّ لَكَ رَكَـعْتُ وَبِكَ آمَـنْت، ولَكَ أَسْلَـمْت ، خَشَـعَ لَكَ سَمْـعي، وَبَصَـري ، وَمُخِّـي، وَعَظْمـي، وَعَصَـبي ، وَما استَقَـلَّ بِهِ قَدَمي","transliteration":"Allāhumma laka raka`tu, wa bika \u0027āmantu, wa laka \u0027aslamtu khasha`a laka sam`ee wa baṣarī, wa mukhkhī, wa `aẓmī, wa `aṣabī, wa mastaqalla bihi qadamī.","meaning_en":"O Allah , to You I bow (in prayer) and in You I believe and to You I have submitted. Before You my hearing is humbled, and my sight, and my mind, my bones, my nerves and what my feet have mounted upon (for travel).","meaning_dv":"","reference":"Muslim 1/534, Abu Dawud, An-Nasa\u0027i and At- Tirmidhi.","source":"Hisn al-Muslim 36 - Sunnah.com","source_url":"https://sunnah.com/hisn:36","tags":["travel","prayer"]},{"id":"hisn-37","n":37,"title":"While bowing in prayer","chapter_en":"While bowing in prayer","chapter_ar":"دعاء الركوع","arabic":"سُبْـحانَ ذي الْجَبَـروت، والمَلَـكوت، وَالكِبْـرِياء، وَالْعَظَـمَةِ","transliteration":"Subḥāna dhil-jabarūti, walmalakūti, walkibriyā\u0027i, wal`aẓamati.","meaning_en":"Glory is to You, Master of power, of dominion, of majesty and greatness.","meaning_dv":"","reference":"Abu Dawud 1/230, An-Nasa\u0027i and Ahmad. Its chain of narration is good (Hasan).","source":"Hisn al-Muslim 37 - Sunnah.com","source_url":"https://sunnah.com/hisn:37","tags":["prayer"]},{"id":"hisn-38","n":38,"title":"Upon rising from the bowing position","chapter_en":"Upon rising from the bowing position","chapter_ar":"دعاء الرفع من الركوع","arabic":"سَمِـعَ اللهُ لِمَـنْ حَمِـدَه","transliteration":"Sami`allāhu liman ḥamidah.","meaning_en":"Allah hears whoever praises Him.","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 2/282.","source":"Hisn al-Muslim 38 - Sunnah.com","source_url":"https://sunnah.com/hisn:38","tags":["forgiveness","prayer","gratitude"]},{"id":"hisn-39","n":39,"title":"Upon rising from the bowing position","chapter_en":"Upon rising from the bowing position","chapter_ar":"دعاء الرفع من الركوع","arabic":"رَبَّنـا وَلَكَ الحَمْـدُ حَمْـداً كَثـيراً طَيِّـباً مُـبارَكاً فيه","transliteration":"Rabbanā wa lakal-ḥamd, ḥamdan kathīran ṭayyiban mubārakan fīh.","meaning_en":"Our Lord, praise is Yours, abundant, good and blessed praise.","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 2/284.","source":"Hisn al-Muslim 39 - Sunnah.com","source_url":"https://sunnah.com/hisn:39","tags":["forgiveness","prayer","gratitude"]},{"id":"hisn-40","n":40,"title":"Upon rising from the bowing position","chapter_en":"Upon rising from the bowing position","chapter_ar":"دعاء الرفع من الركوع","arabic":"مِلْءَ السَّمـواتِ وَمِلْءَ الأَرْض، وَما بَيْـنَهُمـا ، وَمِلْءَ ما شِئْـتَ مِنْ شَيءٍ بَعْـد . أَهـلَ الثَّـناءِ وَالمَجـد ، أََحَـقُّ ما قالَ العَبْـد ، وَكُلُّـنا لَكَ عَـبد . اللّهُـمَّ لا مانِعَ لِما أَعْطَـيْت ، وَلا مُعْطِـيَ لِما مَنَـعْت ، وَلا يَنْفَـعُ ذا الجَـدِّ مِنْـكَ الجَـد","transliteration":"Mil\u0027a \u0027s-samāwāti wa mil\u0027a \u0027l-\u0027arḍi wa mā baynahumā, wa mil\u0027a mā shi\u0027ta min shay\u0027in ba`d. \u0027Ahla \u0027th-thanā\u0027i wa \u0027l-majdi, \u0027aḥaqqu mā qāla \u0027l-`abdu, wa kullunā laka `abdun. Allāhumma lā māni`a limā \u0027a`ṭayta, wa lā mu`ṭiya limā mana`ta, wa lā yanfa`u dhal-jaddi minka \u0027l-jadd. .","meaning_en":"(A praise that) fills the heavens and the earth and what lies between them, and whatever else You please. (You Allah) are most worthy of praise and majesty, and what the slave has said - we are all Your slaves. O Allah, there is none who can withhold what You give, and none may give what You have withheld. And the might of the mighty person cannot benefit him against You.","meaning_dv":"","reference":"Muslim 1/346.","source":"Hisn al-Muslim 40 - Sunnah.com","source_url":"https://sunnah.com/hisn:40","tags":["forgiveness","prayer","gratitude"]},{"id":"hisn-41","n":41,"title":"While prostrating","chapter_en":"While prostrating","chapter_ar":"دعاء السجود","arabic":"سُبْـحانَ رَبِّـيَ الأَعْلـى. (ثلاث مرات)","transliteration":"Subḥāna Rabbiya ‘l-a`lā.","meaning_en":"Glory is to my Lord, the Most High. (This is said three times in Arabic.)","meaning_dv":"","reference":"Abu Dawud, Ibn Majah, An-Nasa\u0027i, At-Tirmidhi, and Ahmad. See also Al-Albani, Sahih At-Tirmidhi 1/83.","source":"Hisn al-Muslim 41 - Sunnah.com","source_url":"https://sunnah.com/hisn:41","tags":["prayer"]},{"id":"hisn-42","n":42,"title":"While prostrating","chapter_en":"While prostrating","chapter_ar":"دعاء السجود","arabic":"سُبْـحانَكَ اللّهُـمَّ رَبَّـنا وَبِحَـمْدِكَ ، اللّهُـمَّ اغْفِرْ لي","transliteration":"Subḥānaka Allāhumma Rabbanā wa biḥamdika Allāhumma ‘ghfir lī.","meaning_en":"Glory is to You, O Allah, our Lord, and praise is Yours. O Allah, forgive me.","meaning_dv":"","reference":"Al-Bukhari and Muslim, see invocation no. 34 above.","source":"Hisn al-Muslim 42 - Sunnah.com","source_url":"https://sunnah.com/hisn:42","tags":["forgiveness","prayer","gratitude"]},{"id":"hisn-43","n":43,"title":"While prostrating","chapter_en":"While prostrating","chapter_ar":"دعاء السجود","arabic":"سُبـّوحٌ قُـدّوس، رَبُّ الملائِكَـةِ وَالـرُّوح","transliteration":"Subbūḥun, Quddūsun, Rabbu ‘l-malā\u0027ikati warrūḥ.","meaning_en":"Glory (to You), Most Holy (are You), Lord of the angels and the Spirit.","meaning_dv":"","reference":"Muslim 1/533, see invocation no. 35 above.","source":"Hisn al-Muslim 43 - Sunnah.com","source_url":"https://sunnah.com/hisn:43","tags":["prayer"]},{"id":"hisn-44","n":44,"title":"While prostrating","chapter_en":"While prostrating","chapter_ar":"دعاء السجود","arabic":"اللّهُـمَّ لَكَ سَـجَدْتُ وَبِـكَ آمَنْـت ، وَلَكَ أَسْلَـمْت ، سَجَـدَ وَجْهـي للَّـذي خَلَقَـهُ وَصَـوَّرَهُ وَشَقَّ سَمْـعَـهُ وَبَصَـرَه ، تَبـارَكَ اللهُ أَحْسـنُ الخـالِقيـن","transliteration":"Allāhumma laka sajadtu wa bika āmantu, wa laka aslamtu, sajada waj’hiya lilladhī khalaqahu, wa ṣawwarahu, wa shaqqa sam`ahu wa baṣarahu, tabārakallāhu \u0027aḥsanul-khāliqīn.","meaning_en":"O Allah, to You I prostrate myself and in You I believe. To You I have submitted. My face is prostrated to the One Who created it, fashioned it, and gave it hearing and sight. Blessed is Allah, the Best of creators","meaning_dv":"","reference":"Muslim 1/534 and others.","source":"Hisn al-Muslim 44 - Sunnah.com","source_url":"https://sunnah.com/hisn:44","tags":["prayer"]},{"id":"hisn-45","n":45,"title":"While prostrating","chapter_en":"While prostrating","chapter_ar":"دعاء السجود","arabic":"سُبْـحانَ ذي الْجَبَـروت، والمَلَكـوت، والكِبْـرِياء، وَالعَظَمَـةِ.","transliteration":"Subḥāna dhi ’l-jabarūti, wa ’l-malakūti, wa ‘l-kibriyā\u0027i, wa ‘l-aẓamati.","meaning_en":"Glory is to the master of power, sovereignty, of majesty and greatness.","meaning_dv":"","reference":"Abu Dawud 1/230, An-Nasa\u0027i, Ahmad. See also Al-Albani, Sahih Abu Dawud 1/166, see invocation no. 37 above.","source":"Hisn al-Muslim 45 - Sunnah.com","source_url":"https://sunnah.com/hisn:45","tags":["prayer"]},{"id":"hisn-46","n":46,"title":"While prostrating","chapter_en":"While prostrating","chapter_ar":"دعاء السجود","arabic":"اللّهُـمَّ اغْفِـرْ لي ذَنْـبي كُلَّـه ، دِقَّـهُ وَجِلَّـه ، وَأَوَّلَـهُ وَآخِـرَه ، وَعَلانِيَّتَـهُ وَسِـرَّه","transliteration":"Allāhumma’ghfir lī dhanbī kullahu, diqqahu wa jillahu, wa awwalahu wa ākhirahu wa `alāniyyatahu wa sirrahu.","meaning_en":"O Allah, forgive me all my sins, great and small, the first and the last, those that are apparent and those that are hidden.","meaning_dv":"","reference":"Muslim 1/350.","source":"Hisn al-Muslim 46 - Sunnah.com","source_url":"https://sunnah.com/hisn:46","tags":["forgiveness","prayer"]},{"id":"hisn-47","n":47,"title":"While prostrating","chapter_en":"While prostrating","chapter_ar":"دعاء السجود","arabic":"اللّهُـمَّ إِنِّـي أَعـوذُ بِرِضـاكَ مِنْ سَخَطِـك ، وَبِمعـافاتِـكَ مِنْ عُقوبَـتِك ، وَأَعـوذُ بِكَ مِنْـك ، لا أُحْصـي ثَنـاءً عَلَـيْك ، أَنْـتَ كَمـا أَثْنَـيْتَ عَلـى نَفْسـِك","transliteration":"Allāhumma innī a`ūdhu biriḍāka min sakhaṭika, wa bimu`āfātika min `uqūbatika wa a`ūdhu bika minka lā uḥṣī thanā\u0027an `alayka anta kamā athnayta `alā nafsika.","meaning_en":"O Allah, I seek protection in Your pleasure from Your anger, and I seek protection in Your forgiveness from Your punishment. I seek protection in You from You. I cannot count Your praises. You are as You have praised Yourself.","meaning_dv":"","reference":"Muslim 1/352.","source":"Hisn al-Muslim 47 - Sunnah.com","source_url":"https://sunnah.com/hisn:47","tags":["forgiveness","protection","prayer","daily","gratitude"]},{"id":"hisn-48","n":48,"title":"Between the two prostrations","chapter_en":"Between the two prostrations","chapter_ar":"دعاء الجلسة بين السجدتين","arabic":"رَبِّ اغْفِـرْ لي ، رَبِّ اغْفِـرْ لي","transliteration":"Rabbi’ghfir lī, Rabbi’ghfir lī.","meaning_en":"Lord, forgive me. My Lord, forgive me.","meaning_dv":"","reference":"Abu Dawud 1/231. See also Al-Albani, Sahihibn Mdjah 1/148.","source":"Hisn al-Muslim 48 - Sunnah.com","source_url":"https://sunnah.com/hisn:48","tags":["forgiveness","prayer"]},{"id":"hisn-49","n":49,"title":"Between the two prostrations","chapter_en":"Between the two prostrations","chapter_ar":"دعاء الجلسة بين السجدتين","arabic":"اللّهُـمَّ اغْفِـرْ لي ، وَارْحَمْـني ، وَاهْدِنـي ، وَاجْبُرْنـي ، وَعافِنـي وَارْزُقْنـي وَارْفَعْـني","transliteration":"Allāhumma’ghfir lī, war’ḥamnī, wahdinī, wajburnī, wa `āfinī, warzuqnī, warfa`nī.","meaning_en":"O Allah forgive me, have mercy on me, guide me, support me, protect me, provide for me, and elevate me.","meaning_dv":"","reference":"Abu Dawud, Ibn Majah, At-Tirmidhi. See also Al-Albani, Sahih At-Tirmidhi 1/90 and Sahih Ibn Majah 1/148.","source":"Hisn al-Muslim 49 - Sunnah.com","source_url":"https://sunnah.com/hisn:49","tags":["forgiveness","prayer"]},{"id":"hisn-50","n":50,"title":"When prostrating due to recitation of the Quran","chapter_en":"When prostrating due to recitation of the Quran","chapter_ar":"دعاء سجود التلاوة","arabic":"سَجَـدَ وَجْهـي للَّـذي خَلَقَـهُ وَشَقَّ سَمْـعَـهُ وَبَصَـرَهُ بِحَـوْلِـهِ وَقُـوَّتِهِ ﴿فتَبـارَكَ اللهُ أَحْسَـنُ الخـالِقيـن﴾.","transliteration":"Sajada wajhiya lilladhī khalaqahu, wa shaqqa sam`ahu wa baṣarahu biḥawlihi wa quwwatihi. Fatabārakallāhu \u0027aḥsanul-khāliqīn.","meaning_en":"I have prostrated my face to the One Who created it, and gave it hearing and sight by His might and His power. Glory is to Allah, the Best of creators.","meaning_dv":"","reference":"At-Tirmidhi 2/474, Ahmad 6/30, and Al-Hakim","source":"Hisn al-Muslim 50 - Sunnah.com","source_url":"https://sunnah.com/hisn:50","tags":["prayer"]},{"id":"hisn-51","n":51,"title":"When prostrating due to recitation of the Quran","chapter_en":"When prostrating due to recitation of the Quran","chapter_ar":"دعاء سجود التلاوة","arabic":"اللّهُـمَّ اكْتُـبْ لي بِهـا عِنْـدَكَ أَجْـراً ، وَضَـعْ عَنِّـي بِهـا وِزْراً ، وَاجْعَـلها لي عِنْـدَكَ ذُخْـراً ، وَتَقَبَّـلها مِنِّي كَمَا تَقَبَّلْتَهَا مِنْ عَبْدِكَ دَاوُدَ.","transliteration":"Allāhummak’tub lī bihā `indaka ajra, waḍa` `annī bihā wizra, waj`alhā lī `indaka dhukhra, wa taqabbal’hā minnī kamā taqabbal’tahā min `abdika Dāwūd.","meaning_en":"O Allah, write it as a reward for me, and release me from a burden for it, and make it a treasure for me with You. Accept it from me as You accepted it from your servant Dawud.","meaning_dv":"","reference":"At-Tirmidhi 2/473, and Al-Hakim who graded it authentic and Ath-Thahabi agreed 1/219.","source":"Hisn al-Muslim 51 - Sunnah.com","source_url":"https://sunnah.com/hisn:51","tags":["prayer"]},{"id":"hisn-52","n":52,"title":"The Tashahhud","chapter_en":"The Tashahhud","chapter_ar":"التشهد","arabic":"التَّحِيّـاتُ للهِ وَالصَّلَـواتُ والطَّيِّـبات ، السَّلامُ عَلَيـكَ أَيُّهـا النَّبِـيُّ وَرَحْمَـةُ اللهِ وَبَرَكـاتُه ، السَّلامُ عَلَيْـناوَعَلـى عِبـادِ للهِ الصَّـالِحـين . أَشْـهَدُ أَنْ لا إِلـهَ إِلاّ الله ، وَأَشْـهَدُ أَنَّ مُحَمّـداً عَبْـدُهُ وَرَسـولُه","transliteration":"Attaḥiyyātu lillāhi waṣṣalawātu, waṭṭayyibāt, assalāmu `alayka \u0027ayyuhan-Nabiyyu wa raḥmatullāhi wa barakātuh, assalāmu `alaynā wa `alā ‘ibādillāhiṣ-ṣāliḥīn. \u0027Ash-hadu \u0027an lā \u0027ilāha \u0027illallāh wa \u0027ash-hadu \u0027anna Muḥammadan `abduhu wa rasūluh.","meaning_en":"All greetings of humility are for Allah, and all prayers and goodness. Peace be upon you, O Prophet, and the mercy of Allah and His blessings. Peace be upon us and upon the righteous slaves of Allah. I bear witness that there is none worthy of worship but Allah, and I bear witness that Muhammad is His slave and His Messenger.","meaning_dv":"","reference":"Al-Bukhari, Muslim 1/301. See also Al-Asqalani, Fathul-Bal 1/13","source":"Hisn al-Muslim 52 - Sunnah.com","source_url":"https://sunnah.com/hisn:52","tags":["forgiveness","prayer","gratitude"]},{"id":"hisn-53","n":53,"title":"Prayers upon the Prophet ﷺ after the tashahhud","chapter_en":"Prayers upon the Prophet ﷺ after the tashahhud","chapter_ar":"الصلاة على النبي ﷺ بعد التشهد","arabic":"اللّهُـمَّ صَلِّ عَلـى مُحمَّـد، وَعَلـى آلِ مُحمَّد، كَمـا صَلَّيـتَ عَلـى إبْراهـيمَ وَعَلـى آلِ إبْراهـيم، إِنَّكَ حَمـيدٌ مَجـيد ، اللّهُـمَّ بارِكْ عَلـى مُحمَّـد، وَعَلـى آلِ مُحمَّـد، كَمـا بارِكْتَ عَلـى إبْراهـيمَ وَعَلـى آلِ إبْراهيم، إِنَّكَ حَمـيدٌ مَجـيد","transliteration":"Allāhumma ṣalli `alā Muḥammadinwa `alā ’āli Muḥammadin, kamā ṣallayta `alā \u0027Ibrāhīma wa `alā ’āli \u0027Ibrāhīma, \u0027innaka ḥamīdum-majīd. Allāhumma bārik `alā Muḥammadin wa `alā ’āli Muḥammadin, kamā bārakta `alā \u0027Ibrāhīma wa `alā \u0027āli \u0027Ibrāhīma, \u0027innaka ḥamīdum-majīd.","meaning_en":"O Allah, bestow Your favor on Muhammad and on the family of Muhammad as You have bestowed Your favor on Ibrahim and on the family of Ibrahim, You are Praiseworthy, Most Glorious. O Allah, bless Muhammad and the family of Muhammad as You have blessed Ibrahim and the family of Ibrahim, You are Praiseworthy, Most Glorious.","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 6/408.","source":"Hisn al-Muslim 53 - Sunnah.com","source_url":"https://sunnah.com/hisn:53","tags":["family","prayer","gratitude"]},{"id":"hisn-54","n":54,"title":"Prayers upon the Prophet ﷺ after the tashahhud","chapter_en":"Prayers upon the Prophet ﷺ after the tashahhud","chapter_ar":"الصلاة على النبي ﷺ بعد التشهد","arabic":"اللّهُـمَّ صَلِّ عَلـى مُحمَّـدٍ وَعَلـى أَزْواجِـهِ وَذُرِّيَّـتِه، كَمـا صَلَّيْـتَ عَلـى آلِ إبْراهـيم . وَبارِكْ عَلـى مُحمَّـدٍ وَعَلـى أَزْواجِـهِ وَذُرِّيَّـتِه، كَمـا بارِكْتَ عَلـى آلِ إبْراهـيم . إِنَّكَ حَمـيدٌ مَجـيد","transliteration":"Allāhumma ṣalli `alā Muḥammadin wa `alā \u0027azwājihi wa dhurriyyatihi, kamā ṣallayta `alā \u0027āli \u0027Ibrāhīma. Wa bārik `alā Muḥammadin wa `alā \u0027azwājihi wa dhurriyyatihi, kamā bārakta `alā \u0027āli \u0027Ibrāhīma. \u0027Innaka ḥamīdum-majīd.","meaning_en":"O Allah, bestow Your favor on Muhammad and upon his wives and progeny as You have bestowed Your favor upon the family of Ibrahim. And bless Muhammad and his wives and progeny as You have blessed the family of Ibrahim, You are full of praise, Most Glorious.","meaning_dv":"","reference":"Al-Bukhari, from Al-Asqalani, Fathul-Bari 6/ 407, Muslim 1/306.","source":"Hisn al-Muslim 54 - Sunnah.com","source_url":"https://sunnah.com/hisn:54","tags":["family","prayer","gratitude"]},{"id":"hisn-55","n":55,"title":"After the last tashahhud and before salam","chapter_en":"After the last tashahhud and before salam","chapter_ar":"الدعاء بعد التشهد الأخير وقبل السلام","arabic":"اللّهُـمَّ إِنِّـي أَعـوذُ بِكَ مِـنْ عَذابِ القَـبْر، وَمِـنْ عَذابِ جَهَـنَّم، وَمِـنْ فِتْـنَةِ المَحْـيا وَالمَمـات، وَمِـنْ شَـرِّ فِتْـنَةِ المَسيحِ الدَّجّال","transliteration":"Allāhumma ‘innī ‘a`ūdhu bika min `adhābi ‘l-qabri, wa min `adhābi jahannam, wa min fitnati ‘l-maḥyā wa ‘l-mamāti, wa min sharri fitnati ‘l-masīḥid-dajjāl.","meaning_en":"O Allah, I seek refuge in You from the punishment of the grave, and from the punishment of Hell-fire, and from the trials of life and death, and from the evil of the trial of the False Messiah.","meaning_dv":"","reference":"Al-Bukhari 2/102, Muslim 1/412, and this is Muslim\u0027s wording.","source":"Hisn al-Muslim 55 - Sunnah.com","source_url":"https://sunnah.com/hisn:55","tags":["patience","protection","prayer","death"]},{"id":"hisn-56","n":56,"title":"After the last tashahhud and before salam","chapter_en":"After the last tashahhud and before salam","chapter_ar":"الدعاء بعد التشهد الأخير وقبل السلام","arabic":"اللّهُـمَّ إِنِّـي أَعـوذُ بِكَ مِـنْ عَذابِ القَـبْر ، وَأَعـوذُ بِكَ مِـنْ فِتْـنَةِ المَسيحِ الدَّجّـال ، أَعـوذُ بِكَ مِـنْ فِتْـنَةِ المَحْـيا وَالمَمـات . اللّهُـمَّ إِنِّـي أَعـوذُ بِكَ مِنَ المَأْثَـمِ وَالمَغْـرَم","transliteration":"Allāhumma \u0027innī ‘a`ūdhu bika min `adhābi ‘l-qabr, wa ‘a`ūdhu bika min fitnati ‘l-masīḥid-dajjāl, wa ‘a`ūdhu bika min fitnati ‘l-maḥyā wa ‘l-mamāt. Allāhumma ‘innī ‘a`ūdhu bika mina ‘l-m’athami wa ‘l-maghram.","meaning_en":"O Allah, I seek refuge in You from the punishment of the grave, and I seek refuge in You from the trial of the False Messiah, and I seek refuge in You from the trials of life and death. O Allah, I seek refuge in You from sin and from debt.","meaning_dv":"","reference":"Al-Bukhari 1/202, Muslim 1/412.","source":"Hisn al-Muslim 56 - Sunnah.com","source_url":"https://sunnah.com/hisn:56","tags":["forgiveness","financial","patience","protection","prayer","death"]},{"id":"hisn-57","n":57,"title":"After the last tashahhud and before salam","chapter_en":"After the last tashahhud and before salam","chapter_ar":"الدعاء بعد التشهد الأخير وقبل السلام","arabic":"اللّهُـمَّ إِنِّـي ظَلَـمْتُ نَفْسـي ظُلْمـاً كَثـيراً وَلا يَغْـفِرُ الذُّنـوبَ إِلاّ أَنْت، فَاغْـفِر لي مَغْـفِرَةً مِنْ عِنْـدِك وَارْحَمْـني، إِنَّكَ أَنْتَ الغَـفورُ الرَّحـيم","transliteration":"Allāhumma ‘innī ẓalamtu nafsī ẓulman kathīran, wa lā yaghfiru-dhdhunūba illā \u0027anta, faghfir lī maghfiratam’min `indika warḥamnī innaka \u0027anta ‘l-Ghafūr ur-Rahīm.","meaning_en":"O Allah, I have greatly wronged myself, and no one forgives sins but You. So, grant me forgiveness and have mercy on me. Surely, you are Forgiving, Merciful.","meaning_dv":"","reference":"Al-Bukhari 8/168, Muslim 4/2078.","source":"Hisn al-Muslim 57 - Sunnah.com","source_url":"https://sunnah.com/hisn:57","tags":["forgiveness","prayer"]},{"id":"hisn-58","n":58,"title":"After the last tashahhud and before salam","chapter_en":"After the last tashahhud and before salam","chapter_ar":"الدعاء بعد التشهد الأخير وقبل السلام","arabic":"اللّهُـمَّ اغْـفِرْ لي ما قَدَّمْـتُ وَما أَخَّرْت ، وَما أَسْـرَرْتُ وَما أَعْلَـنْت ، وَما أَسْـرَفْت ، وَما أَنْتَ أَعْـلَمُ بِهِ مِنِّي . أَنْتَ المُقَـدِّمُ، وَأَنْتَ المُـؤَخِّـرُ لا إِلهَ إِلاّ أَنْـت","transliteration":"Allāhummagh’fir lī mā qaddamtu, wa mā ‘akhkhartu, wa mā ‘asrartu, wa mā ‘a`lantu, wa mā ‘asraftu, wa mā \u0027anta ‘a`lamu bihi minnī. ‘anta ‘l-Muqaddimu, wa \u0027anta ‘l-Mu‘akhkhiru lā \u0027ilāha \u0027illā \u0027anta.","meaning_en":"O Allah, forgive me what I have sent before me and what I have left behind me, what I have concealed and what I have done openly, what I have done in excess, and what You are better aware of than I. You are the One Who sends forth and You are the One Who delays. There is none worthy of worship but You.","meaning_dv":"","reference":"Muslim 1/534.","source":"Hisn al-Muslim 58 - Sunnah.com","source_url":"https://sunnah.com/hisn:58","tags":["forgiveness","prayer"]},{"id":"hisn-59","n":59,"title":"After the last tashahhud and before salam","chapter_en":"After the last tashahhud and before salam","chapter_ar":"الدعاء بعد التشهد الأخير وقبل السلام","arabic":"اللّهُـمَّ أَعِـنِّي عَلـى ذِكْـرِكَ وَشُكْـرِك ، وَحُسْـنِ عِبـادَتِـك","transliteration":"Allāhumma ‘a`innī `alā dhikrika, wa shukrika, wa ḥusni `ibādatik.","meaning_en":"O Allah, help me to remember You, to give You thanks, and to perform Your worship in the best manner.","meaning_dv":"","reference":"Abu Dawud 2/86, An-Nasa\u0027i 3/53. See also Al-Albani Sahih Abu Dawud 1 /284.","source":"Hisn al-Muslim 59 - Sunnah.com","source_url":"https://sunnah.com/hisn:59","tags":["prayer","gratitude"]},{"id":"hisn-60","n":60,"title":"After the last tashahhud and before salam","chapter_en":"After the last tashahhud and before salam","chapter_ar":"الدعاء بعد التشهد الأخير وقبل السلام","arabic":"اللّهُـمَّ إِنِّـي أَعوذُ بِكَ مِنَ البُخْـل، وَأَعوذُ بِكَ مِنَ الجُـبْن، وَأَعوذُ بِكَ مِنْ أَنْ أُرَدَّ إِلى أَرْذَلِ الـعُمُر، وَأََعوذُ بِكَ مِنْ فِتْنَـةِ الدُّنْـيا وَعَـذابِ القَـبْر","transliteration":"Allāhumma \u0027innī ‘a`udhu bika mina ‘l-bukhl, wa ‘a`udhu bika mina ‘l-jubn, wa ‘a`udhu bika min ‘an ‘uradda ilā ‘ardhali ‘l-`umur, wa ‘a`udhu bika min fitnatid-dunyā wa `adhābi ‘l-qabr.","meaning_en":"O Allah, I seek Your protection from miserliness, I seek Your protection from cowardice, and I seek Your protection from being returned to feeble old age. I seek Your protection from the trials of this world and from the torment of the grave.","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 6/35","source":"Hisn al-Muslim 60 - Sunnah.com","source_url":"https://sunnah.com/hisn:60","tags":["patience","protection","prayer","death"]},{"id":"hisn-61","n":61,"title":"After the last tashahhud and before salam","chapter_en":"After the last tashahhud and before salam","chapter_ar":"الدعاء بعد التشهد الأخير وقبل السلام","arabic":"اللّهُـمَّ إِنِّـي أَسْأَلُـكَ الجَـنَّةَ وأََعوذُ بِـكَ مِـنَ الـنّار","transliteration":"Allāhumma innī as\u0027aluka ‘l-jannah wa a`ūdhu bika minan-nār.","meaning_en":"O Allah, I ask You for Paradise, and I seek Your protection from the Fire.","meaning_dv":"","reference":"Abu Dawud. See also Al-Albani, Sahih Ibn Majah 2/328.","source":"Hisn al-Muslim 61 - Sunnah.com","source_url":"https://sunnah.com/hisn:61","tags":["protection","prayer"]},{"id":"hisn-62","n":62,"title":"After the last tashahhud and before salam","chapter_en":"After the last tashahhud and before salam","chapter_ar":"الدعاء بعد التشهد الأخير وقبل السلام","arabic":"اللّهُـمَّ بِعِلْـمِكَ الغَـيْبِ وَقُـدْرَتِـكَ عَلـى الْخَلقِ أَحْـيِني ما عَلِـمْتَ الحـياةَ خَـيْراً لـي، وَتَوَفَّـني إِذا عَلِـمْتَ الوَفـاةَ خَـيْراً لـي، اللّهُـمَّ إِنِّـي أَسْـأَلُـكَ خَشْيَتَـكَ في الغَـيْبِ وَالشَّهـادَةِ، وَأَسْـأَلُـكَ كَلِمَـةَ الحَـقِّ في الرِّضـا وَالغَضَـب، وَأَسْـأَلُـكَ القَصْدَ في الغِنـى وَالفَقْـر، أَسْـأَلُـكَ نَعـيماً لا يَنْفَـد، وَأَسْـأَلُـكَ قُـرَّةَ عَيْـنٍ لا تَنْـقَطِعْ وَأَسْـأَلُـكَ الرِّضـا بَعْـدَ القَضـاء، وَأَسْـأَلُـكَ بًـرْدَ الْعَـيْشِ بَعْـدَ الْمَـوْت، وَأَسْـأَلُـكَ لَـذَّةَ النَّظَـرِ إِلـى وَجْـهِكَ وَالشَّـوْقَ إِلـى لِقـائِـك، في غَـيرِ ضَـرّاءَ مُضِـرَّة، وَلا فِتْـنَةٍ مُضـلَّة، اللّهُـمَّ زَيِّـنّا بِزينَـةِ الإيـمان، وَاجْـعَلنا هُـداةً مُهْـتَدين","transliteration":"Allāhumma bi `ilmika ‘l-ghayb, wa qudratika `ala ‘l-khalq, aḥyinī mā `alimta ‘l-ḥayāta khayran lī, wa tawaffanī idhā `alimta ‘l-wafāta khayran lī, Allāhumma innī as\u0027aluka khash’yataka fil-ghaybi wash-shahādah, wa as\u0027aluka kalimata ‘l-ḥaqqi fir-riḍā wa ‘l-ghaḍab, wa as\u0027aluka ‘l-qaṣda fil-ghinā wa ‘l-faqr, wa as\u0027aluka na`īman lā yanfad, wa as\u0027aluka qurrata `aynin lā tanqati`, wa as\u0027alukar-riḍā ba`dal-qaḍā\u0027, wa as\u0027aluka barda ‘l-`ayshi ba`da ‘l-mawt, wa as\u0027aluka ladh-dhatan-naẓari ilā wajhik, wash-shawqa ilā liqā\u0027ik, fī ghayri ḍarrā\u0027a muḍirrah, wa lā fitnatin muḍillah, Allāhumma zayyinnā bi zīnati ‘l-\u0027īmān, waj`alnā hudātan muhtadīn.","meaning_en":"O Allah, by Your Knowledge of the unseen and by Your Power over creation, let me live if You know that life is good for me, and let me die if You know that death is good for me. O Allah, I ask You to grant me fear of You in private and in public. I ask you for the word of truth in times of contentment and anger. I ask You for moderation in wealth and in poverty. I ask you for blessings never ceasing and the coolness of my eye (i.e. pleasure) that never ends. I ask You for pleasure after Your Judgment and I ask You for a life of coolness after death. I ask You for the delight of gazing upon Your Face, and the joy of meeting You, without any harm and misleading trials befalling me. O Allah, dress us with the beauty of Faith and make us guides who are upon (correct) guidance.","meaning_dv":"","reference":"An-Nasa\u0027i 3/54, 55, Ahmad 4/364. See also Al-Albani, Sahih An-Nasa\u0027i 1/281.","source":"Hisn al-Muslim 62 - Sunnah.com","source_url":"https://sunnah.com/hisn:62","tags":["anxiety","forgiveness","financial","patience","protection","prayer","daily","gratitude","death"]},{"id":"hisn-63","n":63,"title":"After the last tashahhud and before salam","chapter_en":"After the last tashahhud and before salam","chapter_ar":"الدعاء بعد التشهد الأخير وقبل السلام","arabic":"اللّهُـمَّ إِنِّـي أَسْأَلُـكَ يا اللهُ بِأَنَّـكَ الواحِـدُ الأَحَـد الصَّـمَدُ الَّـذي لَـمْ يَلِـدْ وَلَمْ يولَدْ، وَلَمْ يَكـنْ لَهُ كُـفُواً أَحَـد ، أَنْ تَغْـفِرْ لي ذُنـوبي إِنَّـكَ أَنْـتَ الغَفـورُ الرَّحِّـيم","transliteration":"Allāhumma innī as\u0027aluka yā Allāh bi\u0027annaka ‘l-Wāḥidu ‘l-Aḥaduṣ-ṣamad, alladhī lam yalid wa lam yūlad, wa lam yakun lahu kufuwan aḥad, an taghfir lī dhunūbī, innaka anta ‘l-Ghafūrur-Raḥīm.","meaning_en":"O Allah, I ask You. O Allah, You are the One, the Only, Self-Sufficient Master, Who was not begotten and begets not, and none is equal to Him. Forgive me my sins, surely you are Forgiving, Merciful.","meaning_dv":"","reference":"An-Nasa\u0027i 3/52, Ahmad 4/338. See also Al-Albani, Sahih An-Nasa\u0027i 1/280 and Sifat Salatun-Nabi, pg. 204.","source":"Hisn al-Muslim 63 - Sunnah.com","source_url":"https://sunnah.com/hisn:63","tags":["forgiveness","prayer"]},{"id":"hisn-64","n":64,"title":"After the last tashahhud and before salam","chapter_en":"After the last tashahhud and before salam","chapter_ar":"الدعاء بعد التشهد الأخير وقبل السلام","arabic":"اللّهُـمَّ إِنِّـي أَسْأَلُـكَ بِأَنَّ لَكَ الْحَـمْدُ لا إِلـهَ إِلاّ أَنْـتَ وَحْـدَكَ لا شَـريكَ لَـكَ المَنّـانُ يا بَديـعَ السَّمواتِ وَالأَرْضِ يا ذا الجَلالِ وَالإِكْـرام يا حَـيُّ يا قَـيّومُ إِنِّـي أَسْأَلُـكَ الجَـنَّةَ وَأَعـوذُ بِـكَ مِنَ الـنّار","transliteration":"Allāhumma innī as\u0027aluka bi\u0027anna laka ‘l-ḥamd, lā ilāha illā ant, waḥdaka lā sharīka lak, al-Mannān, yā Badī`as-samāwāti wa ‘l-arḍ yā dha ‘l-Jalāli wa ‘l-\u0027Ikrām, yā ḥayyu yā Qayyūm, innī as\u0027aluka ‘l-jannah, wa a`ūdhu bika minan-nār.","meaning_en":"O Allah, I ask You, as You are the Owner of praise, there is none worthy of worship but You alone, You have no partner. You are the Giver of all good. O Creator of the heavens and the earth, Owner of majesty and honor. O Living and Everlasting One, I ask you for Paradise, and I seek refuge in You from the fire.","meaning_dv":"","reference":"Abu Dawud, An-Nasa\u0027i, Ibn Majah, At-Tirmidhi. See also Al-Albani, Sahih Ibn Majah 2/329.","source":"Hisn al-Muslim 64 - Sunnah.com","source_url":"https://sunnah.com/hisn:64","tags":["protection","prayer","gratitude"]},{"id":"hisn-65","n":65,"title":"After the last tashahhud and before salam","chapter_en":"After the last tashahhud and before salam","chapter_ar":"الدعاء بعد التشهد الأخير وقبل السلام","arabic":"اللّهُـمَّ إِنِّـي أَسْأَلُـكَ بِأَنَّـي أَشْـهَدُ أَنَّـكَ أنْـتَ اللهُ لا إِلـهَ إِلاّ أَنْـت الأَحَـدُ الصَّـمَدُ الَّـذي لَـمْ يَلِـدْ وَلَمْ يولَـدْ وَلَمْ يَكـنْ لَهُ كُـفُواً أَحَـد","transliteration":"Allāhumma innī as\u0027aluka bi\u0027annī ash-hadu annaka ant-Allāh lā \u0027ilāha \u0027illā ant, Al-Aḥaduṣ-ṣamad alladhī lam yalid wa lam yūlad wa lam yakun lahu kufuwan aḥad.","meaning_en":"O Allah, I ask You, by the fact that I bear witness that You are Allah. There is none worthy of worship but You, the Only God, Independent of creation, Who was not begotten and begets not, and none is equal to Him.","meaning_dv":"","reference":"Abu Dawud 2/62, Ibn Majah 2/1267, At-Tirmidhi 5/515, Ahmad 5/360. See also Al-Albani, Sahih Ibn Majah 2/329 and Sahih At-Tirmidhi 3/163.","source":"Hisn al-Muslim 65 - Sunnah.com","source_url":"https://sunnah.com/hisn:65","tags":["prayer"]},{"id":"hisn-66","n":66,"title":"After salam","chapter_en":"After salam","chapter_ar":"الأذكار بعد السلام من الصلاة","arabic":"أَسْـتَغْفِرُ الله (ثَلاثاً) اللّهُـمَّ أَنْـتَ السَّلامُ وَمِـنْكَ السَّلام تَبارَكْتَ يا ذا الجَـلالِ وَالإِكْـرام","transliteration":"Astaghfirullāh","meaning_en":"I seek the forgiveness of Allah (three times). O Allah, You are Peace and from You comes peace. Blessed are You, O Owner of majesty and honor.","meaning_dv":"","reference":"Muslim 1/414.","source":"Hisn al-Muslim 66 - Sunnah.com","source_url":"https://sunnah.com/hisn:66","tags":["forgiveness"]},{"id":"hisn-67","n":67,"title":"After salam","chapter_en":"After salam","chapter_ar":"الأذكار بعد السلام من الصلاة","arabic":"لا إلهَ إلاّ اللّهُ وحدَهُ لا شريكَ لهُ لهُ المُـلْكُ ولهُ الحَمْد وهوَ على كلّ شَيءٍ قَدير اللّهُـمَّ لا مانِعَ لِما أَعْطَـيْت وَلا مُعْطِـيَ لِما مَنَـعْت وَلا يَنْفَـعُ ذا الجَـدِّ مِنْـكَ الجَـد","transliteration":"Lā \u0027ilāha \u0027illallāh, waḥdahu lā sharīka lah, lahu ‘l-mulku wa lahu ‘l-ḥamd, wa huwa `alā kulli shay\u0027in qadīr, Allāhumma lā māni`a limā \u0027a`tayt, wa lā mu`tiya limā mana`t, wa lā yanfa`u dhal-jaddi minkal-jadd.","meaning_en":"None has the right to be worshipped but Allah alone, He has no partner, His is the dominion and His is the praise, and He is Able to do all things. O Allah, there is none who can withhold what You give, and none may give what You have withheld, and the might of the mighty person cannot benefit him against You.","meaning_dv":"","reference":"Al-Bukhari 1/255, Muslim 1/414.","source":"Hisn al-Muslim 67 - Sunnah.com","source_url":"https://sunnah.com/hisn:67","tags":["gratitude"]},{"id":"hisn-68","n":68,"title":"After salam","chapter_en":"After salam","chapter_ar":"الأذكار بعد السلام من الصلاة","arabic":"لا إلهَ إلاّ اللّه وحدَهُ لا شريكَ لهُ لهُ الملكُ ولهُ الحَمد وهوَ على كلّ شيءٍ قدير لا حَـوْلَ وَلا قـوَّةَ إِلاّ بِاللهِ لا إلهَ إلاّ اللّـه وَلا نَعْـبُـدُ إِلاّ إيّـاه لَهُ النِّعْـمَةُ وَلَهُ الفَضْل وَلَهُ الثَّـناءُ الحَـسَن لا إلهَ إلاّ اللّهُ مخْلِصـينَ لَـهُ الدِّينَ وَلَوْ كَـرِهَ الكـافِرون","transliteration":"Lā \u0027ilāha \u0027illallāh, waḥdahu lā sharīka lah, lahul-mulku, wa lahul-ḥamd, wa huwa `alā kulli shay\u0027in qadīr. Lā ḥawla wa lā quwwata \u0027illā billāh, lā \u0027ilāha \u0027illallāh, wa lā na`budu \u0027illā \u0027iyyāh, lahun-ni`matu wa lahul-faḍl, wa lahuth-thanā\u0027ul-ḥasan, lā \u0027ilāha \u0027illallāh, mukhliṣīna lahud-dīn, wa law karihal-kāfirūn.","meaning_en":"None has the right to be worshipped but Allah alone, He has no partner, His is the dominion and His is the praise and He is Able to do all things. There is no power and no might except by Allah. None has the right to be worshipped but Allah, and we do not worship any other besides Him. His is grace, and His is bounty, and to Him belongs the most excellent praise. None has the right to be worshipped but Allah. (We are) sincere in making our religious devotion to Him, even though the disbelievers may dislike it.","meaning_dv":"","reference":"Muslim 1/415.","source":"Hisn al-Muslim 68 - Sunnah.com","source_url":"https://sunnah.com/hisn:68","tags":["forgiveness","gratitude"]},{"id":"hisn-69","n":69,"title":"After salam","chapter_en":"After salam","chapter_ar":"الأذكار بعد السلام من الصلاة","arabic":"سُـبْحانَ اللهِ والحَمْـدُ لله واللهُ أكْـبَر (ثلاثاً وثلاثين) لا إلهَ إلاّ اللّهُ وَحْـدَهُ لا شريكَ لهُ لهُ الملكُ ولهُ الحَمْد وهُوَ على كُلّ شَيءٍ قَـدير","transliteration":"Subḥānallāh, walḥamdu lillāh, wallāhu \u0027akbar,","meaning_en":"Glory is to Allah, and praise is to Allah, and Allah is the Most Great. (each said thirty-three times) None has the right to be worshiped but Allah alone, He has no partner, His is the dominion and His is the praise and He is Able to do all things.","meaning_dv":"","reference":"Muslim 1/418, Whoever says this after every prayer will be forgiven his sins even though they be as the foam of the sea.","source":"Hisn al-Muslim 69 - Sunnah.com","source_url":"https://sunnah.com/hisn:69","tags":["forgiveness","prayer","gratitude"]},{"id":"hisn-70","n":70,"title":"After salam","chapter_en":"After salam","chapter_ar":"الأذكار بعد السلام من الصلاة","arabic":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ {قُلْ هُوَ اللَّهُ أَحَدٌ* اللَّهُ الصَّمَدُ* لَمْ يَلِدْ وَلَمْ يُولَدْ* وَلَمْ يَكُن لَّهُ كُفُواً أَحَدٌ} بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ* مِن شَرِّ مَا خَلَقَ* وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ* وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ* وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ} بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ {قُلْ أَعُوذُ بِرَبِّ النَّاسِ* مَلِكِ النَّاسِ* إِلَهِ النَّاسِ* مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ* الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ* مِنَ الْجِنَّةِ وَالنَّاسِ} بَعْدَ كُلِّ صَلاَةٍ.","transliteration":"Bismillāhir-Raḥmānir-Raḥīm. Qul huwallāhu aḥad. Allāhuṣ-ṣamad. Lam yalid wa lam yūlad. Wa lam yakun lahu kufuwan aḥad. Bismillāhir-Raḥmānir-Raḥīm. Qul a`ūdhu birabbil-falaq. Min sharri mā khalaq. Wa min sharri ghāsiqin idhā waqab. Wa min sharrin-naffāthāti fil-`uqad. Wa min sharri ḥāsidin idhā ḥasad. Bismillāhir-Raḥmānir-Raḥīm. Qul a`ūdhu birabbin-nās. Malikin-nās. \u0027Ilāhin-nās. Min sharri ‘l-waswāsil-khannās. Alladhī yuwaswisu fī ṣudūrin-nās. Minal-jinnati wannās.","meaning_en":"With the Name of Allah, the Most Gracious, the Most Merciful. Say:","meaning_dv":"","reference":"Abu Dawud 2/86, An-Nasa\u0027i 3/68. See also Al-Albani, Sahih At-Tirmidhi 2/8.","source":"Hisn al-Muslim 70 - Sunnah.com","source_url":"https://sunnah.com/hisn:70","tags":[]},{"id":"hisn-71","n":71,"title":"After salam","chapter_en":"After salam","chapter_ar":"الأذكار بعد السلام من الصلاة","arabic":"﴿اللّهُ لاَ إِلَـهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ لاَ تَأْخُذُهُ سِنَةٌ وَلاَ نَوْمٌ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الأَرْضِ مَن ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلاَّ بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلاَ يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلاَّ بِمَا شَاء وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالأَرْضَ وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ﴾ عقب كل صلاة","transliteration":"Allāhu lā ilāha illā huwa ‘l-Ḥayyul-Qayyūm, lā ta\u0027khudhuhu sinatun wa lā nawm, lahu mā fis-samāwāti wa mā fil-ardh, man dhal-ladhī yashfa`u `indahu illā bi\u0027idhnih, ya`lamu mā bayna \u0027aydīhim wa mā khalfahum, wa lā yuḥītūna bishay\u0027im-min `ilmihi illā bimā shā\u0027a, wasi `a kursiyyuhus-samāwāti wal-ardh, wa lā ya\u0027ūduhu hifẓuhumā, wa huwal-`Aliyyu ‘l-`Aẓīm.","meaning_en":"Allah! There is none worthy of worship but He, the Ever-Living, the One Who sustains and protects all that exists. Neither slumber nor sleep overtakes Him. To Him belongs whatever is in the heavens and whatever is on the earth. Who is he that can intercede with Him except with His Permission? He knows what happens to them in this world, and what will happen to them in the Hereafter. And they will never compass anything of His Knowledge except that which He wills. His Throne extends over the heavens and the earth, and He feels no fatigue in guarding and preserving them. And He is the Most High, the Most Great. (Recite in Arabic after each prayer.)","meaning_dv":"","reference":"An-Nasa\u0027i, \u0027Amalul-Yawm wal-Laylah (Hadith no. 100), also Ibn As-Sunni (no. 121). See also Al-Albani, Sahihul-Jami\u0027 As-Saghir 5/339 and Silsilatul-Ahadith As-Sahihah 2/697 (no. 972).","source":"Hisn al-Muslim 71 - Sunnah.com","source_url":"https://sunnah.com/hisn:71","tags":["prayer","daily"]},{"id":"hisn-72","n":72,"title":"After salam","chapter_en":"After salam","chapter_ar":"الأذكار بعد السلام من الصلاة","arabic":"لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِي وَيُمِيتُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ (عَشْرَ مَرّاتٍ بَعْدَ صَلاةِ الْمَغْرِبِ وَالصُّبْحِ)","transliteration":"Lā ilāha illallāh waḥdahu lā sharīka lah, lahu‘l-mulku wa lahu‘l-ḥamd yuḥyī wa yumīt wa huwa `alā kulli shay\u0027in qadīr.","meaning_en":"None has the right to be worshipped but Allah alone, Who has no partner. His is the dominion and His is the praise. He brings life and He causes death, and He is Able to do all things.","meaning_dv":"","reference":"At-Tirmidhi 5/515, Ahmad 4/227. See its checking in Ibn Al-Qayyim Al-Jawziyyah\u0027s Zddul-Ma\u0027ad 1/300.","source":"Hisn al-Muslim 72 - Sunnah.com","source_url":"https://sunnah.com/hisn:72","tags":["gratitude","death"]},{"id":"hisn-73","n":73,"title":"After salam","chapter_en":"After salam","chapter_ar":"الأذكار بعد السلام من الصلاة","arabic":"اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْماً نافِعاً وَرِزْقاً طَيِّباً وَعَمَلاً مُتَقَبَّلاً (بَعْدَ السّلامِ مِنْ صَلاَةِ الفَجْرِ)","transliteration":"Allāhumma innī as\u0027aluka `ilman nāfi`an, wa rizqan ṭayyiban, wa `amalam-mutaqabbala.","meaning_en":"\"O Allah, I ask You for knowledge which is beneficial, and sustenance which is good, and deeds which are acceptable.\"","meaning_dv":"","reference":"Ibn Majah and others. See Sahih Ibn Majah 1/152 and Majma\u0027 Az-Zawa\u0027id 10/111","source":"Hisn al-Muslim 73 - Sunnah.com","source_url":"https://sunnah.com/hisn:73","tags":[]},{"id":"hisn-74","n":74,"title":"For seeking guidance in forming a decision or choosing the proper course","chapter_en":"For seeking guidance in forming a decision or choosing the proper course","chapter_ar":"دعاء صلاة الاستخارة","arabic":"قال جابر بن عبد الله رضي الله عنهما : كان رسول الله صلى الله عليه وسلم ، يُعلمنا الاستخارة في الأمور كلها كما يعلمُنا السورة من القرآن ، يقول : إذا هم أحدكم بالأمر فليركع ركعتين من غير الفريضة ، ثم ليقل: \"اللهم إني أستخيرك بعلمك ، وأستقدرك بقدرتك ، وأسألك من فضلك العظيم فإنك تقدِرُ ولا أقدِرُ ، وتعلم ولا أعلم ، وأنت علام الغيوب ، اللهم إن كنت تعلم أن هذا الأمر - يسمي حاجته - خير لي في ديني ومعاشي وعاقبة أمري - أو قال : عاجله وآجله - فاقدره لي ويسره لي ، ثم بارك لي فيه ، وإن كنت تعلم أن هذا الأمر شر لي في ديني ومعاشي وعاقبة أمري - أو قال : عاجله وآجله - فاصرفه عني واصرفني عنه ، واقدر لي الخير حيث كان ، ثم ارضني به \" وما ندم من استخار الخالق، وشاور المخلوقين المؤمنين وتثبَّت في أمره، فقد قال سبحانه ﴿وَشـاوِرْهُـم في الأمْـرِ فَـإِذا عَـزَمْـتَ فَتَوَكّـلْ عَلـى الله﴾","transliteration":"Allāhumma innī astakhīruka bi `ilmik, wa astaqdiruka biqudratik, wa as\u0027aluka min faḍlika ‘l-`Aẓīm, fa\u0027innaka taqdiru wa lā aqdir, wa ta`lamu wa lā a`lam, wa anta `allāmu ‘l-ghuyūb, Allāhumma in kunta ta`lamu anna hādha ‘l-amra - [then mention the thing to be decided] Khayrun lī fī dīnī wa ma`āshī wa `āqibati amrī - [or say] `ājilihi wa ājilih - faqdurhu lī wa yassirhu lī thumma bārik lī fīh, wa in kunta ta`lamu anna hādha ‘l-amra sharrun lī fī dīnī wa ma`āshī wa `āqibati \u0027amrī - [or say] `ājilihi wa \u0027ājilihi - faṣrifhu `annī waṣrifnī `anh, waqdur liya ‘l-khayra ḥaythu kān, thumma arḍinī bih.","meaning_en":"\"O Allah, I seek the counsel of Your Knowledge, and I seek the help of Your Omnipotence, and I beseech You for Your Magnificent Grace. Surely, You are Capable and I am not. You know and I know not, and You are the Knower of the unseen. O Allah, if You know that this matter [then mention the thing to be decided] is good for me in my religion and in my life and for my welfare in the life to come, - [or say: in this life and the afterlife] - then ordain it for me and make it easy for me, then bless me in it. And if You know that this matter is bad for me in my religion and in my life and for my welfare in the life to come, - [or say: in this life and the afterlife] - then distance it from me, and distance me from it, and ordain for me what is good wherever it may be, and help me to be content with it.\"","meaning_dv":"","reference":"Al-Bukhari 7/162. and Aal-\u0027Imran 3:159.","source":"Hisn al-Muslim 74 - Sunnah.com","source_url":"https://sunnah.com/hisn:74","tags":["forgiveness"]},{"id":"hisn-75","n":75,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"الْحَمْدُ لِلَّهِ وَحْدَهُ، وَالصَّلاَةُ وَالسَّلاَمُ عَلَى مَنْ لاَ نَبِيَّ بَعْدَهُ","transliteration":"Alḥamdulillahi waḥdah waṣ-ṣalatu was-salam `alā man lā nabiyya ba`dah.","meaning_en":"All praise is due to Allah alone, and peace and blessings be upon him after whom there is no other Prophet.","meaning_dv":"","reference":"Anas (RA) said that he heard the Prophet (ﷺ) say: \"That I sit with people remembering Almighty Allah from the morning (Fajr) prayer until sunrise is more beloved to me than freeing four slaves from among the Children of Isma\u0027il. That I sit with people remembering Allah from the afternoon (\u0027Asr) prayer, until the sun sets, is more beloved to me than freeing four slaves from among the Children of Isma\u0027il.\" This was reported by Abu Dawud (no. 3667). Al-Albani graded it good in Sahih Abu Dawud 2/698.","source":"Hisn al-Muslim 75 - Sunnah.com","source_url":"https://sunnah.com/hisn:75","tags":["forgiveness","family","prayer","gratitude"]},{"id":"hisn-75-1","n":75,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"(أعوذ بالله من الشيطان الرجيم) ﴿اللّهُ لاَ إِلَـهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ لاَ تَأْخُذُهُ سِنَةٌ وَلاَ نَوْمٌ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الأَرْضِ مَن ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلاَّ بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلاَ يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلاَّ بِمَا شَاء وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالأَرْضَ وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ﴾","transliteration":"(A`ūdhu billāhi min ash-shaytāni \u0027r-rajīm) Allāhu lā ilāha illā huwa ‘l-Ḥayyul-Qayyūm, lā ta\u0027khudhuhu sinatun wa lā nawm, lahu mā fis-samāwāti wa māfil-arḍ, man dhal-ladhī yashfa`u `indahu illā bi\u0027idhnih, ya`lamu mā bayna aydīhim wa mā khalfahum, wa lā yuḥīṭūna bishay\u0027im-min `ilmihi illā bimā shā\u0027, wasi`a kursiyyuhus-samāwāti wal-arḍ, wa lā ya\u0027ūduhu hifẓuhumā, wa huwal-`Aliyyu‘l-`Aẓīm.","meaning_en":"Allah! There is none worthy of worship but He, the Ever-Living, the One Who sustains and protects all that exists. Neither slumber nor sleep overtakes Him. To Him belongs whatever is in the heavens and whatever is on the earth. Who is he that can intercede with Him except with His Permission? He knows what happens to them in this world, and what will happen to them in the Hereafter. And they will never encompass anything of His Knowledge except that which He wills. His Throne extends over the heavens and the earth, and He feels no fatigue in guarding and preserving them. And He is the Most High, the Most Great.","meaning_dv":"","reference":"(Ayat al-Kursi; Al-Qur\u0027an 2:255)","source":"Hisn al-Muslim 75 - Sunnah.com","source_url":"https://sunnah.com/hisn:75","tags":["daily"]},{"id":"hisn-76","n":76,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"بسم الله الرحمن الرحيم { قُلْ هُوَ اللَّهُ أَحَدٌ * اللَّهُ الصَّمَدُ * لَمْ يَلِدْ وَلَمْ يُولَدْ * لَمْ يَكُن لَّهُ كُفُواً أَحَدٌ } بسم الله الرحمن الرحيم { قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ * مِن شَرِّ مَا خَلَقَ * وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ * وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ * وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ } بسم الله الرحمن الرحيم { قُلْ أَعُوذُ بِرَبِّ النَّاسِ * مَلِكِ النَّاسِ * إِلَهِ النَّاسِ * مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ * الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ * مِنَ الْجِنَّةِ وَالنَّاسِ } (ثلاث مرات)","transliteration":"Bismillāhir-Raḥmānir-Raḥīm. Qul huwallāhu aḥad. Allāhuṣ-ṣamad. Lam yalid wa lam yūlad. Wa lam yakun lahu kufuwan aḥad. Bismillāhir-Raḥmānir-Raḥīm. Qul a`ūdhu birabbil-falaq. Min sharri mā khalaq. Wa min sharri ghāsiqin idhā waqab. Wa min sharrin-naffāthāti fil-`uqad. Wa min sharri ḥāsidin idhā ḥasad. Bismillāhir-Raḥmānir-Raḥīm. Qul a`ūdhu birabbin-nās. Malikin-nās. \u0027Ilāhin-nās. Min sharri ‘l-waswāsil-khannās. Alladhī yuwaswisu fī ṣudūrin-nās. Minal-jinnati wannās.","meaning_en":"With the Name of Allah, the Most Gracious, the Most Merciful. Say:","meaning_dv":"","reference":"Al-Ikhlas 112:1-4, Al-Falaq 113:1-5, An-Nas 114:1-6. Whoever recites these three times in the morning and in the evening, they will suffice him (as a protection) against everything. The Hadith was reported by Abu Dawud 4/322, and At-Tirmidhi 5/567. See Al-Albani\u0027s Sahih At-Tirmidhi 3/182.","source":"Hisn al-Muslim 76 - Sunnah.com","source_url":"https://sunnah.com/hisn:76","tags":["protection"]},{"id":"hisn-77","n":77,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَوْمِ وَخَيرَ مَا بَعْدَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي القَـبْر.","transliteration":"Aṣbaḥnā wa aṣbaḥal-mulku lillāh, walḥamdu lillāh, lā ilāha illallāhu waḥdahu lā sharīka lah, lahul-mulku wa lahul-ḥamd, wa huwa `alā kulli shay\u0027in Qadīr. Rabbi as\u0027aluka khayra mā fī hādha ‘l-yawmi wa khayra mā ba`dahu wa a`ūdhu bika min sharri mā fī hātha ‘l-yawmi wa sharri mā ba`dahu, Rabbi a`ūdhu bika minal-kasali, wa sū\u0027il-kibar, Rabbi a`ūdhu bika min `adhābin fin-nāri wa `adhābin fil-qabr.","meaning_en":"We have entered a new day 1 and with it all dominion is Allah\u0027s. Praise is to Allah. None has the right to be worshipped but Allah alone, Who has no partner. To Allah belongs the dominion, and to Him is the praise and He is Able to do all things. My Lord, I ask You for the goodness of this day and of the days that come after it, and I seek refuge in You from the evil of this day and of the days that come after it.2 My Lord, I seek refuge in You from laziness and helpless old age. My Lord, I seek refuge in You from the punishment of Hell-fire, and from the punishment of the grave.3","meaning_dv":"","reference":"1 When you say this in the evening you should say Amsaynā wa amsal-mulku lillāh: \"We have ended another day and with it, all dominion is Allah\u0027s. 2 When you say this in the evening you should say: Rabbi as\u0027aluka khayra mā fī hāthihil-laylati, wa khayra mā ba`dahā, wa a`ūthu bika min sharri mā fī hāthihil-laylati wa sharri mā ba`dahā: \"I ask You for the good things of this night and of the nights that come after it and I seek refuge in You from the evil of this night and of the nights that come after it.\" 3 Muslim 4/2088.","source":"Hisn al-Muslim 77 - Sunnah.com","source_url":"https://sunnah.com/hisn:77","tags":["protection","gratitude","death"]},{"id":"hisn-78","n":78,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"اللّهُـمَّ بِكَ أَصْـبَحْنا وَبِكَ أَمْسَـينا وَبِكَ نَحْـيا وَبِكَ نَمـوتُ وَإِلَـيْكَ النِّـشور وإذا أمسي فليقل : اللهم بك أمسينا وبك أصبحنا وبك نحيا وبك نموت وإليك المصير","transliteration":"Allāhumma bika aṣbaḥnā, wa bika amsaynā, wa bika naḥyā, wa bika namūt, wa ilaykan-nushūr. When you say this in the evening you should say:","meaning_en":"O Allah, by You we enter the morning and by You we enter the evening, by You we live and by You we die, and to You is the Final Return. O Allah, You bring us the end of the day as You bring us its beginning, You bring us life and you bring us death, and to You is our fate.","meaning_dv":"","reference":"Sahih At-Tirmidhi 3/142.\u0027","source":"Hisn al-Muslim 78 - Sunnah.com","source_url":"https://sunnah.com/hisn:78","tags":["death"]},{"id":"hisn-79","n":79,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"اللّهـمَّ أَنْتَ رَبِّـي لا إلهَ إلاّ أَنْتَ خَلَقْتَنـي وَأَنا عَبْـدُك وَأَنا عَلـى عَهْـدِكَ وَوَعْـدِكَ ما اسْتَـطَعْـت أَعـوذُ بِكَ مِنْ شَـرِّ ما صَنَـعْت أَبـوءُ لَـكَ بِنِعْـمَتِـكَ عَلَـيَّ وَأَبـوءُ بِذَنْـبي فَاغْفـِرْ لي فَإِنَّـهُ لا يَغْـفِرُ الذُّنـوبَ إِلاّ أَنْتَ","transliteration":"Allāhumma anta Rabbī lā ilāha illā ant, khalaqtanī wa anā `abduk, wa anā `alā `ahdika wa wa`dika mastaṭa`t, a`ūdhu bika min sharri mā ṣana`t, abū\u0027u laka bi ni`matika `alay, wa abū\u0027u bidhanbī faghfir lī fa\u0027innahu lā yaghfirudh-dhunūba illā ant.","meaning_en":"O Allah, You are my Lord, there is none worthy of worship but You. You created me and I am your slave. I keep Your covenant, and my pledge to You so far as I am able. I seek refuge in You from the evil of what I have done. I admit to Your blessings upon me, and I admit to my misdeeds. Forgive me, for there is none who may forgive sins but You.","meaning_dv":"","reference":"Whoever recites this with conviction in the evening and dies during that night shall enter Paradise, and whoever recites it with conviction in the morning and dies during that day shall enter Paradise, Al-Bukhari 7/150. Other reports are in An-Nasa\u0027i and At-Tirmidhi.","source":"Hisn al-Muslim 79 - Sunnah.com","source_url":"https://sunnah.com/hisn:79","tags":["forgiveness","protection","gratitude"]},{"id":"hisn-80","n":80,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"اللّهُـمَّ إِنِّـي أَصْبَـحْتُ أَُشْـهِدُك ، وَأُشْـهِدُ حَمَلَـةَ عَـرْشِـك ، وَمَلائِكَتِك ، وَجَمـيعَ خَلْـقِك ، أَنَّـكَ أَنْـتَ اللهُ لا إلهَ إلاّ أَنْـتَ وَحْـدَكَ لا شَريكَ لَـك ، وَأَنَّ ُ مُحَمّـداً عَبْـدُكَ وَرَسـولُـك . (أربع مرات حينَ يصْبِح أوْ يمسي)","transliteration":"Allāhumma innī aṣbaḥtu ush-hiduka wa ush-hidu ḥamalata `arshik, wa malā\u0027ikataka wajamī`a khalqik, annaka antallāhu lā ilāha illā ant, waḥdaka lā sharīka lak, wa anna Muḥammadan `abduka wa rasūluk.","meaning_en":"O Allah, I have entered a new morning 1 and call upon You and upon the bearers of Your Throne, upon Your angels and all creation to bear witness that surely You are Allah, there is none worthy of worship but You alone, You have no partners, and that Muhammad is Your slave and Your Messenger. (Recite four times in Arabic.) 2","meaning_dv":"","reference":"1 When you say this in the evening you should say, Allāhumma innī amsaytu. . . .: \"O Allah, I have ended another day...\" 2 \"Allah will spare whoever says this four times in the morning or evening from the fire of Hell.\" Abu Dawud 4/317. It was also reported by Al-Bukhari in Al-\u0027Adab Al-Mufrad, An-Nasa\u0027i in \u0027Amalul-Yawm wal-Laylah and Ibn As-Sunni. Nasa\u0027i\u0027s and Abu Dawud\u0027s chains of transmission are good (Hasan), Ibn Baz, p. 23.","source":"Hisn al-Muslim 80 - Sunnah.com","source_url":"https://sunnah.com/hisn:80","tags":[]},{"id":"hisn-81","n":81,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"اللّهُـمَّ ما أَصْبَـَحَ بي مِـنْ نِعْـمَةٍ أَو بِأَحَـدٍ مِـنْ خَلْـقِك ، فَمِـنْكَ وَحْـدَكَ لا شريكَ لَـك ، فَلَـكَ الْحَمْـدُ وَلَـكَ الشُّكْـر","transliteration":"Allāhumma mā aṣbaha bī min ni`matin aw bi aḥadin min khalqik, fa minka waḥdaka lā sharīka lak, falaka ‘l-ḥamdu wa lakash-shukr.","meaning_en":"O Allah, whatever blessing has been received by me or anyone of Your creation 1 is from You alone, You have no partner. All praise is for you and thanks is to You. 2","meaning_dv":"","reference":"1 When you say this in the evening, you should say: Allāhumma mā \u0027amsā bī...: \"O Allah, as I... enter this evening...\" 2 Whoever recites this in the morning, has completed his obligation to thank Allah for that day; and whoever says it in the evening, has completed his obligation for that night. Abu Dawud 4/318, An-Nasa\u0027i \u0027Amalul-Yawm wal-Laylah (no. 7), Ibn As-Sunni (no. 41), Ibn Hibban (no. 2361). Its chain of transmission is good (Hasan), Ibn Baz, p. 24.","source":"Hisn al-Muslim 81 - Sunnah.com","source_url":"https://sunnah.com/hisn:81","tags":["forgiveness","gratitude"]},{"id":"hisn-82","n":82,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"اللّهُـمَّ عافِـني في بَدَنـي، اللّهُـمَّ عافِـني في سَمْـعي، اللّهُـمَّ عافِـني في بَصَـري، لا إلهَ إلاّ اللّه أَنْـتَ. اللّهُـمَّ إِنّـي أَعـوذُبِكَ مِنَ الْكُـفر، وَالفَـقْر، وَأَعـوذُ بِكَ مِنْ عَذابِ القَـبْر، لا إلهَ إلاّ أَنْـتَ. (ثلاث مرات)","transliteration":"Allāhumma `āfinī fī badanī, Allāhumma `āfinī fī sam`ī, Allāhumma `āfinī fī baṣarī, lā ilāha illā ant. Allāhumma innī a`ūdhu bika mina ‘l-kufri, wa ‘l-faqr, wa a`ūdhu bika min `adhābi ‘l-qabr, lā ilāha illā ant.","meaning_en":"O Allah, make me healthy in my body. O Allah, preserve for me my hearing. O Allah, preserve for me my sight. There is none worthy of worship but You. O Allah, I seek refuge in You from disbelief and poverty, and I seek refuge in You from the punishment of the grave. There is none worthy of worship but You (Recite three times in Arabic.)","meaning_dv":"","reference":"Abu Dawud 4/324, Ahmad 5/42, An-Nasa\u0027i, \u0027Amalul-Yawm wal-Laylah (no. 22), Ibn As-Sunni (no. 69), Al-Bukhari Al-\u0027Adab Al-Mufrad. Its chain of transmission is good (Hasan), Ibn Baz, p. 26.","source":"Hisn al-Muslim 82 - Sunnah.com","source_url":"https://sunnah.com/hisn:82","tags":["illness","protection","death"]},{"id":"hisn-83","n":83,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"حَسْبِـيَ اللّهُ لا إلهَ إلاّ هُوَ عَلَـيهِ تَوَكَّـلتُ وَهُوَ رَبُّ العَرْشِ العَظـيم. (سبع مرات)","transliteration":"Ḥasbiyallāhu lā ilāha illā huwa `alayhi tawakkalt, wa huwa Rabbu ‘l-`Arshi ‘l-\u0027Aẓīm.","meaning_en":"Allah is sufficient for me. There is none worthy of worship but Him. I have placed my trust in Him, He is Lord of the Majestic Throne. (Recite seven times in Arabic.)","meaning_dv":"","reference":"Allah will grant whoever recites this seven times in the morning or evening whatever he desires from this world or the next, Ibn As-Sunni (no. 71), Abu Dawud 4/321. Both reports are attributed directly to the Prophet j§ (Marfu1). The chain of transmission is sound (Sahih). Ibn As-Sunni.","source":"Hisn al-Muslim 83 - Sunnah.com","source_url":"https://sunnah.com/hisn:83","tags":[]},{"id":"hisn-84","n":84,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"اللّهُـمَّ إِنِّـي أسْـأَلُـكَ العَـفْوَ وَالعـافِـيةَ في الدُّنْـيا وَالآخِـرَة ، اللّهُـمَّ إِنِّـي أسْـأَلُـكَ العَـفْوَ وَالعـافِـيةَ في ديني وَدُنْـيايَ وَأهْـلي وَمالـي ، اللّهُـمَّ اسْتُـرْ عـوْراتي وَآمِـنْ رَوْعاتـي ، اللّهُـمَّ احْفَظْـني مِن بَـينِ يَدَيَّ وَمِن خَلْفـي وَعَن يَمـيني وَعَن شِمـالي ، وَمِن فَوْقـي ، وَأَعـوذُ بِعَظَمَـتِكَ أَن أُغْـتالَ مِن تَحْتـي","transliteration":"Allāhumma innī as\u0027aluka \u0027l-`afwa wal-`āfiyah fid-dunyā wal-ākhirah, Allāhumma innī as\u0027aluka \u0027l-`afwa wal-`āfiyah fī dīnī wa dunyāya, wa ahlī, wa mālī, Allāhummastur `awrātī, wa āmin raw`ātī, Allāhummaḥfaẓnī min bayni yadayya, wa min khalfī, wa `an yamīnī, wa `an shimālī, wa min fawqī, wa a`ūdhu bi`aẓamatika an \u0027ughtāla min taḥtī.","meaning_en":"O Allah, I seek Your forgiveness and Your protection in this world and the next. O Allah, I seek Your forgiveness and Your protection in my religion, in my worldly affairs, in my family and in my wealth. O Allah, conceal my secrets and preserve me from anguish. O Allah, guard me from what is in front of me and behind me, from my left, and from my right, and from above me. I seek refuge in Your Greatness from being struck down from beneath me.","meaning_dv":"","reference":"Sahih Ibn Majah 2/332 and Abu Dawud.","source":"Hisn al-Muslim 84 - Sunnah.com","source_url":"https://sunnah.com/hisn:84","tags":["forgiveness","financial","family","protection"]},{"id":"hisn-85","n":85,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"اللّهُـمَّ عالِـمَ الغَـيْبِ وَالشّـهادَةِ فاطِـرَ السّماواتِ وَالأرْضِ رَبَّ كـلِّ شَـيءٍ وَمَليـكَه ، أَشْهَـدُ أَنْ لا إِلـهَ إِلاّ أَنْت ، أَعـوذُ بِكَ مِن شَـرِّ نَفْسـي وَمِن شَـرِّ الشَّيْـطانِ وَشِـرْكِه ، وَأَنْ أَقْتَـرِفَ عَلـى نَفْسـي سوءاً أَوْ أَجُـرَّهُ إِلـى مُسْـلِم","transliteration":"Allāhumma `ālima ‘l-ghaybi wash-shahādah fātir as-samāwāti wa ‘l\u0027arḍ, Rabba kulli shay\u0027in wa malīkah, ash-hadu an lā ilāha illā ant, a`ūdhu bika min sharri nafsī, wa min sharrish-shayṭāni wa shirkih, wa an aqtarifa `alā nafsī sū\u0027an, aw ajurrahu ilā Muslim.","meaning_en":"O Allah, Knower of the unseen and the evident, Maker of the heavens and the earth, Lord of everything and its Possessor, I bear witness that there is none worthy of worship but You. I seek refuge in You from the evil of my soul, and from the evil of Satan and his helpers. (I seek refuge in You) from bringing evil upon my soul and from harming any Muslim.","meaning_dv":"","reference":"Sahih At-Tirmidhi 3/142 and AbuDawud.","source":"Hisn al-Muslim 85 - Sunnah.com","source_url":"https://sunnah.com/hisn:85","tags":["protection"]},{"id":"hisn-86","n":86,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"بِسـمِ اللهِ الذي لا يَضُـرُّ مَعَ اسمِـهِ شَيءٌ في الأرْضِ وَلا في السّمـاءِ وَهـوَ السّمـيعُ العَلـيم . (ثلاث مرات)","transliteration":"Bismillāhi ‘l-ladhī lā yaḍurru ma`a-smihi shay\u0027un fil-\u0027arḍi wa lā fis-samā\u0027 wa huwas-Samī `ul-`Alīm.","meaning_en":"In the Name of Allah, Who with His Name nothing can cause harm in the earth nor in the heavens, and He is the All-Hearing, the All-Knowing. (Recite three times in Arabic).","meaning_dv":"","reference":"\"Whoever recites it three times in the morning will not be afflicted by any calamity before evening, and whoever recites it three times in the evening will not be overtaken by any calamity before morning.\" Abu Dawud 4/323, At-Tirmidhi 5/465, Ibn Majah 2/332, Ahmad. Ibn Majah\u0027s chain of transmission is good (Hasan), Ibn Baz, p. 39.","source":"Hisn al-Muslim 86 - Sunnah.com","source_url":"https://sunnah.com/hisn:86","tags":["patience"]},{"id":"hisn-87","n":87,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"رَضيـتُ بِاللهِ رَبَّـاً وَبِالإسْلامِ ديـناً وَبِمُحَـمَّدٍ نَبِيّـاً . (ثلاث مرات)","transliteration":"Raḍītu billāhi Rabba, wa bil-Islāmi dīna, wa bi-Muḥammadin (ṣallallāhu `alayhi wa sallama) nabiyya.","meaning_en":"I am pleased with Allah as my Lord, with Islam as my religion, and with Muhammad (peace and blessings of Allah be upon him) as my Prophet. (Recite three times in Arabic.)","meaning_dv":"","reference":"\"Allah has promised that anyone who says this three times every morning or evening will be pleased on the Day of Resurrection.\" Ahmad 4/ 337, An-Nasa\u0027i, \u0027Amalul-Yawm wal-Laylah p. 4, Ibn As-Sunni (no. 68), At-Tirmidhi 5/465. Its chain of transmission is good (Hasan), Ibn Baz, p. 39.","source":"Hisn al-Muslim 87 - Sunnah.com","source_url":"https://sunnah.com/hisn:87","tags":["forgiveness","gratitude"]},{"id":"hisn-88","n":88,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"يا حَـيُّ يا قَيّـومُ بِـرَحْمَـتِكِ أَسْتَـغـيث ، أَصْلِـحْ لي شَـأْنـي كُلَّـه ، وَلا تَكِلـني إِلى نَفْـسي طَـرْفَةَ عَـين","transliteration":"Yā Ḥayyu yā Qayyūmu biraḥmatika astaghīth aṣlih lī sha\u0027nī kullah wa lā takilnī ilā nafsī ṭarfata `ayn.","meaning_en":"O Ever-Living One, O Eternal One, by Your mercy I call on You to set right all my affairs. Do not place me in charge of my soul even for the blinking of an eye (i.e. a moment).","meaning_dv":"","reference":"Its chain of transmission is sound (Sahih), Al-Hakim 1/545, see Albani, Sahihut-Targhib wat-Tarhib, 1/273.","source":"Hisn al-Muslim 88 - Sunnah.com","source_url":"https://sunnah.com/hisn:88","tags":["protection"]},{"id":"hisn-89","n":89,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"أَصْبَـحْـنا وَأَصْبَـحْ المُـلكُ للهِ رَبِّ العـالَمـين ، اللّهُـمَّ إِنِّـي أسْـأَلُـكَ خَـيْرَ هـذا الـيَوْم ، فَـتْحَهُ ، وَنَصْـرَهُ ، وَنـورَهُ وَبَـرَكَتَـهُ ، وَهُـداهُ ، وَأَعـوذُ بِـكَ مِـنْ شَـرِّ ما فـيهِ وَشَـرِّ ما بَعْـدَه وإذا أمسى قال: أَمْسَيْـنا وَأَمْسـى المُـلكُ للهِ رَبِّ العـالَمـين ، اللّهُـمَّ إِنِّـي أسْـأَلُـكَ خَـيْرَ هـذهِ اللَّـيْلَة ، فَتْحَهـا ، وَنَصْـرَهـا ، وَنـورَهـا وَبَـرَكَتَـهـا ، وَهُـداهـا ، وَأَعـوذُ بِـكَ مِـنْ شَـرِّ ما فـيهـاِ وَشَـرِّ ما بَعْـدَهـا","transliteration":"Aṣbaḥnā wa aṣbaḥal-mulku lillāhi Rabbi ‘l-a`lāmīn, Allāhumma innī as\u0027aluka khayra hādha ‘l-yawm:","meaning_en":"We have entered a new day and with it all the dominion which belongs to Allah, Lord of all that exists. O Allah, I ask You for the goodness of this day,2 its victory, its help, its light, its blessings, and its guidance. I seek refuge in You from the evil that is in it, and from the evil that follows it.","meaning_dv":"","reference":"1 For evening recitation, say here: Allāhumma innī as\u0027aluka khayra hāthihil-laylah: \"My Lord, I ask You for the good things of this night.\" 2 Abu Dawud 4/322. Its transmission chain is good (Hasan). See also Ibn Al-Qayyim, Zadul- Ma\u0027ad 2/273.","source":"Hisn al-Muslim 89 - Sunnah.com","source_url":"https://sunnah.com/hisn:89","tags":["forgiveness","protection","gratitude"]},{"id":"hisn-90","n":90,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"أَصْـبَحْنا[أَمْسَـينا] علـى فِطْـرَةِ الإسْلام، وَعَلـى كَلِـمَةِ الإخْـلاص، وَعلـى دينِ نَبِـيِّنا مُحَـمَّدٍ وَعَلـى مِلَّـةِ أبينـا إِبْـراهيـمَ حَنيـفاً مُسْلِـماً وَمـا كـانَ مِنَ المُشـرِكيـن","transliteration":"Aṣbahnā `alā fiṭrati ‘l-Islām, wa `alā kalimati ‘l-ikhlās, wa `alā dīni nabiyyinā Muḥammadin (ṣallallāhu `alayhi wa sallam), wa `alā millati abīnā Ibrāhīm, ḥanīfan Musliman wa mā kāna mina ‘l-mushrikīn.","meaning_en":"We have entered a new day 1 upon the natural religion of Islam, the word of sincere devotion, the religion of our Prophet Muhammad (peace and blessings of Allah be upon him), and the faith of our father Ibrahim. He was upright (in worshipping Allah), and a Muslim. He was not of those who worship others besides Allah. 2","meaning_dv":"","reference":"1 When you say this in the evening, you should say: \u0027Amsaynā `alā fiṭratil-Islām...: \"We end this day...\" 2 Ahmad 3/406-7, 5/123, An-Nasa\u0027i, \u0027Amalul- Yawm wal-Laylah (no. 34), At-Tirmidhi 4/209.","source":"Hisn al-Muslim 90 - Sunnah.com","source_url":"https://sunnah.com/hisn:90","tags":["forgiveness","gratitude"]},{"id":"hisn-91","n":91,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"سُبْحـانَ اللهِ وَبِحَمْـدِهِ . (مائة مرة)","transliteration":"Subḥānallāhi wa biḥamdih.","meaning_en":"Glory is to Allah and praise is to Him. (Recite one hundred times in Arabic).","meaning_dv":"","reference":"\"Whoever recites this one hundred times in the morning and in the evening will not be surpassed on the Day of Resurrection by anyone having done better than this except for someone who had recited it more. \" Al-Bukhari 4/2071.","source":"Hisn al-Muslim 91 - Sunnah.com","source_url":"https://sunnah.com/hisn:91","tags":["gratitude"]},{"id":"hisn-92","n":92,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"لا إلهَ إلاّ اللّهُ وحْـدَهُ لا شَـريكَ لهُ، لهُ المُـلْكُ ولهُ الحَمْـد، وهُوَ على كُلّ شَيءٍ قَدير . (عشر مرات أَوْ مرَّةً واحدةً عندَ الكَسَلِ)","transliteration":"Lā ilāha illallāhu waḥdahu lā sharīka lah, lahu ‘l-mulku walahu ‘l-ḥamd, wa huwa `alā kulli shay\u0027in qadīr.","meaning_en":"None has the right to be worshipped but Allah alone, Who has no partner. His is the dominion and His is the praise and He is Able to do all things. (Recite ten times 1 in Arabic or one time to ward off laziness.) 2","meaning_dv":"","reference":"1Allah will write ten Hasanaat (rewards) for whoever recites this ten times in the morning, and forgive him ten misdeeds and give him the reward of freeing ten slaves and protect him from Satan. Whoever recites this ten times in the evening will get this same reward. An-Nasa\u0027i, \u0027Amalul-Yawm wal-Laylah (no. 24). Its chain of transmission is sound (Sahih). Albani 1/272. Abu Hurayrah «fe narrated that the Prophet j§ said: \"Allah will write one hundred Hasanat for whoever says There is no God but Allah alone, He has no partner. To Allah is possession of everything, and to Him all praise is. He is Capable of all things\u0027 ten times in the morning, and forgive him one hundred misdeeds. He will have the reward of freeing a slave and will be protected from Satan throughout the day unto dusk. Whoever says it in the evening will have the same reward.\" Ahmad 8/704, 16/293. Its chain of transmission is good (Hasan), Ibn Baz, p. 44. 2 Whoever recites this in the morning, will have the reward of freeing a slave from the Children of Isma\u0027il. Ten Hasanaat (rewards) will be written for him, and he will be forgiven ten misdeeds, raised up ten degrees, and be protected from Satan until evening. Whoever says it in the evening will have the same reward until morning. Abu Dawud 4/319, 3/957, Ahmad 4/ 60, Ibn Majah 2/331, Ibn Al-Qayyim Zadul-Ma\u0027ad 2/388. Its chain of transmission is sound (Sahih). Al-Albani 1/270.","source":"Hisn al-Muslim 92 - Sunnah.com","source_url":"https://sunnah.com/hisn:92","tags":["forgiveness","family","protection","gratitude"]},{"id":"hisn-93","n":93,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"لا إلهَ إلاّ اللّهُ وحْـدَهُ لا شَـريكَ لهُ، لهُ المُـلْكُ ولهُ الحَمْـد، وهُوَ على كُلّ شَيءٍ قَدير . (مائة مرة إذا أصبح)","transliteration":"Lā ilāha illallāhu waḥdahu lā sharīka lah, lahu ‘l-mulku walahu ‘l-ḥamd, wa huwa `alā kulli shay\u0027in qadīr.","meaning_en":"None has the right to be worshipped but Allah alone, Who has no partner. His is the dominion and His is the praise and He is Able to do all things. (Recite 100 times in Arabic upon rising in the morning).","meaning_dv":"","reference":"Whoever recites this one hundred times a day will have the reward of freeing ten slaves. One hundred Hasanaat (rewards) will be written for him and one hundred misdeeds will be washed away. He will be shielded from Satan until the evening. No one will be able to present anything better than this except for someone who has recited more than this. Al-Bukhari 4/95, Muslim 4/2071.","source":"Hisn al-Muslim 93 - Sunnah.com","source_url":"https://sunnah.com/hisn:93","tags":["forgiveness","protection","gratitude"]},{"id":"hisn-94","n":94,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"سُبْحـانَ اللهِ وَبِحَمْـدِهِ عَدَدَ خَلْـقِه ، وَرِضـا نَفْسِـه ، وَزِنَـةَ عَـرْشِـه ، وَمِـدادَ كَلِمـاتِـه . (ثلاث مرات إذا أصبح)","transliteration":"Subḥānallāhi wa biḥamdih:","meaning_en":"Glory is to Allah and praise is to Him, by the multitude of His creation, by His Pleasure, by the weight of His Throne, and by the extent of His Words. (Recite three times in Arabic upon rising in the morning.)","meaning_dv":"","reference":"Muslim 4/2090.","source":"Hisn al-Muslim 94 - Sunnah.com","source_url":"https://sunnah.com/hisn:94","tags":["forgiveness","gratitude"]},{"id":"hisn-95","n":95,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْماً نَافِعاً، وَرِزْقاً طَيِّباً، وَعَمَلاً مُتَقَبَّلاً (إذا أصبحَ)","transliteration":"Allāhumma innī as\u0027aluka `ilman nāfi`a, wa rizqan ṭayyiba, wa `amalan mutaqabbala.","meaning_en":"O Allah, I ask You for knowledge that is of benefit, a good provision, and deeds that will be accepted. (Recite in Arabic upon rising in the morning.)","meaning_dv":"","reference":"Ibn As-Sunni, no. 54, Ibn Majah no. 925. Its chain of transmission is good (Hasan), Ibn Al-Qayyim 2/375.","source":"Hisn al-Muslim 95 - Sunnah.com","source_url":"https://sunnah.com/hisn:95","tags":["forgiveness","financial"]},{"id":"hisn-96","n":96,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ (مِائَةَ مَرَّةٍ فِي الْيَوْمِ)","transliteration":"Astaghfirullāha wa atūbu ilayh.","meaning_en":"I seek the forgiveness of Allah and repent to Him. (Recite one hundred times in Arabic during the day.)","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 11/101, Muslim 4/2075.","source":"Hisn al-Muslim 96 - Sunnah.com","source_url":"https://sunnah.com/hisn:96","tags":["forgiveness"]},{"id":"hisn-97","n":97,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"أَعـوذُ بِكَلِمـاتِ اللّهِ التّـامّـاتِ مِنْ شَـرِّ ما خَلَـق (ثلاث مرات إِذا أمسى)","transliteration":"A`ūdhu bikalimāti-llāhit-tāmmāti min sharri mā khalaq.","meaning_en":"I seek refuge in the Perfect Words of Allah from the evil of what He has created. (Recite three times in Arabic in the evening.)","meaning_dv":"","reference":"Whoever recites this three times in the evening will be protected from insect stings, Ahmad 2/ 290, An-Nasa\u0027i, \u0027Amalul-Yawm wal-Laylah no. 590, At-Tirmidhi 3/187, Ibn As-Sunni no. 68. According to Al-Albani, Ibn Majah\u0027s (2/266) chain of transmission is sound (Sahih), and following Ibn Baz 45, At-Tirmidhi\u0027s report is good (Hasan).","source":"Hisn al-Muslim 97 - Sunnah.com","source_url":"https://sunnah.com/hisn:97","tags":["protection"]},{"id":"hisn-98","n":98,"title":"In the morning and evening","chapter_en":"In the morning and evening","chapter_ar":"أذكار الصباح والمساء","arabic":"اللَّهُمَّ صَلِّ وَ سَلِّمْ عَلَى نَبِيِّنَا مُحَمَّدٍ (عشر مرات)","transliteration":"Allāhumma ṣalli wa sallim `alā nabiyyinā Muḥammad.","meaning_en":"O Allah, we ask for your peace and blessings upon our Prophet Muhammad. (Recite ten times in Arabic.)","meaning_dv":"","reference":"The Prophet (ﷺ) said: \"Who recites blessings upon me ten times in the morning and ten times in the evening will obtain my intercession on the Day of Resurrection.\" At-Tabarani reported this Hadith together with two chains of transmission. One of them is reliable (Jayyid). See Haythami\u0027s Majma\u0027uz-Zawa\u0027id 10/120, and Al-Albani\u0027s Sahihut-Targhib wat-Tarhib 1/273.","source":"Hisn al-Muslim 98 - Sunnah.com","source_url":"https://sunnah.com/hisn:98","tags":["forgiveness","gratitude"]},{"id":"hisn-99","n":99,"title":"Before sleeping","chapter_en":"Before sleeping","chapter_ar":"أذكار النوم","arabic":"يَجْمَعُ كَفَّيْهِ ثُمَّ يَنْفُثُ فِيهِمَا فَيَقْرَأُ فِيهِمَا: بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ {قُلْ هُوَ اللَّهُ أَحَدٌ * اللَّهُ الصَّمَدُ* لَمْ يَلِدْ وَلَمْ يُولَدْ* وَلَمْ يَكُن لَّهُ كُفُواً أَحَدٌ}. بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ* مِن شَرِّ مَا خَلَقَ* وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ* وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ* وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ}. بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ {قُلْ أَعُوذُ بِرَبِّ النَّاسِ* مَلِكِ النَّاسِ* إِلَهِ النَّاسِ* مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ* الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ* مِنَ الْجِنَّةِ وَالنَّاسِ} ثُمَّ يَمْسَحُ بِهِمَا مَا اسْتَطَاعَ مِنْ جَسَدِهِ يَبْدَأُ بِهِمَا عَلَى رَأْسِهِ وَوَجْهِهِ وَمَا أَقبَلَ مِنْ جَسَدِهِ (يفعلُ ذلك ثلاثَ مرَّاتٍ)","transliteration":"Bismillāhir-Raḥmānir-Raḥīm. Qul huwallāhu aḥad. Allāhuṣ-ṣamad. Lam yalid wa lam yūlad. Wa lam yakun lahu kufuwan aḥad. Reference: Al-Ikhlas 112:1-4. Bismillāhir-Raḥmānir-Raḥīm. Qul a`ūdhu birabbil-falaq. Min sharri mā khalaq. Wa min sharri ghāsiqin idhā waqab. Wa min sharrin-naffāthāti fil-`uqad. Wa min sharri ḥāsidin idhā ḥasad. Reference: Al-Falaq 113:1-5. Bismillāhir-Raḥmānir-Raḥīm. Qul a`ūdhu birabbin-nās. Malikin-nās. \u0027Ilāhin-nās. Min sharri ‘l-waswāsil-khannās. Alladhī yuwaswisu fī ṣudūrin-nās. Minal-jinnati wannās. Reference: An-Nas 114:1-6","meaning_en":"Hold the palms together, blow (with a little spittle) into them, and recite: \"With the Name of Allah, the Most Gracious, the Most Merciful. Say: He is Allah (the) One. The Self-Sufficient Master, Whom all creatures need, He begets not nor was He begotten, and there is none equal to Him. With the Name of Allah, the Most Gracious, the Most Merciful. Say: I seek refuge with (Allah) the Lord of the daybreak, from the evil of what He has created, and from the evil of the darkening (night) as it comes with its darkness, and from the evil of those who practice witchcraft when they blow in the knots, and from the evil of the envier when he envies. With the Name of Allah, the Most Gracious, the Most Merciful. Say: I seek refuge with (Allah) the Lord of mankind, the King of mankind, the God of mankind, from the evil of the whisperer who withdraws, who whispers in the breasts of mankind, of jinns and men.\" (Then pass your hands over as much of your body as you can reach, beginning with the head and the face, then the entire front of your body. Do this three times.)","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 9/62, and Muslim 4/ 1723.","source":"Hisn al-Muslim 99 - Sunnah.com","source_url":"https://sunnah.com/hisn:99","tags":["protection","daily"]},{"id":"hisn-100","n":100,"title":"Before sleeping","chapter_en":"Before sleeping","chapter_ar":"أذكار النوم","arabic":"((اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ لاَ تَأْخُذُهُ سِنَةٌ وَلاَ نَوْمٌ لَّهُ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ مَن ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلاَّ بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلاَ يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلاَّ بِمَا شَاء وَسِعَ كُرْسِيُّهُ السَّمَوَاتِ وَالأَرْضَ وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ))","transliteration":"Allāhu lā ilāha illā huwa ‘l-Ḥayyul-Qayyūm, lā ta\u0027khudhuhu sinatun wa lā nawm, lahu mā fis-samāwāti wa māfil-ardh, man dhal-ladhī yashfa`u `indahu illā bi\u0027idhnih, ya`lamu mā bayna aydīhim wa mā khalfahum, wa lā yuḥītūna bishay\u0027im-min `ilmihi illā bimā shā\u0027, wasi`a kursiyyuhus-samāwāti wal-ardh, wa lā ya\u0027ūduhu hifẓuhumā, wa huwal-`Aliyyu‘l-`Aẓīm.","meaning_en":"Allah! There is none worthy of worship but He, the Ever-Living, the One Who sustains and protects all that exists. Neither slumber nor sleep overtakes Him. To Him belongs whatever is in the heavens and whatever is on the earth. Who is he that can intercede with Him except with His Permission? He knows what happens to them in this world, and what will happen to them in the Hereafter. And they will never encompass anything of His Knowledge except that which He wills. His Throne extends over the heavens and the earth, and He feels no fatigue in guarding and preserving them. And He is the Most High, the Most Great.","meaning_dv":"","reference":"Al-Baqarah 2:255. Whoever reads this when he lies down to sleep will have a guardian from Allah remain with him and Satan will not be able to come near him until he rises in the morning. See Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 4/487.","source":"Hisn al-Muslim 100 - Sunnah.com","source_url":"https://sunnah.com/hisn:100","tags":["protection","daily"]},{"id":"hisn-101","n":101,"title":"Before sleeping","chapter_en":"Before sleeping","chapter_ar":"أذكار النوم","arabic":"((ءامَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ كُلٌّ ءامَنَ بِاللهِ وَمَلآئِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لاَ نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ وَقَالُواْ سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ {285} لاَ يُكَلِّفُ اللهُ نَفْسًا إِلاَّ وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لاَ تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا رَبَّنَا وَلاَ تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا رَبَّنَا وَلاَ تُحَمِّلْنَا مَا لاَ طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَآ أَنتَ مَوْلاَنَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ {286}))","transliteration":"Āmanar-Rasūlu bimā unzila ilaihi mir-Rabbihi wa ‘l-mu\u0027minūn, kullun āmana billāhi wa malā\u0027ikatihi wa kutubihi wa rusulih, lā nufarriqu bayna aḥadim-mir-rusulih, wa qālū sami`nā wa aṭa`nā, ghufrānaka Rabbanā wa ilayka ‘l-maṣīr. Lā yukallifu ‘llāhu nafsan illā wus`ahā, lahā mā kasabat wa `alayhā mak-tasabat, Rabbanā lā tu\u0027ākhidhnā in nasīnā aw akhta\u0027nā, Rabbanā wa lā taḥmil `alaynā iṣran kamā ḥamaltahu `alal-ladhīna min qablinā, Rabbanā wa lā tuḥammilnā mā lā ṭāqata lanā bih, wa`fu `annā, waghfir lanā, warḥamnā, Anta mawlānā fanṣurnā `ala ‘l-qawmi ‘l-kāfirīn.","meaning_en":"The Messenger believes in what has been sent down to him from his Lord, and so do the believers. Each one believes in Allah, His Angels, His Books, and His Messengers. They say:","meaning_dv":"","reference":"Al-Baqarah 2:285-6. These two Verses will be sufficient for anyone who recites them at night before sleeping. Al-Bukhari, cf. Al-Asqalani, Fathul-Bari.9/94, Muslim 1/554.","source":"Hisn al-Muslim 101 - Sunnah.com","source_url":"https://sunnah.com/hisn:101","tags":["daily"]},{"id":"hisn-102","n":102,"title":"Before sleeping","chapter_en":"Before sleeping","chapter_ar":"أذكار النوم","arabic":"بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِن أَمْسَكْتَ نَفْسِي فارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ","transliteration":"Bismika Rabbī waḍa`tu janbī, wa bika arfa`uh, fa in amsakta nafsī farḥamhā, wa in arsaltahā faḥfaẓhā bimā taḥfaẓu bihi `ibādakaṣ-ṣāliḥīn.","meaning_en":"With Your Name1 my Lord, I lay myself down; and with Your Name I rise. And if You take my soul, have mercy on it, and if You send it back then protect it as You protect Your righteous slaves.2","meaning_dv":"","reference":"1 \"If any of you rises from his bed and later returns to it, let him dust off his bed with his waist garment three times and mention the Name of Allah, for he does not know what may have entered the bed after him, and when he lies down he should say. . . \". 2 Al-Bukhari 1 1/ 126 and Muslim 4/2084.","source":"Hisn al-Muslim 102 - Sunnah.com","source_url":"https://sunnah.com/hisn:102","tags":["daily"]},{"id":"hisn-103","n":103,"title":"Before sleeping","chapter_en":"Before sleeping","chapter_ar":"أذكار النوم","arabic":"اللَّهُمَّ إِنَّكَ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا، لَكَ مَمَاتُهَا وَمَحْياهَا، إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا، وَإِنْ أَمَتَّهَا فَاغْفِرْ لَهَا. اللَّهُمَّ إِنِّي أَسْأَلُكَ العَافِيَةَ","transliteration":"Allāhumma innaka khalaqta nafsī wa anta tawaffāhā, laka mamātuhā wa maḥyāhā, in aḥyaytahā faḥfaẓhā, wa in amattahā faghfir lahā. Allāhumma innī as\u0027aluka ‘l-`āfiyah.","meaning_en":"O Allah, You have created my soul and You take it back. Unto You is its death and its life. If You give it life then protect it, and if You cause it to die then forgive it. O Allah, I ask You for strength.","meaning_dv":"","reference":"Muslim 4/2083 and Ahmad 2/79.","source":"Hisn al-Muslim 103 - Sunnah.com","source_url":"https://sunnah.com/hisn:103","tags":["forgiveness","daily","death"]},{"id":"hisn-104","n":104,"title":"Before sleeping","chapter_en":"Before sleeping","chapter_ar":"أذكار النوم","arabic":"اللّهُـمَّ قِنـي عَذابَـكَ يَـوْمَ تَبْـعَثُ عِبـادَك .","transliteration":"Allāhumma qinī `adhābaka yawma tab`athu `ibādak.","meaning_en":"O Allah,1 save me from Your punishment on the Day that You resurrect Your slaves.2","meaning_dv":"","reference":"1 \"When the Prophet (ﷺ) wanted to lie down to sleep, he used to place his right hand under his cheek and say...\" 2 Abu Dawud 4/311. See also Al-Albani, Sahih At-Tirmidhi 3/143.","source":"Hisn al-Muslim 104 - Sunnah.com","source_url":"https://sunnah.com/hisn:104","tags":["daily"]},{"id":"hisn-105","n":105,"title":"Before sleeping","chapter_en":"Before sleeping","chapter_ar":"أذكار النوم","arabic":"بِاسْـمِكَ اللّهُـمَّ أَمـوتُ وَأَحْـيا","transliteration":"Bismika Allāhumma amūtu wa aḥyā.","meaning_en":"In Your Name, O Allah, I die and I live.","meaning_dv":"","reference":"Here, dying and living are metaphors for sleep and wakefulness. This explains why the normal order of these words has been reversed in this Hadith. In other contexts the living is mentioned before dying. See Qur\u0027an Al-Baqarah 2:258, Aal-\u0027Imrdn 3:156, Al-A\u0027raf 7:158 among many other examples, (trans.). See also Al-Asqalani, Fathul-Bari 11/113, Muslim 4/ 2083.","source":"Hisn al-Muslim 105 - Sunnah.com","source_url":"https://sunnah.com/hisn:105","tags":["daily","death"]},{"id":"hisn-106","n":106,"title":"Before sleeping","chapter_en":"Before sleeping","chapter_ar":"أذكار النوم","arabic":"سُبْحَانَ اللَّهِ (ثلاثاً وثلاثين) وَالْحَمْدُ لِلَّهِ (ثلاثاً وثلاثين) وَاللَّهُ أَكْبَرُ (أربعاً وثلاثينَ)","transliteration":"Subḥānallāh, Wa ‘l-ḥamdu lillāh, Wallāhu Akbar.","meaning_en":"Glory is to Allah (thirty-three times in Arabic), Praise is to Allah (thirty-three times), Allah is the Most Great (thirty-four times)","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 7/71, Muslim 4/2091.","source":"Hisn al-Muslim 106 - Sunnah.com","source_url":"https://sunnah.com/hisn:106","tags":["daily","gratitude"]},{"id":"hisn-107","n":107,"title":"Before sleeping","chapter_en":"Before sleeping","chapter_ar":"أذكار النوم","arabic":"اللّهُـمَّ رَبَّ السّمـواتِ السَّبْـعِ وَرَبَّ العَـرْشِ العَظـيم رَبَّنـا وَرَبَّ كُـلِّ شَـيء فالِـقَ الحَـبِّ وَالنَّـوى وَمُـنَزِّلَ التَّـوْراةِ وَالإنْجـيل والفُـرْقان أَعـوذُ بِـكَ مِن شَـرِّ كُـلِّ شَـيءٍ أَنْـتَ آخِـذٌ بِنـاصِـيَتِه اللّهُـمَّ أَنْـتَ الأوَّلُ فَلَـيسَ قَبْـلَكَ شَيء وَأَنْـتَ الآخِـرُ فَلَـيسَ بَعْـدَكَ شَيء وَأَنْـتَ الظّـاهِـرُ فَلَـيْسَ فَـوْقَـكَ شَيء وَأَنْـتَ الْبـاطِـنُ فَلَـيْسَ دونَـكَ شَيء اقـْضِ عَنّـا الـدَّيْـنَ وَأَغْـنِنـا مِنَ الفَـقْر","transliteration":"Allāhumma Rabbas-samāwātis-sab`i wa Rabba ‘l-`Arshi ‘l-`Aẓīm, Rabbanā wa Rabba kulli shay\u0027, fāliqa ‘l-ḥabbi wan-nawā, wa munzilat-Tawrāti wal-\u0027Injīli, wal-Furqān, a`ūdhu bika min sharri kulli shay\u0027in anta ākhidhun bināṣiyatih. Allāhumma anta ‘l-awwalu falaysa qablaka shay\u0027, wa antal-ākhiru falaysa ba`daka shay\u0027, wa antaẓ-ẓāhiru falaysa fawqaka shay\u0027, wa antal-bāṭinu falaysa dūnaka shay\u0027, iqḍi `annad-dayn, wa aghninā mina ‘l-faqr.","meaning_en":"O Allah! Lord of the seven heavens and Lord of the Magnificent Throne. Our Lord and the Lord of everything. Splitter of the grain and the date-stone, Revealer of the Torah and the Injeel1 and the Furqan (the Qur\u0027an), I seek refuge in You from the evil of everything that You shall seize by the forelock.2 O Allah You are the First and nothing has come before you, and You are the Last, and nothing may come after You. You are the Most High, nothing is above You and You are the Most Near, and nothing is nearer than You. Remove our debts from us and enrich us against poverty. 3","meaning_dv":"","reference":"1 The Scripture that was revealed to \u0027Isa (Jesus). 2 See Qur\u0027an Al-\u0027Alaq 96:15, where seizure by the forelock preceeds being cast into Hell. (Translator) 3 Muslim 4/2084.","source":"Hisn al-Muslim 107 - Sunnah.com","source_url":"https://sunnah.com/hisn:107","tags":["financial","protection","daily","weather"]},{"id":"hisn-108","n":108,"title":"Before sleeping","chapter_en":"Before sleeping","chapter_ar":"أذكار النوم","arabic":"الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا، وَكَفَانَا، وَآوَانَا، فَكَمْ مِمَّنْ لاَ كَافِيَ لَهُ وَلاَ مُؤْوِيَ","transliteration":"Alḥamdu lillāhil-lathī \u0027aṭ`amanā wa saqānā, wa kafānā, wa \u0027āwānā, fakam mimman lā kāfiya lahu wa lā mu\u0027wī.","meaning_en":"Praise is to Allah Who has provided us with food and with drink, sufficed us and gave us an abode, for how many are there with no provision and no home.","meaning_dv":"","reference":"Muslim 4/2085.","source":"Hisn al-Muslim 108 - Sunnah.com","source_url":"https://sunnah.com/hisn:108","tags":["financial","daily","gratitude"]},{"id":"hisn-109","n":109,"title":"Before sleeping","chapter_en":"Before sleeping","chapter_ar":"أذكار النوم","arabic":"اللّهُـمَّ عالِـمَ الغَـيْبِ وَالشّـهادَةِ فاطِـرَ السّماواتِ وَالأرْضِ رَبَّ كـلِّ شَـيءٍ وَمَليـكَه أَشْهَـدُ أَنْ لا إِلـهَ إِلاّ أَنْت أَعـوذُ بِكَ مِن شَـرِّ نَفْسـي وَمِن شَـرِّ الشَّيْـطانِ وَشِـرْكِه وَأَنْ أَقْتَـرِفَ عَلـى نَفْسـي سوءاً أَوْ أَجُـرَّهُ إِلـى مُسْـلِم","transliteration":"Allāhumma `ālima ‘l-ghaybi wash-shahādah, fātiras-samāwāti wa ‘l-ardh, Rabba kulli shay\u0027in wa malīkah, ash-hadu an lā ilāha illā ant, a`ūdhu bika min sharri nafsī, wa min sharrish-shayṭāni wa shirkih, wa an aqtarifa `alā nafsī sū\u0027an, aw ajurrahu ilā Muslim.","meaning_en":"O Allah, Knower of the unseen and the evident, Maker of the heavens and the earth, Lord of everything and its Master, I bear witness that there is none worthy of worship but You. I seek refuge in You from the evil of my soul, and from the evil of Satan and his helpers. (I seek refuge in You) from bringing evil upon my soul and from harming any Muslim.","meaning_dv":"","reference":"Abu Dawud 4/317. See also Al-Albani, SahihAt-Tirmidhi 3/142.","source":"Hisn al-Muslim 109 - Sunnah.com","source_url":"https://sunnah.com/hisn:109","tags":["protection","daily"]},{"id":"hisn-110","n":110,"title":"Before sleeping","chapter_en":"Before sleeping","chapter_ar":"أذكار النوم","arabic":"يقرأ ((ألم * تنزيل)) السجدة، و((تبارك الذي بيده الملك))","transliteration":"--","meaning_en":"Recite Surah 32 (As-Sajdah) and Surah 67 (Al-Mulk) in Arabic.","meaning_dv":"","reference":"At-Tirmidhi, An-Nasa\u0027i. See also Al-Albani, Sahihul-Jami \u0027 As-Saghir 4/255","source":"Hisn al-Muslim 110 - Sunnah.com","source_url":"https://sunnah.com/hisn:110","tags":["daily"]},{"id":"hisn-111","n":111,"title":"Before sleeping","chapter_en":"Before sleeping","chapter_ar":"أذكار النوم","arabic":"اللّهُـمَّ أَسْـلَمْتُ نَفْـسي إِلَـيْكَ، وَفَوَّضْـتُ أَمْـري إِلَـيْكَ، وَوَجَّـهْتُ وَجْـهي إِلَـيْكَ، وَأَلْـجَـاْتُ ظَهـري إِلَـيْكَ، رَغْبَـةً وَرَهْـبَةً إِلَـيْكَ، لا مَلْجَـأَ وَلا مَنْـجـا مِنْـكَ إِلاّ إِلَـيْكَ، آمَنْـتُ بِكِتـابِكَ الّـذي أَنْزَلْـتَ وَبِنَبِـيِّـكَ الّـذي أَرْسَلْـت","transliteration":"Allāhumma aslamtu nafsī ilayk, wa fawwaḍtu amrī ilayk, wa wajjahtu wajhī ilayk, wa alja\u0027tu ẓahrī ilayk, raghbatan wa rahbatan ilayk, lā malja\u0027a wa la manjā minka illā ilayk, āmantu bikitābika ‘l-ladhī anzalt, wa bi-nabiyyika ‘l-ladhī arsalt.","meaning_en":"O Allah,1 I submit myself to You, entrust my affairs to You, turn my face to You, and lay myself down depending upon You, hoping in You and fearing You. There is no refuge, and no escape, except to You. I believe in Your Book (the Qur\u0027an) that You revealed, and the Prophet whom You sent.","meaning_dv":"","reference":"1 \"Before you go to bed perform ablutions as you would for prayer, then lie down on your right side and say. . . \" The Prophet (ﷺ) said: \"Whoever says this and dies in his sleep, has died in a state of the natural monotheism (Fitrah).\" Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 11/113, Muslim 4/2081.","source":"Hisn al-Muslim 111 - Sunnah.com","source_url":"https://sunnah.com/hisn:111","tags":["anxiety","protection","prayer","daily"]},{"id":"hisn-112","n":112,"title":"When tossing and turning during the night","chapter_en":"When tossing and turning during the night","chapter_ar":"الدعاء إذا تقلب ليلاً","arabic":"لا إِلـهَ إِلاّ اللهُ الـواحِدُ القَهّـار رَبُّ السَّـمواتِ وَالأرْضِ وَما بَيْـنَهـما العَزيـزُ الغَـفّار","transliteration":"Lā ilāha illallāh al-Wāḥidul-Qahhār, Rabbus-samāwāti wa ‘l-arḍi wa mā baynahuma al-`Azīzul-Ghaffār.","meaning_en":"There is none worthy of worship but Allah, the One, the Victorious, Lord of the heavens and the earth and all that is between them, the All-Mighty, the All-Forgiving.","meaning_dv":"","reference":"This is to be said if you turn over in bed during the night. Al-Hakim graded it authentic and Ath-Thahabi agreed 1/540. Also see An-Nasa\u0027i, \u0027Amalul-Yawm wal-Laylah, and Ibn As-Sunni. See also Al-Albani, Sahihul-Jami\u0027 As-Saghir 4/ 213.","source":"Hisn al-Muslim 112 - Sunnah.com","source_url":"https://sunnah.com/hisn:112","tags":["forgiveness"]},{"id":"hisn-113","n":113,"title":"Upon experiencing unrest, fear, apprehensiveness during sleep","chapter_en":"Upon experiencing unrest, fear, apprehensiveness during sleep","chapter_ar":"دعاء القلق والفزع في النوم ومن بلي بالوحشة","arabic":"أَعـوذُ بِكَلِمـاتِ اللّهِ التّـامّـاتِ مِن غَضَـبِهِ وَعِـقابِهِ وَشَـرِّ عِبـادِهِ وَمِنْ هَمَـزاتِ الشَّـياطينِ وَأَنْ يَحْضـرون","transliteration":"A`ūdhu bikalimāti ‘llāhit-tāmmāti min ghaḍabihi wa `iqābihi wa sharri `ibādih, wa min hamazātish-shayāṭīni wa an yaḥḍurūn.","meaning_en":"I seek refuge in the Perfect Words of Allah from His anger and His punishment, from the evil of His slaves, and from the taunts of devils and from their presence.","meaning_dv":"","reference":"Abu Dawud 4/12. See also Al-Albani, Sahih At- Tirmidhi 3/171","source":"Hisn al-Muslim 113 - Sunnah.com","source_url":"https://sunnah.com/hisn:113","tags":["anxiety","protection","daily"]},{"id":"hisn-114","n":114,"title":"Upon seeing a good dream or a bad dream","chapter_en":"Upon seeing a good dream or a bad dream","chapter_ar":"ما يفعل من رأى الرؤيا أو الحلم","arabic":"يَنْفُثُ عَنْ يَسَارِهِ (ثلاثاً). يَسْتَعِيذُ بِاللَّهِ مِنَ الشَّيطَانِ وَمِنْ شَرِّ مَا رَأَى (ثَلاَثَ مَرَّاتٍ). لاَ يُحَدِّثْ بِهَا أَحَداً. يَــتَحَوَّلُ عَنْ جَنْبِهِ الَّذِي كَانَ عَلَيْهِ.","transliteration":"","meaning_en":"Spit to your left (three times).1 Seek refuge in Allah from the Devil and from the evil of what you have seen (three times).2 Do not speak about it to anyone.3 Turn over on your other side.4","meaning_dv":"","reference":"1. Muslim 4/1 772. 2. Muslim 4/1 772, 3. 3. Muslim 4/1772. 4. Muslim 4/1773.","source":"Hisn al-Muslim 114 - Sunnah.com","source_url":"https://sunnah.com/hisn:114","tags":["protection"]},{"id":"hisn-115","n":115,"title":"Upon seeing a good dream or a bad dream","chapter_en":"Upon seeing a good dream or a bad dream","chapter_ar":"ما يفعل من رأى الرؤيا أو الحلم","arabic":"يقوم يصلي إن أراد ذلك.ويَقُومُ يُصَلِّي إِنْ أَرَادَ ذَلِكَ.","transliteration":"","meaning_en":"Get up and pray if you desire to do so.","meaning_dv":"","reference":"Muslim 4/1773.","source":"Hisn al-Muslim 115 - Sunnah.com","source_url":"https://sunnah.com/hisn:115","tags":[]},{"id":"hisn-116","n":116,"title":"Qunoot Al-Witr","chapter_en":"Qunoot Al-Witr","chapter_ar":"دعاء قنوت الوتر","arabic":"اللّهُـمَّ اهْـدِنـي فـيمَنْ هَـدَيْـت، وَعـافِنـي فـيمَنْ عافَـيْت، وَتَوَلَّـني فـيمَنْ تَوَلَّـيْت، وَبارِكْ لـي فـيما أَعْطَـيْت، وَقِـني شَرَّ ما قَضَـيْت، فَإِنَّـكَ تَقْـضي وَلا يُقْـضى عَلَـيْك ، إِنَّـهُ لا يَـذِلُّ مَنْ والَـيْت، [ وَلا يَعِـزُّ مَن عـادَيْت ]، تَبـارَكْـتَ رَبَّـنا وَتَعـالَـيْت","transliteration":"Allāhumma’hdinī fī man hadayt, wa `āfinī fī man `āfayt, wa tawallanī fī man tawallayt, wa bārik lī fī mā a`atayt, wa qinī sharra mā qaḍayt, fa innaka taqḍī wa lā yuqḍā `alayk, innahu lā yadhillu man wālayt, [wa lā ya`izzu man `ādayt] , tabārakta Rabbanā wa ta`ālayt.","meaning_en":"O Allah, guide me with those whom You have guided, and strengthen me with those whom You have given strength. Take me to Your care with those whom You have taken to Your care. Bless me in what You have given me. Protect me from the evil You have ordained. Surely, You command and are not commanded, and none whom You have committed to Your care shall be humiliated [and none whom You have taken as an enemy shall taste glory]. You are Blessed, Our Lord, and Exalted.","meaning_dv":"","reference":"Abu Dawud, Ibn Majah, An-Nasa\u0027i, At-Tirmidhi, Ahmad, Ad-Darimi, Al-Hakim, and Al-Bayhaqi. See also Al-Albani, Sahih At-Tirmidhi 1/144, Sahih Ibn Majah 1/194, and \u0027Irwa\u0027ul-GhaW. 2/ 172.","source":"Hisn al-Muslim 116 - Sunnah.com","source_url":"https://sunnah.com/hisn:116","tags":["protection","prayer"]},{"id":"hisn-117","n":117,"title":"Qunoot Al-Witr","chapter_en":"Qunoot Al-Witr","chapter_ar":"دعاء قنوت الوتر","arabic":"اللّهُـمَّ إِنِّـي أَعـوذُ بِرِضـاكَ مِنْ سَخَطِـك، وَبِمُعـافاتِـكَ مِنْ عُقوبَـتِك، وَأَعـوذُ بِكَ مِنْـك، لا أُحْصـي ثَنـاءً عَلَـيْك، أَنْـتَ كَمـا أَثْنَـيْتَ عَلـى نَفْسـِك","transliteration":"Allāhumma innī a`ūdhu biriḍāka min sakhaṭik, wa bimu`āfātika min `uqūbatik, wa a`ūdhu bika mink, lā uḥṣī thanā\u0027an `alayk, Anta kamā athnayta `alā nafsik.","meaning_en":"O Allah, I seek refuge with Your Pleasure from Your anger. I seek refuge in Your forgiveness from Your punishment. I seek refuge in You from You. I cannot count Your praises, You are as You have praised Yourself.","meaning_dv":"","reference":"Abu Dawud, Ibn Majah, An-Nasa\u0027i, At-Tirmidhi, Ahmad. See Al-Albani, Sahih At-Tirmidhi 3/180, Sahih Ibn Majah 1/194, and \u0027Irwa\u0027ul-Ghalil. 2/ 175.","source":"Hisn al-Muslim 117 - Sunnah.com","source_url":"https://sunnah.com/hisn:117","tags":["forgiveness","protection","prayer","daily","gratitude"]},{"id":"hisn-118","n":118,"title":"Qunoot Al-Witr","chapter_en":"Qunoot Al-Witr","chapter_ar":"دعاء قنوت الوتر","arabic":"اللّهُـمَّ إِيّـاكَ نعْـبُدْ، وَلَـكَ نُصَلّـي وَنَسْـجُد، وَإِلَـيْكَ نَسْـعى وَنَحْـفِد، نَـرْجو رَحْمَـتَك، وَنَخْشـى عَـذابَك، إِنَّ عَـذابَكَ بالكـافرين ملْحَـق. اللّهُـمَّ إِنّا نَسْتَعـينُكَ وَنَسْتَـغْفِرُك، وَنُثْـنـي عَلَـيْك الخَـيْرَ، وَلا نَكْـفُرُك، وَنُـؤْمِنُ بِك، وَنَخْـضَعُ لَكَ وَنَخْـلَعُ مَنْ يَكْـفرُك","transliteration":"Allāhumma iyyāka na`bud, wa laka nuṣallī wa nasjud, wa ilayka nas`ā wa naḥfid, narjū raḥmatak, wa nakhshā `adhābak, inna `adhābaka bilkāfirīna mulḥaq. Allāhumma innā nasta`īnuk, wa nastaghfiruk, wa nuthnī `alaykal-khayr, wa lā nakfuruk, wa nu\u0027minu bik, wa nakhḍa`u lak, wa nakhla`u man yakfuruk.","meaning_en":"O Allah, You alone do we worship, and to You we pray and bow down prostrate. To You we hasten to worship and to serve. Our hope is for Your mercy, and we fear Your punishment. Surely, Your punishment of the disbelievers is at hand. O Allah, we seek Your help and Your forgiveness, and we praise You beneficently. We do not deny You and we believe in You. We surrender to You and renounce whoever disbelieves in You.","meaning_dv":"","reference":"Al-Bayhaqi graded its chain authentic in As-Sunan Al-Kubra. Al-Albani said in \u0027Irwa\u0027ul-GhaliL 2/170 that its chain is authentic as a statement of \u0027Umar.","source":"Hisn al-Muslim 118 - Sunnah.com","source_url":"https://sunnah.com/hisn:118","tags":["anxiety","forgiveness","prayer","gratitude"]},{"id":"hisn-119","n":119,"title":"Immediately after salam of the witr prayer","chapter_en":"Immediately after salam of the witr prayer","chapter_ar":"الذكر عقب السلام من الوتر","arabic":"\"سبحان الملك القدوس\" ثلاث مرات والثالثة يجهر بها ويمد بها صوته \"ربِّ الملائكةِ والرّوح\"","transliteration":"Subḥāna ‘l-Maliki ‘l-Quddūs. [Recite three times, and raise and extend the voice on the third time and say...] Rabbi ‘l-Malā\u0027ikati war-rūh.","meaning_en":"Glory is to the King, the Holy. [Recite three times in Arabic, and raise and extend the voice on the third time and say...] Lord of the angels and the Spirit.","meaning_dv":"","reference":"An-Nasa\u0027i 3/244, Ad-Daraqutni and others. The final addition is from Ad-Daraqutni\u0027s version 2/ 31 and its chain of narration is authentic. See the checking of Zadul-Ma\u0027ad by Shu\u0027aib Al-Arna\u0027ut and \u0027Abdul-Qadir Al-Arna\u0027ut 1/337.","source":"Hisn al-Muslim 119 - Sunnah.com","source_url":"https://sunnah.com/hisn:119","tags":["prayer"]},{"id":"hisn-120","n":120,"title":"For anxiety and sorrow","chapter_en":"For anxiety and sorrow","chapter_ar":"دعاء الهم والحزن","arabic":"اللّهُـمَّ إِنِّي عَبْـدُكَ ابْنُ عَبْـدِكَ ابْنُ أَمَتِـكَ نَاصِيَتِي بِيَـدِكَ مَاضٍ فِيَّ حُكْمُكَ عَدْلٌ فِيَّ قَضَاؤكَ أَسْأَلُـكَ بِكُلِّ اسْمٍ هُوَ لَكَ سَمَّـيْتَ بِهِ نَفْسَكَ أِوْ أَنْزَلْتَـهُ فِي كِتَابِكَ أَوْ عَلَّمْـتَهُ أَحَداً مِنْ خَلْقِـكَ أَوِ اسْتَـأْثَرْتَ بِهِ فِي عِلْمِ الغَيْـبِ عِنْـدَكَ أَنْ تَجْـعَلَ القُرْآنَ رَبِيـعَ قَلْبِـي وَنورَ صَـدْرِي وجَلَاءَ حُـزْنِي وذَهَابَ هَمِّـي","transliteration":"Allāhumma innī `abduk, ibnu `abdik, ibnu amatik, nāsiyatī biyadik, māḍin fiyya ḥukmuk, `adlun fiyya qaḍā\u0027uk, as\u0027aluka bikullis’min huwa lak, sammayta bihi nafsak, aw anzaltahu fī kitābik, aw `allamtahu aḥadan min khalqik, aw‘ista\u0027tharta bihi fī `ilmil-ghaybi `indak, an taj`ala ‘l-Qur\u0027āna rabī`a qalbī, wa nūra ṣadrī, wa jalā\u0027a ḥuznī, wa dhahāba hammī.","meaning_en":"O Allah, I am Your slave, and the son of Your male slave, and the son of your female slave. My forehead is in Your Hand (i.e. you have control over me). Your Judgment upon me is assured, and Your Decree concerning me is just. I ask You by every Name that You have named Yourself with, revealed in Your Book, taught any one of Your creation, or kept unto Yourself in the knowledge of the unseen that is with You, to make the Qur\u0027an the spring of my heart, and the light of my chest, the banisher of my sadness, and the reliever of my distress.","meaning_dv":"","reference":"Ahmad 1/391, and Al-Albani graded it authentic.","source":"Hisn al-Muslim 120 - Sunnah.com","source_url":"https://sunnah.com/hisn:120","tags":["anxiety"]},{"id":"hisn-121","n":121,"title":"For anxiety and sorrow","chapter_en":"For anxiety and sorrow","chapter_ar":"دعاء الهم والحزن","arabic":"اللّهُـمَّ إِنِّي أَعْوذُ بِكَ مِنَ الهَـمِّ وَ الْحُـزْنِ، والعًجْـزِ والكَسَلِ والبُخْـلِ والجُـبْنِ، وضَلْـعِ الـدَّيْنِ وغَلَبَـةِ الرِّجال","transliteration":"Allāhumma \u0027innī \u0027a`ūdhu bika mina ‘l-ḥammi wa ‘l-ḥuzn, wa ‘l-`ajzi wa ‘l-kasal, wa ‘l-bukhli wa ‘l-jubn, wa ḍala`id-dayn, wa ghalabatir-rijāl.","meaning_en":"O Allah, I seek refuge in you from grief and sadness, from weakness and from laziness, from miserliness and from cowardice, from being overcome by debt and overpowered by men (i.e. others).","meaning_dv":"","reference":"Al-Bukhari 7/158. See also Al-Asqalani, Fathul-Bari 11/173.","source":"Hisn al-Muslim 121 - Sunnah.com","source_url":"https://sunnah.com/hisn:121","tags":["anxiety","financial","protection"]},{"id":"hisn-122","n":122,"title":"For one in distress","chapter_en":"For one in distress","chapter_ar":"دعاء الكرب","arabic":"لَا إلَهَ إِلَّا اللَّهُ الْعَظـيمُ الْحَلِـيمْ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ العَـرْشِ العَظِيـمِ، لَا إِلَـهَ إِلَّا اللَّهْ رَبُّ السَّمَـوّاتِ ورّبُّ الأَرْضِ ورَبُّ العَرْشِ الكَـريم","transliteration":"Lā ilāha illallāh al-`Aẓīmul-Ḥalīm, lā ilāha illallāh Rabbu ‘l-`Arshi ‘l-\u0027Aẓīm, lā ilāha illallāh Rabbus-samāwāti wa Rabbu ‘l-arḍ wa Rabbu ‘l-`Arshi ‘l-Karīm.","meaning_en":"There is none worthy of worship but Allah, the Mighty, the Forbearing. There is none worthy of worship but Allah, Lord of the Magnificent Throne. There is none worthy of worship but Allah, Lord of the heavens and Lord of the earth, and Lord of the Noble Throne.","meaning_dv":"","reference":"Al-Bukhari 8/154, Muslim 4/2092","source":"Hisn al-Muslim 122 - Sunnah.com","source_url":"https://sunnah.com/hisn:122","tags":["anxiety"]},{"id":"hisn-123","n":123,"title":"For one in distress","chapter_en":"For one in distress","chapter_ar":"دعاء الكرب","arabic":"اللّهُـمَّ رَحْمَتَـكَ أَرْجـو فَلا تَكِلـني إِلى نَفْـسي طَـرْفَةَ عَـيْن، وَأَصْلِـحْ لي شَأْنـي كُلَّـه لَا إِلَهَ إِلَّا أنْـت","transliteration":"Allāhumma raḥmataka arjū falā takilnī ilā nafsī ṭarfata `ayn, wa aṣliḥ lī sha\u0027nī kullah, lā ilāha illā ant.","meaning_en":"O Allah, I hope for Your mercy. Do not leave me to myself even for the blinking of an eye (i.e. a moment). Correct all of my affairs for me. There is none worthy of worship but You.","meaning_dv":"","reference":"Abu Dawud 4/324, Ahmad 5/42. Al-Albani graded it as good in Sahih Abu Dawud 3/959.","source":"Hisn al-Muslim 123 - Sunnah.com","source_url":"https://sunnah.com/hisn:123","tags":["anxiety","protection"]},{"id":"hisn-124","n":124,"title":"For one in distress","chapter_en":"For one in distress","chapter_ar":"دعاء الكرب","arabic":"لَا إِلَهَ إِلَّا أنْـت سُـبْحانَكَ إِنِّي كُنْـتُ مِنَ الظّـالِميـن","transliteration":"Lā ilāha illā anta subḥānaka innī kuntu minaẓ-ẓālimīn.","meaning_en":"There is none worthy of worship but You, glory is to You. Surely, I was among the wrongdoers.","meaning_dv":"","reference":"At-Tirmidhi 5/529. Al-Hakim declared it authentic and Ath-Thahabi agreed with him 1/ 505. See also Al-Albani, Sahih At-Tirmidhi 3/168.","source":"Hisn al-Muslim 124 - Sunnah.com","source_url":"https://sunnah.com/hisn:124","tags":["anxiety"]},{"id":"hisn-125","n":125,"title":"For one in distress","chapter_en":"For one in distress","chapter_ar":"دعاء الكرب","arabic":"اللهُ اللهُ رَبِّي لا أُشْـرِكُ بِهِ شَيْـئاً","transliteration":"Allāh, Allāhu Rabbī lā ushriku bihi shay\u0027a.","meaning_en":"Allah, Allah is my Lord. I do not associate anything with Him.","meaning_dv":"","reference":"Abu Dawud 2/87. See also Al-Albani, Sahih Ibn Mdjah 2/335.","source":"Hisn al-Muslim 125 - Sunnah.com","source_url":"https://sunnah.com/hisn:125","tags":["anxiety"]},{"id":"hisn-126","n":126,"title":"Upon encountering an enemy or those of authority","chapter_en":"Upon encountering an enemy or those of authority","chapter_ar":"دعاء لقاء العدو وذي السلطان","arabic":"اللّهُـمَّ إِنا نَجْـعَلُكَ في نُحـورِهِـم، وَنَعـوذُ بِكَ مِنْ شُرورِهـمْ","transliteration":"Allāhumma innā naj`aluka fī nuḥūrihim wa na`ūdhu bika min shurūrihim.","meaning_en":"O Allah, we ask You to restrain them by their necks, and we seek refuge in You from their evil.","meaning_dv":"","reference":"Abu Dawud 2/89, and Al-Hakim graded it authentic and Ath-Thahabi agreed 2/142.","source":"Hisn al-Muslim 126 - Sunnah.com","source_url":"https://sunnah.com/hisn:126","tags":["protection","weather"]},{"id":"hisn-127","n":127,"title":"Upon encountering an enemy or those of authority","chapter_en":"Upon encountering an enemy or those of authority","chapter_ar":"دعاء لقاء العدو وذي السلطان","arabic":"اللّهُـمَّ أَنْتَ عَضُـدي، وَأَنْتَ نَصـيري، بِكَ أَجـولُ وَبِكَ أَصـولُ وَبِكَ أُقـاتِل","transliteration":"Allāhumma anta `aḍudī, wa anta naṣīrī, bika ajūlu, wa bika aṣūlu, wa bika uqātil.","meaning_en":"O Allah, You are my strength and You are my support. For Your sake, I go forth and for Your sake, I advance and for Your sake, I fight.","meaning_dv":"","reference":"Abu Dawud 3/42, At-Tirmidhi 5/572. See also Al-Albani, Sahih At-Tirmidhi 3/183.","source":"Hisn al-Muslim 127 - Sunnah.com","source_url":"https://sunnah.com/hisn:127","tags":["protection"]},{"id":"hisn-128","n":128,"title":"Upon encountering an enemy or those of authority","chapter_en":"Upon encountering an enemy or those of authority","chapter_ar":"دعاء لقاء العدو وذي السلطان","arabic":"حَسْبُـنا اللهُ وَنِعْـمَ الوَكـيل","transliteration":"Ḥasbunallāhu wa ni`mal-wakīl.","meaning_en":"Allah is sufficient for us and the best of those on whom to depend.","meaning_dv":"","reference":"Al-Bukhari, 5/172.","source":"Hisn al-Muslim 128 - Sunnah.com","source_url":"https://sunnah.com/hisn:128","tags":["protection"]},{"id":"hisn-129","n":129,"title":"For one afraid of the ruler\u0027s injustice","chapter_en":"For one afraid of the ruler\u0027s injustice","chapter_ar":"دعاء من خاف ظلم السلطان","arabic":"اللَّهُمَّ ربَّ السَّمَوَاتِ السَّبْعِ، وَرَبَّ الْعَرْشِ الْعَظِيمِ، كُنْ لِي جَاراً مِنْ فُلاَنِ بْنِ فُلاَنٍ، وَأَحْزَابِهِ مِنْ خَلاَئِقِكَ، أَنْ يَفْرُطَ عَلَيَّ أَحَدٌ مِنْهُمْ أَوْ يَطْغَى، عَزَّ جَارُكَ، وَجَلَّ ثَنَاؤُكَ، وَلاَ إِلَهَ إِلاَّ أَنْتَ","transliteration":"Allāhumma Rabbas-samāwātis-sab`, wa Rabba ‘l-`Arshi ‘l-`Aẓīm, kun lī jāran min [here you mention the person\u0027s name], wa aḥzābihi min khalā\u0027iqik, an yafruṭa `alayya aḥadun minhum aw yaṭghā, `azza jāruk, wa jalla thanā\u0027uk, wa lā ilāha illā ant.","meaning_en":"O Allah, Lord of the seven heavens, Lord of the Magnificent Throne, be for me a support against [such and such a person] and his helpers from among your creatures, lest any of them abuse me or do me wrong. Mighty is Your patronage, and glorious are Your praises. There is none worthy of worship but You.","meaning_dv":"","reference":"Al-Bukhari, Al-\u0027Adab Al-Mufrad (no. 707). Al-Albani graded it authentic in Sahih Al-\u0027Adab Al-Mufrad (no. 545).","source":"Hisn al-Muslim 129 - Sunnah.com","source_url":"https://sunnah.com/hisn:129","tags":["anxiety","gratitude"]},{"id":"hisn-130","n":130,"title":"For one afraid of the ruler\u0027s injustice","chapter_en":"For one afraid of the ruler\u0027s injustice","chapter_ar":"دعاء من خاف ظلم السلطان","arabic":"الله أكبر، الله أعز من خلقه جميعاً ، الله أعز مما أخاف وأحذر ، أعوذ بالله الذي لا إله إلا هو ، الممسك السموات السبع أن يقعن على الأرض إلا بإذنه ، من شر عبدك فلان ، وجنوده وأتباعه وأشياعه ، من الجن والأنس ، اللهم كن لي جاراً من شرهم ، جل ثناؤك وعز جارك ، وتبارك اسمك ، ولا إله غيرك (ثلاث مرات)","transliteration":"Allāhu Akbar, Allāhu a`azzu min khalqihi jamī`a, Allāhu a`azzu mimmā akhāfu wa aḥdhar, a`ūdhu billāhi ‘l-ladhī lā ilāha illā hū, almumsikis-samāwātis-sab`i an yaqa`na `ala ‘l-arḍi illā bi idhnih, min sharri `abdika [name of the person], wa junūdihi wa atbā`ihi wa ashyā`ih, mina ‘l-jinni wa ‘l-ins, Allāhumma kun lī jāran min sharrihim, jalla thanā\u0027uk, wa `azza jāruk, wa tabāraka-smuk, wa lā ilāha ghayruk.","meaning_en":"Allah is the Most Great, Mightier than all His creation. He is Mightier than what I fear and dread. I seek refuge in Allah, Who there is none worthy of worship but Him. He is the One Who holds the seven heavens from falling upon the earth except by His command. [I seek refuge in You Allah] from the evil of Your slave [name of the person], and his helpers, his followers, and his supporters from among the jinn and mankind. O Allah, be my support against their evil. Glorious are Your praises and mighty is Your patronage. Blessed is Your Name, there is no true God but You. (Recite three times in Arabic.)","meaning_dv":"","reference":"Al-Bukhari, 5/172.","source":"Hisn al-Muslim 130 - Sunnah.com","source_url":"https://sunnah.com/hisn:130","tags":["anxiety","protection","gratitude"]},{"id":"hisn-131","n":131,"title":"Against enemies","chapter_en":"Against enemies","chapter_ar":"الدعاء على العدو","arabic":"اللَّهُمَّ مُنْزِلَ الْكِتَاب سَرِيعَ الْحِسَاب اهْزِم الأَحْزَاب اللَّهُمَّ اهْزِمْهُمْ وَ زَلْزِلْهُم","transliteration":"Allāhumma munzila ‘l-kitāb, sarī`a ‘l-ḥisāb, ihzimi ‘l-aḥzāb, Allāhumma-hzimhum wa zalzilhum.","meaning_en":"O Allah, Revealer of the Book, Swift to account, defeat the groups (of disbelievers). O Allah, defeat them and shake them.","meaning_dv":"","reference":"Muslim 3/1362.","source":"Hisn al-Muslim 131 - Sunnah.com","source_url":"https://sunnah.com/hisn:131","tags":[]},{"id":"hisn-132","n":132,"title":"When being afraid of a group of people","chapter_en":"When being afraid of a group of people","chapter_ar":"ما يقول من خاف قوماً","arabic":"اللَّهُمَّ اكْفِنِيهِم بمَا شِئْت","transliteration":"Allāhummak-finīhim bimā shi\u0027t.","meaning_en":"O Allah, suffice (i.e. protect) me against them however You wish.","meaning_dv":"","reference":"Muslim 4/2300.","source":"Hisn al-Muslim 132 - Sunnah.com","source_url":"https://sunnah.com/hisn:132","tags":["anxiety"]},{"id":"hisn-133","n":133,"title":"For one afflicted with doubt in his faith","chapter_en":"For one afflicted with doubt in his faith","chapter_ar":"دعاء من أصابه شك في الإيمان","arabic":"يَسْتَعِيذُ بِاللَّهِ. يَنْتَهِي عَمَّا شك فِيهِ.","transliteration":"A`ūdhu billāh","meaning_en":"(Say:","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 6/336, Muslim 1/120.","source":"Hisn al-Muslim 133 - Sunnah.com","source_url":"https://sunnah.com/hisn:133","tags":[]},{"id":"hisn-134","n":134,"title":"For one afflicted with doubt in his faith","chapter_en":"For one afflicted with doubt in his faith","chapter_ar":"دعاء من أصابه شك في الإيمان","arabic":"يقول\" آمنت بالله ورسله\"","transliteration":"Āmantu billāhi wa Rusulih.","meaning_en":"(Say:","meaning_dv":"","reference":"Muslim, 1/119-20.","source":"Hisn al-Muslim 134 - Sunnah.com","source_url":"https://sunnah.com/hisn:134","tags":[]},{"id":"hisn-135","n":135,"title":"For one afflicted with doubt in his faith","chapter_en":"For one afflicted with doubt in his faith","chapter_ar":"دعاء من أصابه شك في الإيمان","arabic":"يقرأ قوله تعالى ((هُوَ الأوَّلُ، وَالآخِـرُ، وَالظّـاهِـرُ، وَالْبـاطِـنُ، وَهُوَ بِكُلِّ شَيءٍ عَلـيم))","transliteration":"Huwa ‘l-Awwalu wa ‘l-Ākhir, waẓ-Ẓāhiru wal-Bāṭin, wa huwa bikulli shay\u0027in `Alīm.","meaning_en":"(Recite the Ayat) He is the First and the Last, the Most High and the Most Near. And He is the Knower of all things (in Arabic).","meaning_dv":"","reference":"Al-Hadid 57:3, Abu Dawud 4/329. Al-Albani graded it good in SahihAbu Dawud, 3/962.","source":"Hisn al-Muslim 135 - Sunnah.com","source_url":"https://sunnah.com/hisn:135","tags":[]},{"id":"hisn-136","n":136,"title":"Settling a debt","chapter_en":"Settling a debt","chapter_ar":"الدعاء قضاء الدين","arabic":"اللّهُـمَّ اكْفِـني بِحَلالِـكَ عَنْ حَـرامِـك، وَأَغْنِـني بِفَضْـلِكَ عَمَّـنْ سِـواك","transliteration":"Allāhummak-finī biḥalālika `an ḥarāmik, wa \u0027aghninī bi faḍlika `amman siwāk.","meaning_en":"O Allah, suffice me with what You have allowed instead of what You have forbidden, and make me independent of all others besides You.","meaning_dv":"","reference":"At-Tirmidhi 5/560. See also Al-Albani, Sahih At-Tirmidhi 3/180.","source":"Hisn al-Muslim 136 - Sunnah.com","source_url":"https://sunnah.com/hisn:136","tags":["financial"]},{"id":"hisn-137","n":137,"title":"Settling a debt","chapter_en":"Settling a debt","chapter_ar":"الدعاء قضاء الدين","arabic":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ","transliteration":"Allāhumma innī a`ūdhu bika mina ‘l-ḥammi wa ‘l-ḥazan, wa ‘l-`ajzi wa ‘l-kasal, wa ‘l-bukhli wa ‘l-jubn, wa ḍala`id-dayni wa ghalabatir-rijāl.","meaning_en":"O Allah! I seek refuge with You from worry and grief, from incapacity and laziness, from cowardice and miserliness, from being heavily in debt and from being overpowered by (other) men.","meaning_dv":"","reference":"Al-Bukhari 7/158.","source":"Hisn al-Muslim 137 - Sunnah.com","source_url":"https://sunnah.com/hisn:137","tags":["anxiety","financial","protection"]},{"id":"hisn-138","n":138,"title":"For one afflicted by whisperings in prayer or recitation","chapter_en":"For one afflicted by whisperings in prayer or recitation","chapter_ar":"دعاء الوسوسة في الصلاة والقراءة","arabic":"أَعُوذُ بِاللَّهِ مِنَ الشَّيطَانِ الرَّجِيمِ، وَاتْفُلْ عَلَى يَسَارِكَ (ثلاثاً)","transliteration":"A`ūdhu billāhi minash-shayṭānir-rajīm.","meaning_en":"(Say:","meaning_dv":"","reference":"Muslim 4/1729.","source":"Hisn al-Muslim 138 - Sunnah.com","source_url":"https://sunnah.com/hisn:138","tags":["prayer"]},{"id":"hisn-139","n":139,"title":"For one whose affairs have become difficult","chapter_en":"For one whose affairs have become difficult","chapter_ar":"دعاء من استصعب عليه أمر","arabic":"اللَّهُمَّ لاَ سَهْلَ إِلاَّ مَا جَعَلْتَهُ سَهْلاً، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلاً","transliteration":"Allāhumma lā saḥla illā ma ja`altahu saḥla wa anta taj`alu ‘l-ḥazna idhā shi\u0027ta saḥla.","meaning_en":"O Allah, there is no ease other than what You make easy. If You please You ease sorrow.","meaning_dv":"","reference":"Ibn Hibban in his Sahih (no. 2427), and Ibn As- Sunni (no. 351). Al-Hafidh (Ibn Hajar) said that this Hadith is authentic. It was also declared authentic by \u0027Abdul-Qadir Al-Arna\u0027ut in his checking of An-Nawawi\u0027s Kitabul-Athkarp. 106.","source":"Hisn al-Muslim 139 - Sunnah.com","source_url":"https://sunnah.com/hisn:139","tags":["anxiety"]},{"id":"hisn-140","n":140,"title":"Upon committing a sin","chapter_en":"Upon committing a sin","chapter_ar":"ما يقول ويفعل من أذنب ذنباً","arabic":"مَا مِنْ عَبْدٍ يُذنِبُ ذَنْباً فَيُحْسِنُ الطُّهُورَ، ثُمَّ يَقُومُ فَيُصَلِّي رَكْعَتَيْنِ، ثُمَّ يَسْتَغْفِرُ اللَّهَ إِلاَّ غَفَرَ اللَّهُ لَهُ","transliteration":"","meaning_en":"There is not any slave of Allah who commits a sin, then he perfects his purification and stands to pray two Rak\u0027ahs of prayer, then seeks Allah\u0027s forgiveness, except that Allah will forgive him.","meaning_dv":"","reference":"Abu Dawud 2/86, At-Tirmidhi 2/257. Al-Albani graded it authentic in Sahih Abu Dawud 1/283.","source":"Hisn al-Muslim 140 - Sunnah.com","source_url":"https://sunnah.com/hisn:140","tags":["forgiveness","prayer"]},{"id":"hisn-141","n":141,"title":"For expelling the devil and his whisperings","chapter_en":"For expelling the devil and his whisperings","chapter_ar":"دعاء طرد الشيطان ووساوسه","arabic":"الاستعاذة بالله منه","transliteration":"A`ūdhu billāhi minash-shayṭānir-rajīm.","meaning_en":"Seeking refuge with Allah against him (i.e. by saying I seek refuge in Allah from Satan the outcast).","meaning_dv":"","reference":"Abu Dawud 1/206, At-Tirmidhi. See also Al-Albani, Sahih At-Tirmidhi 1/77, and Surat Al-Mu\u0027minun, 23:98-9.","source":"Hisn al-Muslim 141 - Sunnah.com","source_url":"https://sunnah.com/hisn:141","tags":["protection"]},{"id":"hisn-142","n":142,"title":"For expelling the devil and his whisperings","chapter_en":"For expelling the devil and his whisperings","chapter_ar":"دعاء طرد الشيطان ووساوسه","arabic":"الْأَذَانُ","transliteration":"--","meaning_en":"The call to prayer - \u0027Athan.","meaning_dv":"","reference":"Muslim 1/291, Al-Bukhari 1/151.","source":"Hisn al-Muslim 142 - Sunnah.com","source_url":"https://sunnah.com/hisn:142","tags":["protection","prayer"]},{"id":"hisn-143","n":143,"title":"For expelling the devil and his whisperings","chapter_en":"For expelling the devil and his whisperings","chapter_ar":"دعاء طرد الشيطان ووساوسه","arabic":"الْأَذْكَارُ وَقِرَاءَةُ الْقُرْآنِ","transliteration":"--","meaning_en":"Saying words of Allah\u0027s remembrance (Thikr) and recitation of the Qur\u0027an.","meaning_dv":"","reference":"\"Do not turn your homes into graveyards, surely the Devil flees from the house in which Surat Al-Baqarah is read,\" Muslim 1/539. The Devil is also driven out by the invocations for morning and evening, those that are said before sleeping and upon waking up, those for entering and leaving the house, including those for entering and leaving the mosque, and by many other authentic invocations taught to us by the Prophet (ﷺ) such as the reading of \u0027Ayatul-Kursi, (Al-Baqarah 2:255), and the last two \u0027Ayat of Surat Al-Baqarah before going to sleep. Whoever says: \"There is none worthy of worship but Allah alone, Who has no partner, His is the dominion and His is the praise, and he is Able to do all things,\" one hundred times, it will be a protection for him from the Devil throughout the day.\u0027","source":"Hisn al-Muslim 143 - Sunnah.com","source_url":"https://sunnah.com/hisn:143","tags":["protection","prayer","daily","gratitude","death"]},{"id":"hisn-144","n":144,"title":"When stricken with a mishap or overtaken by an affair","chapter_en":"When stricken with a mishap or overtaken by an affair","chapter_ar":"الدعاء حينما يقع مالا يرضاه أو غلب على أمره","arabic":"قَدَّرَ اللهُ وَما شـاءَ فَعَـل","transliteration":"Qaddarallāhu wa mā shā\u0027a fa`al.","meaning_en":"It is the Decree of Allah and He does whatever He wills.","meaning_dv":"","reference":"\"The strong believer is better and more dear to Allah than the weak believer, and in each of them there is good. Be vigilant for what is to your benefit and seek the help of Allah and do not falter. But when you are striken by some setback, do not say: \u0027If only I had done such and such,\u0027 rather say: \u0027It is the Decree of Allah and He does whatever He wills.\u0027 For verily the saying \u0027if (i.e. if only I had) begins the work of the Devil.\" Muslim 4/2052.","source":"Hisn al-Muslim 144 - Sunnah.com","source_url":"https://sunnah.com/hisn:144","tags":["patience","protection"]},{"id":"hisn-145","n":145,"title":"Congratulation on the occasion of a birth and its reply","chapter_en":"Congratulation on the occasion of a birth and its reply","chapter_ar":"تهنئة المولود له وجوابه","arabic":"(بَارَكَ اللَّهُ لَكَ فِي الْمَوْهُوبِ لَكَ، وَشَكَرْتَ الْوَاهِبَ، وَبَلَغَ أَشُدَّهُ، وَرُزِقْتَ بِرَّهُ). وَيَرُدُّ عَلَيْهِ الْمُهَــــــنَّأُ فَيَقُولُ: (بَارَكَ اللَّهُ لَكَ وَبَارَكَ عَلَيْكَ، وَجَزَاكَ اللَّهُ خَيْراً، وَرَزَقَكَ اللَّهُ مِثْلَهُ، وَأَجْزَلَ ثَوَابَكَ).","transliteration":"Bārakallāhu laka fi ‘l-mawhūbi lak, wa shakarta ‘l-wāhib, wa balagha ashuddah, wa ruziqta birrah. The reply of the person being congratulated is to say:","meaning_en":"May Allah bless you with His gift to you, and may you (the new parent) give thanks, may the child reach the maturity of years, and may you be granted its righteousness. The reply of the person being congratulated is to say: May Allah bless you, and shower His blessings upon you, and may Allah reward you well and bestow upon you its like and reward you abundantly","meaning_dv":"","reference":"An-Nawawi, Kitdbul-\u0027Athkarp. 349, and Sahihul-\u0027Athkar2/7l3 by Saleem Al-Hilali.","source":"Hisn al-Muslim 145 - Sunnah.com","source_url":"https://sunnah.com/hisn:145","tags":["forgiveness","family","gratitude"]},{"id":"hisn-146","n":146,"title":"Placing childen under Allah’s protection","chapter_en":"Placing childen under Allah’s protection","chapter_ar":"ما يعوذ به الأولاد","arabic":"كان رسول الله صلى الله عليه وسلم يعوذ الحسن والحسين \" أعيذكما بكلمات الله التامة ، من كل شيطان وهامة ، ومن كل عينِ لامة \"","transliteration":"The Prophet (ﷺ) used to seek Allah\u0027s protection for Al-Hasan and Al-Husain by saying:","meaning_en":"I seek protection for you in the Perfect Words of Allah from every devil and every beast, and from every envious blameworthy eye.","meaning_dv":"","reference":"Al-Bukhari4/119.","source":"Hisn al-Muslim 146 - Sunnah.com","source_url":"https://sunnah.com/hisn:146","tags":["family","protection"]},{"id":"hisn-147","n":147,"title":"When visiting the sick","chapter_en":"When visiting the sick","chapter_ar":"الدعاء للمريض في عيادته","arabic":"لا بأْسَ طَهـورٌ إِنْ شـاءَ الله","transliteration":"Lā ba\u0027sa ṭahūrun in shā Allāh.","meaning_en":"Do not worry, it will be a purification (for you), Allah willing.","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani Fathul-Bari 10/118.","source":"Hisn al-Muslim 147 - Sunnah.com","source_url":"https://sunnah.com/hisn:147","tags":["anxiety","illness"]},{"id":"hisn-148","n":148,"title":"When visiting the sick","chapter_en":"When visiting the sick","chapter_ar":"الدعاء للمريض في عيادته","arabic":"أَسْـأَلُ اللهَ العَـظيـم، رَبَّ العَـرْشِ العَـظيـم أَنْ يَشْفـيك . (سبع مرات)","transliteration":"As\u0027alullāha ‘l-`Aẓīma Rabba ‘l-`Arshil-`Aẓīmi an yashfiyak.","meaning_en":"I ask Almighty Allah, Lord of the Magnificent Throne, to make you well. (Recite seven times in Arabic .)","meaning_dv":"","reference":"At-Tirmidhi, Abu Dawud. See also Al-Albani, Sahih At-Tirmidhi 2/210 and Sahihul-Jami\u0027 As-Saghir 5/180.","source":"Hisn al-Muslim 148 - Sunnah.com","source_url":"https://sunnah.com/hisn:148","tags":["illness"]},{"id":"hisn-149","n":149,"title":"Excellence of visiting the sick","chapter_en":"Excellence of visiting the sick","chapter_ar":"فضل عيادة المريض","arabic":"قَالَ صلى الله عليه وسلم: (إِذَا عَادَ الرَّجُلُ أَخَاهُ الْمُسْلِمَ مَشَى فِي خِرَافَةِ الْجَنَّةِ حَتَّى يَجْلِسَ، فَإِذَا جَلَسَ غَمَرَتْهُ الرَّحْمَةُ، فَإِنْ كَانَ غُدْوَةً صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى يُمْسِيَ، وَإِنْ كَانَ مَسَاءً صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى يُصْبِحَ)","transliteration":"","meaning_en":"When a man goes to visit his sick Muslim brother, he walks along a path of Paradise until he sits, and when he sits he is cloaked in mercy. If he comes in the morning, seventy thousand angels pray for him until evening, and if he comes in the evening, seventy thousand angels pray for him until morning.","meaning_dv":"","reference":"","source":"Hisn al-Muslim 149 - Sunnah.com","source_url":"https://sunnah.com/hisn:149","tags":["illness"]},{"id":"hisn-150","n":150,"title":"When the sick have renounced all hope of life","chapter_en":"When the sick have renounced all hope of life","chapter_ar":"دعاء المريض الذي يئس من حياته","arabic":"أللّهُـمَّ اغْفِـرْ لي وَارْحَمْـني وَأَلْحِقْـني بِالرَّفـيقِ الأّعْلـى","transliteration":"Allāhumma’ghfir lī warḥamnī wa alḥiqnī bir-rafīqi ‘l-\u0027A`alā.","meaning_en":"O Allah, forgive me and have mercy upon me, and join me with the highest companions (in Paradise).","meaning_dv":"","reference":"Al-Bukhari7/10, Muslim 4/1893.","source":"Hisn al-Muslim 150 - Sunnah.com","source_url":"https://sunnah.com/hisn:150","tags":["forgiveness","illness"]},{"id":"hisn-151","n":151,"title":"When the sick have renounced all hope of life","chapter_en":"When the sick have renounced all hope of life","chapter_ar":"دعاء المريض الذي يئس من حياته","arabic":"جعل النبي صلى الله عليه وسلم عند موته يدخل يديه في الماء فيمسح بهما وجههُ ويقول : لا إله إلا الله إن للموت لسكرات","transliteration":"As he was dying, the Prophet (ﷺ) dipped his hands in water and wiped his face saying:","meaning_en":"There is none worthy of worship but Allah, surely death has agonies.","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 8/144. The Hadith also mention him using the Siivak (tooth stick).","source":"Hisn al-Muslim 151 - Sunnah.com","source_url":"https://sunnah.com/hisn:151","tags":["forgiveness","illness","death"]},{"id":"hisn-152","n":152,"title":"When the sick have renounced all hope of life","chapter_en":"When the sick have renounced all hope of life","chapter_ar":"دعاء المريض الذي يئس من حياته","arabic":"لا إلهَ إلاّ اللّهُ وَاللّهُ أَكْبَـر، لا إلهَ إلاّ اللّهُ وحْـدَهُ، لا إلهَ إلاّ اللّهُ وحْـدَهُ لا شَريكَ لهُ، لا إلهَ إلاّ اللّهُ لهُ المُلكُ ولهُ الحَمْد، لا إلهَ إلاّ اللّهُ وَلا حَـوْلَ وَلا قُـوَّةَ إِلاّ بِالله","transliteration":"Lā ilāha illallāh wallāhu Akbar, lā ilāha illallāhu waḥdah, lā ilāha illallāh waḥdahu lā sharīka lah, lā ilāha illallāh lahu ‘l-mulku wa lahu ‘l-ḥamd, lā ilāha illallāh wa lā ḥawla wa lā quwwata illā billāh.","meaning_en":"There is none worthy of worship but Allah, Allah is the Most Great. None has the right to be worshipped but Allah alone. None has the right to be worshipped but Allah alone, Who has no partner. There is none worthy of worship but Allah, His is the dominion and His is the praise. There is none worthy of worship but Allah, there is no power and no might but by Allah.","meaning_dv":"","reference":"At-Tirmidhi and Ibn Majah. See also Al-Albani, Sahih At-Tirmidhi 3/152 and Sahih Ibn Majah 2/317.","source":"Hisn al-Muslim 152 - Sunnah.com","source_url":"https://sunnah.com/hisn:152","tags":["illness","gratitude"]},{"id":"hisn-153","n":153,"title":"Instruction for the one nearing death","chapter_en":"Instruction for the one nearing death","chapter_ar":"تلقين المحتضر لا إله إلا الله","arabic":"من كان آخر كلامه \"لا إله إلا الله\" دخل الجنة","transliteration":"Lā ilāha illallāh","meaning_en":"Whoever dies with the last words (whose meaning is):","meaning_dv":"","reference":"Abu Dawud 3/190. See also Al-Albani, Sahihul-Jami\u0027 As-Saghir 5/432.","source":"Hisn al-Muslim 153 - Sunnah.com","source_url":"https://sunnah.com/hisn:153","tags":["death"]},{"id":"hisn-154","n":154,"title":"For one afflicted by a calamity","chapter_en":"For one afflicted by a calamity","chapter_ar":"دعاء من أصيب بمصيبة","arabic":"إِنّا للهِ وَإِنَا إِلَـيْهِ راجِعـون ، اللهُـمِّ اْجُـرْني في مُصـيبَتي، وَاخْلُـفْ لي خَيْـراً مِنْـها","transliteration":"Innā lillāhi wa innā ilayhi rāji`ūn, Allāhumma-jurni fī muṣībatī wa \u0027khluf lī khayran minhā.","meaning_en":"We are from Allah and unto Him we return. O Allah take me out of my plight and bring to me after it something better.","meaning_dv":"","reference":"Muslim 2/632.","source":"Hisn al-Muslim 154 - Sunnah.com","source_url":"https://sunnah.com/hisn:154","tags":["patience"]},{"id":"hisn-155","n":155,"title":"When closing the eyes of the deceased","chapter_en":"When closing the eyes of the deceased","chapter_ar":"الدعاء عند إغماض الميت","arabic":"اللهُـمِّ اغْفِـرْ لِـفلان (باسـمه) وَارْفَعْ دَرَجَتَـهُ في المَهْـدِييـن ، وَاخْـلُفْـهُ في عَقِـبِهِ في الغابِـرين، وَاغْفِـرْ لَنـا وَلَـهُ يا رَبَّ العـالَمـين، وَافْسَـحْ لَهُ في قَبْـرِهِ وَنَـوِّرْ لَهُ فيه","transliteration":"Allāhumma’ghfir li (name of the person) warfa` darajatahu fi ‘l-mahdiyyīn, wakhlufhu fī `aqibihi fi ‘l-ghābirīn, wagh’fir-lanā wa lahu yā Rabba ‘l-`ālamīn, wafsaḥ lahu fī qabrihi wa nawwir lahu fīh.","meaning_en":"O Allah, forgive [name of the person] and elevate his station among those who are guided. Send him along the path of those who came before, and forgive us and him, O Lord of the worlds. Enlarge for him his grave, and shed light upon him in it.","meaning_dv":"","reference":"Muslim 2/634.","source":"Hisn al-Muslim 155 - Sunnah.com","source_url":"https://sunnah.com/hisn:155","tags":["forgiveness","protection","death"]},{"id":"hisn-156","n":156,"title":"For the deceased at the funeral prayer","chapter_en":"For the deceased at the funeral prayer","chapter_ar":"الدعاء للميت في الصلاة عليه","arabic":"اللهُـمِّ اغْفِـرْ لَهُ وَارْحَمْـه ، وَعافِهِ وَاعْفُ عَنْـه ، وَأَكْـرِمْ نُزُلَـه ، وَوَسِّـعْ مُدْخَـلَه ، وَاغْسِلْـهُ بِالْمـاءِ وَالثَّـلْجِ وَالْبَـرَدْ ، وَنَقِّـهِ مِنَ الْخطـايا كَما نَـقّيْتَ الـثَّوْبَ الأَبْيَـضَ مِنَ الدَّنَـسْ ، وَأَبْـدِلْهُ داراً خَـيْراً مِنْ دارِه ، وَأَهْلاً خَـيْراً مِنْ أَهْلِـه ، وَزَوْجَـاً خَـيْراً مِنْ زَوْجِه ، وَأَدْخِـلْهُ الْجَـنَّة ، وَأَعِـذْهُ مِنْ عَذابِ القَـبْر [وَعَذابِ النّـار]","transliteration":"Allāhumma’ghfir lahu warḥamh, wa `āfihi, wa`fu `anh, wa akrim nuzulah, wa wassi` mudkhalah, wagh’silhu bi ‘lmā\u0027i wath-thalji walbarad, wa naqqihi mina ‘l-khaṭāyā kamā naqqaytath-thawba ‘l-abyaḍa minad-danas, wa abdilhu dāran khayran min dārih, wa ahlan khayran min ahlih, wa zawjan khayran min zawjih, wa adkhilhu ‘l-jannah, wa a`idhhu min `adhābi ‘l-qabri [wa `adhābin-nār].","meaning_en":"O Allah, forgive him and have mercy on him, and give him strength and pardon him. Be generous to him, and cause his entrance to be wide, and wash him with water and snow and hail. Cleanse him of his transgressions as white cloth is cleansed of stains. Give him an abode better than his home, and a family better than his family, and a wife better than his wife. Take him into Paradise, and protect him from the punishment of the grave [and from the punishment of Hell-fire].","meaning_dv":"","reference":"Muslim 2/663.","source":"Hisn al-Muslim 156 - Sunnah.com","source_url":"https://sunnah.com/hisn:156","tags":["forgiveness","family","prayer","daily","death"]},{"id":"hisn-157","n":157,"title":"For the deceased at the funeral prayer","chapter_en":"For the deceased at the funeral prayer","chapter_ar":"الدعاء للميت في الصلاة عليه","arabic":"اللهُـمِّ اغْفِـرْ لِحَيِّـنا وَمَيِّتِـنا، وَشـاهِدِنا وَغائِبِـنا ، وَصَغيـرِنا وَكَبيـرِنا ، وَذَكَـرِنا وَأُنْثـانا . اللهُـمِّ مَنْ أَحْيَيْـتَهُ مِنّا فَأَحْيِـهِ عَلى الإِسْلام ، وَمَنْ تَوَفَّـيْتَهُ مِنّا فَتَوَفَّـهُ عَلى الإِيـمان ، اللهُـمِّ لا تَحْـرِمْنـا أَجْـرَه ، وَلا تُضِـلَّنا بَعْـدَه","transliteration":"Allāhumma’ghfir liḥayyinā, wa mayyitinā, wa shāhidinā, wa ghā\u0027ibinā, wa ṣaghīrinā wa kabīrinā, wa dhakarinā wa unthānā. Allāhumma man aḥyaytahu minnā fa aḥyihi `ala ‘l-Islām, wa man tawaffaytahu minnā fatawaffahu `alal-īmān, Allāhumma lā taḥrimnā ajrah wa lā tuḍillanā ba`dah.","meaning_en":"O Allah forgive our living and our dead, those who are with us and those who are absent, our young and our old, our menfolk and our womenfolk. O Allah, whomever you give life from among us give him life in Islam, and whomever you take away from us take him away in Faith. O Allah, do not forbid us their reward and do not send us astray after them.","meaning_dv":"","reference":"Ibn Majah 1/480, Ahmad 2/368. See also Al-Albani, Sahih Ibn Majah 1/251.","source":"Hisn al-Muslim 157 - Sunnah.com","source_url":"https://sunnah.com/hisn:157","tags":["forgiveness","prayer","daily","death"]},{"id":"hisn-158","n":158,"title":"For the deceased at the funeral prayer","chapter_en":"For the deceased at the funeral prayer","chapter_ar":"الدعاء للميت في الصلاة عليه","arabic":"اللهُـمِّ إِنَّ فُلانَ بْنَ فُلانٍ في ذِمَّـتِك ، وَحَبْـلِ جِـوارِك ، فَقِـهِ مِنْ فِتْـنَةِ الْقَـبْرِ وَعَذابِ النّـار ، وَأَنْتَ أَهْلُ الْوَفـاءِ وَالْـحَقِّ ، فَاغْفِـرْ لَهُ وَارْحَمْـهُ ، إِنَّكَ أَنْتَ الغَـفورُ الـرَّحيم","transliteration":"Allāhumma inna [name the person] fī dhimmatik, wa ḥabli jiwārik, faqihi min fitnati ‘l-qabri wa `adhābin-nār, wa anta ahlu ‘l-wafā\u0027i wa ‘l-ḥaqq. Faghfir lahu warḥamh innaka anta ‘l-Ghafūrur-Raḥīm.","meaning_en":"O Allah, surely [name the person] is under Your protection, and in the rope of Your security, so save him from the trial of the grave and from the punishment of the Fire. You fulfill promises and grant rights, so forgive him and have mercy on him. Surely You are Most Forgiving, Most Merciful.","meaning_dv":"","reference":"Ibn Majah, Abu Dawud 3/211. See also Al Albani, Sahih Ibn Majah 1/251.","source":"Hisn al-Muslim 158 - Sunnah.com","source_url":"https://sunnah.com/hisn:158","tags":["forgiveness","patience","protection","prayer","death"]},{"id":"hisn-159","n":159,"title":"For the deceased at the funeral prayer","chapter_en":"For the deceased at the funeral prayer","chapter_ar":"الدعاء للميت في الصلاة عليه","arabic":"اللهُـمِّ عَبْـدُكَ وَابْنُ أَمَـتِك، احْتـاجَ إِلى رَحْمَـتِك، وَأَنْتَ غَنِـيٌّ عَنْ عَذابِـه، إِنْ كانَ مُحْـسِناً فَزِدْ في حَسَـناتِه، وَإِنْ كانَ مُسـيئاً فَتَـجاوَزْ عَنْـه","transliteration":"Allāhumma `abduka wabnu \u0027amatik iḥtāja ilā raḥmatik, wa anta ghaniyyun `an `adhābih, in kāna muḥsinan fazid fī ḥasanātih, wa in kāna musī\u0027an fatajāwaz `anh.","meaning_en":"O Allah, Your male slave and the child of Your female slave is in need of Your mercy, and You are not in need of his torment. If he was pious then increase his rewards and if he was a transgressor then pardon him.","meaning_dv":"","reference":"Al-Hakim 1/359 who graded it authentic and Ath-Thahabi agreed with him. See also Al-Albani, Ahkamul-Jana\u0027iz, p. 125.","source":"Hisn al-Muslim 159 - Sunnah.com","source_url":"https://sunnah.com/hisn:159","tags":["family","prayer","death"]},{"id":"hisn-160","n":160,"title":"When the deceased is a child, during the funeral prayer","chapter_en":"When the deceased is a child, during the funeral prayer","chapter_ar":"الدعاء للفرط في الصلاة عليه","arabic":"\"اللهم أعذه من عذاب القبر \" وإن قال: \"اللهم اجعله فرطاً وذخراً لوالديه ، وشفيعاً مجاباً . اللهم ثقل به موازينها وأعظم به أجورهما ، وألحقهُ بصالح المؤمنين ، واجعلهُ في كفالة إبراهيم ، وقه برحمتك عذاب الجحيم ، وأبدله داراً خيراً من داره ، وأهلاً خيراً من أهله ، اللهم اغفر لاسلافنا ، وأفراطنا ، ومن سبقنا بالإيمان \" فحسن","transliteration":"Allāhumma a`idh’hu min `adhābi ‘l-qabr [or say:","meaning_en":"O Allah, protect him from the torment of the grave. [It is also good to say:] O Allah, make him a precursor, a forerunner and a treasure for his parents and an answered intercessor. O Allah, make him weigh heavily in their scales (of good) and magnify their reward. Make him join the righteous of the believers. Place him in the care of Ibrahim. Save him by Your mercy from the torment of Hell. Give him a home better than his home, and a family better than his family. O Allah, forgive those who have gone (i.e. passed away) before us, our children lost (by death), and those who have preceded us in Faith.","meaning_dv":"","reference":"Ibn Qudamah, Al-Mughni 3/416 and Ad-Duroosul-Muhimmah li-Aammatil-\u0027Ummah, pg. 15, by Shaikh \u0027Abdul-\u0027Aziz bin Baz.","source":"Hisn al-Muslim 160 - Sunnah.com","source_url":"https://sunnah.com/hisn:160","tags":["forgiveness","family","prayer","daily","death"]},{"id":"hisn-161","n":161,"title":"When the deceased is a child, during the funeral prayer","chapter_en":"When the deceased is a child, during the funeral prayer","chapter_ar":"الدعاء للفرط في الصلاة عليه","arabic":"اللهُـمِّ اجْعَلْـهُ لَنا فَرَطـاً، وَسَلَـفاً وَأَجْـراً","transliteration":"Allāhumma’j`alhu lanā faraṭan, wa salafan, wa ajra.","meaning_en":"O Allah, make him for us a precursor, a forerunner and a cause of reward.","meaning_dv":"","reference":"Al-Hasan (Al-Basri) used to recite Surat Al-Fatihah for a child\u0027s funeral and then say this. Al-Bukhari, Kitabul-Jana\u0027iz, p. 65.","source":"Hisn al-Muslim 161 - Sunnah.com","source_url":"https://sunnah.com/hisn:161","tags":["family","prayer","death"]},{"id":"hisn-162","n":162,"title":"Condolence","chapter_en":"Condolence","chapter_ar":"دعاء التعزية","arabic":"\"إن لله ما أخذ وله ما أعطى . وكل شيء عنده بأجل مُسمى ... فلتصبر ولتحتسب \" وإن قال : \"أعظم الله أجرك ، وأحسن عزاءك وغفر لميتك\" فحسن","transliteration":"Inna lillāhi mā akhadh, wa lahu mā a`tā, wa kullu shay\u0027in `indahu bi ajalin musammā . . . faltaṣbir wa ‘l-taḥtasib . [Also good to say:","meaning_en":"Surely, Allah takes what is His, and what He gives is His, and to all things He has appointed a time... so have patience and be rewarded.1 May Allah magnify your reward, and make perfect your bereavement, and forgive your departed.2","meaning_dv":"","reference":"1 Al-Bukhari 2/80, Muslim 2/636. 2An-Nawawi, Kitabul-\u0027Athkar, p. 126.","source":"Hisn al-Muslim 162 - Sunnah.com","source_url":"https://sunnah.com/hisn:162","tags":["forgiveness","patience","death"]},{"id":"hisn-163","n":163,"title":"Placing the deceased in the grave","chapter_en":"Placing the deceased in the grave","chapter_ar":"دعاء عند إدخال الميت القبر","arabic":"بِسْـمِ اللهِ وَعَلـى سُـنَّةِ رَسـولِ الله","transliteration":"Bismillāh wa `alā sunnati Rasūlillāh.","meaning_en":"With the Name of Allah, and according to the Sunnah of the Messenger of Allah.","meaning_dv":"","reference":"Abu Dawud 3/314 with an authentic chain. Ahmad also recorded it with the wording: With the Name of Allah, and according to the religion of the Messenger of Allah. Its chain is also authentic.","source":"Hisn al-Muslim 163 - Sunnah.com","source_url":"https://sunnah.com/hisn:163","tags":["death"]},{"id":"hisn-164","n":164,"title":"After burying the deceased","chapter_en":"After burying the deceased","chapter_ar":"دعاء بعد دفن الميت","arabic":"اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ثَبِّتْهُ","transliteration":"Allāhumma’ghfir lah Allāhumma thabbit’h.","meaning_en":"O Allah, forgive him. O Allah, strengthen him.","meaning_dv":"","reference":"The Prophet (ﷺ) used to stop after burying the dead and say to the people: \"Ask Allah to forgive your brother and pray for him to be strengthened, for indeed he is now being questioned.\" Abu Dawud 3/315, and Al-Hakim 1/370 who graded it authentic and Ath-Thahabi agreed.","source":"Hisn al-Muslim 164 - Sunnah.com","source_url":"https://sunnah.com/hisn:164","tags":["forgiveness","death"]},{"id":"hisn-165","n":165,"title":"Visiting the graves","chapter_en":"Visiting the graves","chapter_ar":"دعاء زيارة القبور","arabic":"السَّلامُ عَلَـيْكُمْ أَهْلَ الدِّيارِ مِنَ المؤْمِنيـنَ وَالْمُسْلِمين، وَإِنّا إِنْ شاءَ اللهُ بِكُـمْ لاحِقـون، نَسْـاَلُ اللهَ لنـا وَلَكُـمْ العـافِيَة","transliteration":"Assalāmu `alaykum ahlad-diyāri minal-mu\u0027minīna wa ‘l-muslimīn, wa innā in shā\u0027 Allāhu bikum lāḥiqūn nas\u0027alullāha lanā wa lakumul-`āfiyah.","meaning_en":"Peace be upon you, people of this abode, from among the believers and those who are Muslims, and we, by the Will of Allah, shall be joining you. [May Allah have mercy on the first of us and the last of us] I ask Allah to grant us and you well-being.","meaning_dv":"","reference":"Muslim 2/671, Ibn Majah 1/494, the portion brackets is from Muslim 2/671.","source":"Hisn al-Muslim 165 - Sunnah.com","source_url":"https://sunnah.com/hisn:165","tags":["death"]},{"id":"hisn-166","n":166,"title":"During a wind storm","chapter_en":"During a wind storm","chapter_ar":"دعاء الريح","arabic":"اللّهُـمَّ إِنَّـي أَسْـأَلُـكَ خَيْـرَها، وَأَعـوذُ بِكَ مِنْ شَـرِّها","transliteration":"Allāhumma innī as\u0027aluka khayrahā, wa a`ūdhu bika min sharrihā.","meaning_en":"O Allah, I ask You for the good of it, and seek refuge in You against its evil.","meaning_dv":"","reference":"Abu Dawud 4/326, Ibn Majah 2/1228. See also Al-Albani, Sahih Ibn Majah 2/305.","source":"Hisn al-Muslim 166 - Sunnah.com","source_url":"https://sunnah.com/hisn:166","tags":["protection","weather"]},{"id":"hisn-167","n":167,"title":"During a wind storm","chapter_en":"During a wind storm","chapter_ar":"دعاء الريح","arabic":"اللّهُـمَّ إِنَّـي أَسْـأَلُـكَ خَيْـرَها، وَخَيْـرَ ما فيهـا، وَخَيْـرَ ما اُرْسِلَـتْ بِه، وَأَعـوذُ بِكَ مِنْ شَـرِّها، وَشَـرِّ ما فيهـا، وَشَـرِّ ما اُرْسِلَـتْ بِه","transliteration":"Allāhumma innī as\u0027aluka khayrahā, wa khayra mā fīhā, wa khayra mā ursilat bih, wa a`ūdhu bika min sharrihā, wa sharri mā fīhā, wa sharri mā ursilat bih.","meaning_en":"O Allah, I ask You for the good of it, for the good of what it contains, and for the good of what is sent with it. I seek refuge in You from the evil of it, from the evil of what it contains, and from the evil that is sent with it.","meaning_dv":"","reference":"Muslim 2/616, Al-Bukhari 4/76.","source":"Hisn al-Muslim 167 - Sunnah.com","source_url":"https://sunnah.com/hisn:167","tags":["protection","weather"]},{"id":"hisn-168","n":168,"title":"Upon hearing thunder","chapter_en":"Upon hearing thunder","chapter_ar":"دعاء الرعد","arabic":"سُبْـحانَ الّذي يُسَبِّـحُ الـرَّعْدُ بِحَمْـدِهِ، وَالملائِكـةُ مِنْ خيـفَته","transliteration":"Subḥāna ‘l-ladhī yusabbiḥur-ra`du bi ḥamdihi wa ‘l-malā\u0027ikatu min khīfatih.","meaning_en":"Glory is to Him Whom thunder and angels glorify due to fear of Him.","meaning_dv":"","reference":"Whenever Abdullah bin Zubair (RA) would hear thunder, he would abandon all conversation and say this supplication. See Al-Muwatta\u0027 2/992. It was graded authentic by Al-Albani as a statement of Abdullah bin Zubayr only.","source":"Hisn al-Muslim 168 - Sunnah.com","source_url":"https://sunnah.com/hisn:168","tags":["anxiety","weather"]},{"id":"hisn-169","n":169,"title":"For rain","chapter_en":"For rain","chapter_ar":"من أدعية الاستسقاء","arabic":"اللّهُمَّ اسْقِـنا غَيْـثاً مُغيـثاً مَريئاً مُريـعاً، نافِعـاً غَيْـرَ ضار، عاجِـلاً غَـيْرَ آجِل","transliteration":"Allāhumma ‘asqinā ghaythan mughīthan marī\u0027an murī`a, nāfi`an ghayra ḍārr, `ājilan ghayra ājil.","meaning_en":"O Allah, shower upon us abundant rain, beneficial not harmful, swiftly and not delayed.","meaning_dv":"","reference":"Abu Dawud 1/303. See also Al-Albani SahihAbu Dawud 1/216.","source":"Hisn al-Muslim 169 - Sunnah.com","source_url":"https://sunnah.com/hisn:169","tags":["weather"]},{"id":"hisn-170","n":170,"title":"For rain","chapter_en":"For rain","chapter_ar":"من أدعية الاستسقاء","arabic":"اللّهُمَّ أغِثْنـا، اللّهُمَّ أغِثْنـا، اللّهُمَّ أغِثْنـا","transliteration":"Allāhumma aghithnā, Allāhumma aghithnā, Allāhumma aghithnā.","meaning_en":"O Allah, send us rain. O Allah, send us rain. O Allah, send us rain.","meaning_dv":"","reference":"Al-Bukhari 1/224, Muslim 2/613.","source":"Hisn al-Muslim 170 - Sunnah.com","source_url":"https://sunnah.com/hisn:170","tags":["weather"]},{"id":"hisn-171","n":171,"title":"For rain","chapter_en":"For rain","chapter_ar":"من أدعية الاستسقاء","arabic":"اللّهُمَّ اسْقِ عِبادَكَ وَبَهـائِمَك، وَانْشُـرْ رَحْمَـتَكَ وَأَحْيِي بَلَـدَكَ المَيِّـت","transliteration":"Allāhumma’sqi `ibādaka wa bahā\u0027imak, wanshur raḥmatak, wa aḥyi baladaka ‘l-mayyit","meaning_en":"O Allah, give water to Your slaves, and Your livestock, and spread Your mercy, and revive Your dead land.","meaning_dv":"","reference":"Abu Dawud 1/305. Al-Albani graded it good in Sahih Abu Dawud 1/218.","source":"Hisn al-Muslim 171 - Sunnah.com","source_url":"https://sunnah.com/hisn:171","tags":["weather"]},{"id":"hisn-172","n":172,"title":"When it rains","chapter_en":"When it rains","chapter_ar":"الدعاء إذا رأى المطر","arabic":"اللّهُمَّ صَيِّـباً نافِـعاً","transliteration":"Allāhumma ṣayyiban nāfi`a.","meaning_en":"O Allah, (bring) beneficial rain clouds.","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 2/518.","source":"Hisn al-Muslim 172 - Sunnah.com","source_url":"https://sunnah.com/hisn:172","tags":["weather"]},{"id":"hisn-173","n":173,"title":"After rainfall","chapter_en":"After rainfall","chapter_ar":"الذكر بعد نزول المطر","arabic":"مُطِـرْنا بِفَضْـلِ اللهِ وَرَحْمَـتِه","transliteration":"Muṭirnā bifaḍlillāhi wa raḥmatih.","meaning_en":"We have been given rain by the grace and mercy of Allah.","meaning_dv":"","reference":"Al-Bukhari 1/205, Muslim 1/83.","source":"Hisn al-Muslim 173 - Sunnah.com","source_url":"https://sunnah.com/hisn:173","tags":["weather"]},{"id":"hisn-174","n":174,"title":"Asking for clear skies","chapter_en":"Asking for clear skies","chapter_ar":"من أدعية الاستصحاء","arabic":"اللّهُمَّ حَوالَيْنا وَلا عَلَيْـنا، اللّهُمَّ عَلى الآكـامِ وَالظِّـراب، وَبُطـونِ الأوْدِية، وَمَنـابِتِ الشَّجـر","transliteration":"Allāhumma ḥawālaynā wa lā `alaynā. Allāhumma `ala ‘l-ākāmi waẓ-ẓirāb, wa buṭūni ‘l-awdiyati, wa manābitish-shajar.","meaning_en":"O Allah, let the rain fall around us and not upon us, O Allah, (let it fall) on the pastures, hills, valleys, and the roots of trees.","meaning_dv":"","reference":"Al-Bukhari 1/224, Muslim 1/614","source":"Hisn al-Muslim 174 - Sunnah.com","source_url":"https://sunnah.com/hisn:174","tags":["weather"]},{"id":"hisn-175","n":175,"title":"Upon sighting the crescent moon","chapter_en":"Upon sighting the crescent moon","chapter_ar":"دعاء رؤية الهلال","arabic":"اللهُ أَكْـبَر، اللّهُمَّ أَهِلَّـهُ عَلَيْـنا بِالأمْـنِ وَالإيمـان، والسَّلامَـةِ والإسْلام، وَالتَّـوْفيـقِ لِما تُحِـبُّ رَبَّنـا وَتَـرْضـى، رَبُّنـا وَرَبُّكَ الله","transliteration":"Allāhu Akbar, Allāhumma ahillahu `alayna bi ‘l-amni wa ‘l-īmān, was-salāmati wa ‘l-\u0027Islām, wat-tawfīqi limā tuḥibbu Rabbanā wa tarḍā, Rabbunā wa Rabbukallāh.","meaning_en":"Allah is the Most Great. O Allah, bring us the new moon with security and Faith, with peace and in Islam, and in harmony with what our Lord loves and what pleases Him. Our Lord and your Lord is Allah.","meaning_dv":"","reference":"At-Tirmidhi 5/504, Ad-Darimi 1/336. See also Al-Albani, Sahih At-Tirmidhi 3/157.","source":"Hisn al-Muslim 175 - Sunnah.com","source_url":"https://sunnah.com/hisn:175","tags":["weather"]},{"id":"hisn-176","n":176,"title":"Upon breaking fast","chapter_en":"Upon breaking fast","chapter_ar":"الدعاء عند إفطار الصائم","arabic":"ذَهَـبَ الظَّمَـأُ، وَابْتَلَّـتِ العُـروق، وَثَبَـتَ الأجْـرُ إِنْ شـاءَ الله","transliteration":"Dhahabaẓ-ẓama\u0027, wabtallati ‘l-`urūq, wa thabata ‘l-\u0027ajru in shā Allāh.","meaning_en":"The thirst is gone, the veins are moistened, and the reward is confirmed, if Allah wills.","meaning_dv":"","reference":"Abu Dawud 2/306 and others. See also Al- Albani, Sahihul-Jami\u0027 As-Saghir 4/209.","source":"Hisn al-Muslim 176 - Sunnah.com","source_url":"https://sunnah.com/hisn:176","tags":[]},{"id":"hisn-177","n":177,"title":"Upon breaking fast","chapter_en":"Upon breaking fast","chapter_ar":"الدعاء عند إفطار الصائم","arabic":"اللّهُـمَّ إِنَّـي أَسْـأَلُـكَ بِرَحْمَـتِكَ الّتي وَسِـعَت كُلَّ شيء، أَنْ تَغْـفِرَ لي","transliteration":"Allāhumma innī as\u0027aluka bi raḥmatika ‘l-latī wasi`at kulla shay\u0027 an taghfira lī.","meaning_en":"O Allah, I ask You by Your mercy, which encompasses all things, that You forgive me.","meaning_dv":"","reference":"Ibn Majah 1/557 from a supplication of Abdullah bin \u0027Amr. Al-Hafidh graded it as good in his checking of An-Nawawi\u0027s Kitabul-\u0027Athkdr. See Sharhul- Athkar 4/342.","source":"Hisn al-Muslim 177 - Sunnah.com","source_url":"https://sunnah.com/hisn:177","tags":["forgiveness"]},{"id":"hisn-178","n":178,"title":"Before eating","chapter_en":"Before eating","chapter_ar":"الدعاء قبل الطعام","arabic":"إِذَا أَكَلَ أَحَدُكُمْ طَعَاماً فَلْيَقُلْ بِسْمِ اللَّهِ، فَإِنْ نَسِيَ فِي أَوَّلِهِ فَلْيَقُلْ بسمِ اللَّهِ فِي أَوَّلِهِ وَآخِرِهِ","transliteration":"When anyone of you begins eating, say:","meaning_en":"When anyone of you begins eating, say: With the Name of Allah. And if you forget then, when you remember, say: With the Name of Allah, in the beginning, and in the end.","meaning_dv":"","reference":"Abu Dawud 3/347, At-Tirmidhi 4/288. See Al- Albani\u0027s Sahih At-Tirmidhi 2/167.","source":"Hisn al-Muslim 178 - Sunnah.com","source_url":"https://sunnah.com/hisn:178","tags":["daily"]},{"id":"hisn-179","n":179,"title":"Before eating","chapter_en":"Before eating","chapter_ar":"الدعاء قبل الطعام","arabic":"مَنْ أَطْعَمَهُ اللَّهُ الطَّعَامَ فَلْيَقُلْ: \"اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَأَطْعِمْنَا خَيْراً مِنْهُ\"، وَمَنْ سَقَاهُ اللَّهُ لَبَناً فَلْيَقُلْ \"اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَزِدْنَا مِنْهُ\"","transliteration":"Whomever Allah has given food, should say:","meaning_en":"Whomever Allah has given food, should say: O Allah, bless us in it and provide us with better than it. Whomever Allah has given milk to drink, should say : O Allah, bless us in it and give us more of it.","meaning_dv":"","reference":"At-Tirmidhi 5/506. See also Al-Albani, Sahih At-Tirmidhi 3/158.","source":"Hisn al-Muslim 179 - Sunnah.com","source_url":"https://sunnah.com/hisn:179","tags":["financial","daily"]},{"id":"hisn-180","n":180,"title":"Upon completing the meal","chapter_en":"Upon completing the meal","chapter_ar":"الدعاء عند الفراغ من الطعام","arabic":"الْحَمْـدُ للهِ الَّذي أَطْعَمَنـي هـذا وَرَزَقَنـيهِ مِنْ غَـيْرِ حَوْلٍ مِنِّي وَلا قُوَّة","transliteration":"Alhamdu lillāhi ‘l-ladhī aṭ`amanī hādhā, wa razaqanīhi min ghayri ḥawlin minnī wa lā quwwah.","meaning_en":"Praise is to Allah Who has given me this food, and sustained me with it though I was unable to do it and powerless.","meaning_dv":"","reference":"At-Tirmidhi, Abu Dawud, and Ibn Majah. See also Al-Albani, Sahih At-Tirmidhi 3/159.","source":"Hisn al-Muslim 180 - Sunnah.com","source_url":"https://sunnah.com/hisn:180","tags":["financial","daily","gratitude"]},{"id":"hisn-181","n":181,"title":"Upon completing the meal","chapter_en":"Upon completing the meal","chapter_ar":"الدعاء عند الفراغ من الطعام","arabic":"الْحَمْـدُ للهِ حَمْـداً كَثـيراً طَيِّـباً مُبـارَكاً فيه، غَيْرَ مَكْفِيٍّ وَلا مُوَدَّعٍ وَلا مُسْتَغْـنىً عَنْـهُ رَبَّـنا","transliteration":"Alhamdu lillāhi ḥamdan kathīran tayyiban mubārakan fīh, ghayra makfiyyin wa lā muwadda`in, wa lā mustaghnan `anhu Rabbanā.","meaning_en":"All praise is to Allah, praise in abundance, good and blessed. It cannot [be compensated for, nor can it] be left, nor can it be done without, our Lord.","meaning_dv":"","reference":"Al-Bukhari 6/214, At-Tirmidhi 5/507.","source":"Hisn al-Muslim 181 - Sunnah.com","source_url":"https://sunnah.com/hisn:181","tags":["daily","gratitude"]},{"id":"hisn-182","n":182,"title":"Of the guest for the host","chapter_en":"Of the guest for the host","chapter_ar":"دعاء الضيف لصاحب الطعام","arabic":"اللّهُـمَّ بارِكْ لَهُمْ فيما رَزَقْـتَهُم، وَاغْفِـرْ لَهُـمْ وَارْحَمْهُمْ","transliteration":"Allāhumma bārik lahum fī mā razaqtahum, wagh’fir lahum warḥamhum.","meaning_en":"O Allah, bless them in what You have provided for them, and forgive them and have mercy on them.","meaning_dv":"","reference":"Muslim 3/1615.","source":"Hisn al-Muslim 182 - Sunnah.com","source_url":"https://sunnah.com/hisn:182","tags":["forgiveness","family"]},{"id":"hisn-183","n":183,"title":"To one who intends to give food or drink","chapter_en":"To one who intends to give food or drink","chapter_ar":"الدعاء إذا أراد الطعام أو الشراب","arabic":"اللّهُـمَّ أَطْعِمْ مَن أَطْعَمَني، وَاسْقِ مَن سقاني","transliteration":"Allāhumma aṭ`im man aṭ`amanī wasqi man saqānī.","meaning_en":"O Allah, feed the one who has fed me, and give drink to the one who has given me drink.","meaning_dv":"","reference":"Muslim 3/126.","source":"Hisn al-Muslim 183 - Sunnah.com","source_url":"https://sunnah.com/hisn:183","tags":["financial"]},{"id":"hisn-184","n":184,"title":"When breaking fast in someone’s home","chapter_en":"When breaking fast in someone’s home","chapter_ar":"الدعاء إذا أفطر عند أهل بيت","arabic":"أَفْطَـرَ عِنْدَكُم الصّـائِمونَ وَأَكَلَ طَعامَـكُمُ الأبْـرار، وَصَلَّـتْ عَلَـيْكُمُ الملائِكَـة","transliteration":"Afṭara `indakumuṣ-ṣā\u0027imūn, wa akala ṭa`āmakumu ‘l-\u0027abrār, wa ṣallat `alaykumu ‘l-malā\u0027ikah.","meaning_en":"With you, those who are fasting have broken their fast, you have fed those who are righteous, and the angels recite their prayers upon you.","meaning_dv":"","reference":"Abu Dawud 3/367, Ibn Majah 1/556, An-Nasa\u0027i, \u0027Amalul-Yawm wal-Laylah 296-8. Al-Albani graded it authentic in Sahih Abu Dawud 2/730.","source":"Hisn al-Muslim 184 - Sunnah.com","source_url":"https://sunnah.com/hisn:184","tags":["prayer","daily"]},{"id":"hisn-185","n":185,"title":"By one fasting when presented with food and does not break his fast","chapter_en":"By one fasting when presented with food and does not break his fast","chapter_ar":"دعاء الصائم إذا حضر الطعام ولم يفطر","arabic":"(إِذَا دُعِيَ أَحَدُكُمْ فَلْيُجِبْ، فَإِنْ كَانَ صَائِماً فَلْيُصَلِّ، وَإِنْ كَانَ مُفْطِراً فَلْيَطْعَمْ) ، وَمَعْنَى فَلْيُصَلِّ أَيْ فَلْيَدْعُ.","transliteration":"--","meaning_en":"When you are invited (to eat) then reply to the invitation. If you are fasting then invoke Allah\u0027s blessings (on your host), and if you are not fasting then eat.","meaning_dv":"","reference":"Muslim 2/1054.","source":"Hisn al-Muslim 185 - Sunnah.com","source_url":"https://sunnah.com/hisn:185","tags":["forgiveness","financial","family","gratitude"]},{"id":"hisn-186","n":186,"title":"When insulted while fasting","chapter_en":"When insulted while fasting","chapter_ar":"ما يقول الصائم إذا سابه أحد","arabic":"إِنِّي صَائِمٌ، إِنِّي صَائِمٌ","transliteration":"Innī ṣā\u0027im, innī ṣā\u0027im.","meaning_en":"I am fasting. I am fasting.","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-BAri 4/103, Muslim 2/806.","source":"Hisn al-Muslim 186 - Sunnah.com","source_url":"https://sunnah.com/hisn:186","tags":[]},{"id":"hisn-187","n":187,"title":"Upon seeing the early or premature fruit","chapter_en":"Upon seeing the early or premature fruit","chapter_ar":"الدعاء عند رؤية باكورة الثمر","arabic":"اللّهُـمَّ بارِكْ لَنا في ثَمَـرِنا، وَبارِكْ لَنا في مَدينَتِنـا، وَبارِكْ لَنا في صاعِنـا، وَبارِكْ لَنا في مُدِّنا","transliteration":"Allahumma bārik lanā fī thamarinā, wa bārik lanā fī madīnatinā wa bārik lanā fī ṣā`inā, wa bārik lanā fī muddinā.","meaning_en":"O Allah, bless us in our dates and bless us in our town, bless us in our Sa\u0027 and in our Mudd.","meaning_dv":"","reference":"Muslim 2/1000 (Sa\u0027 and Mudd are both dry measures used for agricultural produce by the Arabs in the Prophet\u0027s time. Of the two, the So.\u0027 was the larger measure.) (Translator)","source":"Hisn al-Muslim 187 - Sunnah.com","source_url":"https://sunnah.com/hisn:187","tags":["travel"]},{"id":"hisn-188","n":188,"title":"Upon sneezing","chapter_en":"Upon sneezing","chapter_ar":"دعاء العطاس","arabic":"إِذَا عَطَسَ أَحَدُكُم فَلْيَقُلِ (الْحَمْدُ لِلَّهِ)، وَلْيَقُلْ لَهُ أَخُوهُ أَوْ صَاحِبُهُ: (يَرْحَمُكَ اللَّهُ)، فَإِذَا قَالَ لَهُ: (يَرحَمُكَ اللَّهُ)، فَلْيَقُلْ: (يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ)","transliteration":"When you sneeze , then say :","meaning_en":"When you sneeze, then say: All praises and thanks are to Allah. Your companion should say: May Allah have mercy upon you. When someone says Yarḥamukallāh to you then you should say: May Allah guide you and set your affairs in order.","meaning_dv":"","reference":"Al-Bukhari 7/125.","source":"Hisn al-Muslim 188 - Sunnah.com","source_url":"https://sunnah.com/hisn:188","tags":["daily","gratitude"]},{"id":"hisn-189","n":189,"title":"When a disbeliever praises Allah after sneezing","chapter_en":"When a disbeliever praises Allah after sneezing","chapter_ar":"ما يقالُ للكافر إذا عطس فحمد الله","arabic":"يَهْـديكُـمُ اللهُ وَيُصْـلِحُ بالَـكُم","transliteration":"Yahdīkumullāhu wa yuṣliḥu bālakum.","meaning_en":"May Allah guide you and set your affairs in order","meaning_dv":"","reference":"At-Tirmidhi 5/82, Ahmad 4/400, Abu Dawud 4/ 308. See also Al-Albani, Sahih At-Tirmidhi 2/354.","source":"Hisn al-Muslim 189 - Sunnah.com","source_url":"https://sunnah.com/hisn:189","tags":["daily","gratitude"]},{"id":"hisn-190","n":190,"title":"To the newlywed","chapter_en":"To the newlywed","chapter_ar":"الدعاء للمتزوج","arabic":"بارَكَ اللّهُ لَك، وَبارَكَ عَلَـيْك، وَجَمَعَ بَيْـنَكُما في خَـيْر","transliteration":"Bārakallāhu lak, wa bāraka `alayk, wa jama`a baynakumā fī khayr.","meaning_en":"May Allah bless you, and shower His blessings upon you, and join you together in goodness.","meaning_dv":"","reference":"Abu Dawud, Ibn Majah and At-Tirmidhi. See also Al-Albani, Sahih At-Tirmidhi 1/316.","source":"Hisn al-Muslim 190 - Sunnah.com","source_url":"https://sunnah.com/hisn:190","tags":["forgiveness","gratitude"]},{"id":"hisn-191","n":191,"title":"On the wedding night or when buying an animal","chapter_en":"On the wedding night or when buying an animal","chapter_ar":"دعاء المتزوج لنفسه ودعاء شراء الدابة","arabic":"إِذَا تَزَوَّجَ أَحَدُكُمُ امْرَأَةً، أَوْ إِذَا اشْتَرَى خَادِماً فَلْيَقُلْ: (اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا جَبَلْتَهَا عَلَيْهِ)، وَإِذَا اشْتَرَى بَعِيراً فَلْيَأْخُذْ بِذِرْوَةِ سَنَامِهِ وَلْيَقُلْ مِثْلَ ذَلِكَ.","transliteration":"When any of you marries a woman or purchases a maid-servant then let him say:","meaning_en":"When any of you marries a woman or purchases a maid-servant then let him say : O Allah, I ask You for the goodness of her, and the goodness upon which You have created her, and I seek refuge in You from the evil of her, and from the evil upon which You have created her. If you purchase a camel then take hold of the top of its hump and say the same.","meaning_dv":"","reference":"Abu Dawud 2/248 and Ibn Majah 1/617. See also Al-Albani, Sahih Ibn Majah 1/324.","source":"Hisn al-Muslim 191 - Sunnah.com","source_url":"https://sunnah.com/hisn:191","tags":["protection"]},{"id":"hisn-192","n":192,"title":"Before sexual intercourse with the wife","chapter_en":"Before sexual intercourse with the wife","chapter_ar":"الدعاء قبل إتيان الزوجة","arabic":"بِسْمِ الله اللّهُـمَّ جَنِّبْنا الشَّيْـطانَ، وَجَنِّبِ الشَّـيْطانَ ما رَزَقْـتَنا","transliteration":"Bismillāh. Allāhumma jannibnash-Shayṭān, wa jannibish-Shayṭāna mā razaqtanā.","meaning_en":"With the Name of Allah. O Allah, keep the Devil away from us, and keep the Devil away from that which You provide for us.","meaning_dv":"","reference":"Al-Bukhari 6/141, Muslim 2/1028.","source":"Hisn al-Muslim 192 - Sunnah.com","source_url":"https://sunnah.com/hisn:192","tags":["family","protection"]},{"id":"hisn-193","n":193,"title":"When angry","chapter_en":"When angry","chapter_ar":"دعاء الغضب","arabic":"أَعـوذُ بِاللهِ مِنَ الشَّيْـطانِ الرَّجيـم","transliteration":"A`ūdhu billāhi minash-Shayṭānir-rajīm.","meaning_en":"I seek refuge in Allah from Satan the outcast.","meaning_dv":"","reference":"Al-Bukhari 7/99, Muslim 4/2015.","source":"Hisn al-Muslim 193 - Sunnah.com","source_url":"https://sunnah.com/hisn:193","tags":["protection","daily"]},{"id":"hisn-194","n":194,"title":"Upon seeing someone in trial or tribulation","chapter_en":"Upon seeing someone in trial or tribulation","chapter_ar":"دعاء من رأى مبتلى","arabic":"الْحَمْـدُ للهِ الّذي عافاني مِمّا ابْتَـلاكَ بِهِ، وَفَضَّلَـني عَلى كَثيـرٍ مِمَّنْ خَلَـقَ تَفْضـيلا","transliteration":"Alhamdu lillāhi ‘l-ladhī `āfānī mimmab-talāka bihi wa faḍḍalanī `alā kathīrin mimman khalaqa tafḍīlā.","meaning_en":"Praise is to Allah Who has spared me what He has afflicted you with, and preferred me greatly above much of what He has created.","meaning_dv":"","reference":"At-Tirmidhi 5/493,4. See also Al-Albani, Sahih At-Tirmidhi 3/153.","source":"Hisn al-Muslim 194 - Sunnah.com","source_url":"https://sunnah.com/hisn:194","tags":["patience","gratitude"]},{"id":"hisn-195","n":195,"title":"At a sitting or gathering","chapter_en":"At a sitting or gathering","chapter_ar":"ما يقال في المجلس","arabic":"عن ابن عمر قال : كان يعد لرسول الله صلى الله عليه وسلم في المجلس الواحد مائة مرة من قبل أن يقوم \"رب اغفر لي وتب علي إنك أنت التواب الغفور\"","transliteration":"Ibn Umar (ra) said:","meaning_en":"Ibn Umar (ra) said: Allah\u0027s Messenger (ﷺ) used to repeat in a single sitting: My Lord, forgive me, and accept my repentance, You are the Ever-Relenting, the All-Forgiving.","meaning_dv":"","reference":"Sahih Ibn Majah 2/321. See also Al-Albani, Sahih At-Tirmidhi 3/153.","source":"Hisn al-Muslim 195 - Sunnah.com","source_url":"https://sunnah.com/hisn:195","tags":["forgiveness"]},{"id":"hisn-196","n":196,"title":"For the expiation of sins, said at the conclusion of a sitting or gathering","chapter_en":"For the expiation of sins, said at the conclusion of a sitting or gathering","chapter_ar":"كفارة المجلس","arabic":"سُبْحـانَكَ اللّهُـمَّ وَبِحَمدِك، أَشْهَـدُ أَنْ لا إِلهَ إِلاّ أَنْتَ أَسْتَغْفِرُكَ وَأَتوبُ إِلَـيْك","transliteration":"Subhānaka Allāhumma wa biḥamdik, ash-hadu an lā ilāha illā ant, astaghfiruka wa atību ilayk.","meaning_en":"Glory is to You, O Allah, and praise is to You. I bear witness that there is none worthy of worship but You. I seek Your forgiveness and repent to You.","meaning_dv":"","reference":"Abu Dawud, Ibn Majah, At-Tirmidhi and An-Nasa\u0027i. See also Al-Albani, Sahih At-Tirmidhi 3/ 153. Aishah (RA) said: \"Allah\u0027s Messenger (ﷺ) did not sit in a gathering, and did not recite the Qur\u0027an, and did not perform any prayer without concluding by saying ... (then she quoted the above).\" This was reported by An-Nasa\u0027i in \u0027Amalul-Yawm wal-Laylah (no.308), and Dr. Farooq Hamadah graded it authentic in his checking of the same book, p. 273. See also Ahmad 6/77","source":"Hisn al-Muslim 196 - Sunnah.com","source_url":"https://sunnah.com/hisn:196","tags":["forgiveness","prayer","gratitude"]},{"id":"hisn-197","n":197,"title":"Returning a supplication of forgiveness","chapter_en":"Returning a supplication of forgiveness","chapter_ar":"الدعاء لمن قال غفر الله لك","arabic":"وَلَكَ","transliteration":"Walaka","meaning_en":"And you.","meaning_dv":"","reference":"Ahmad 5/82, and An-Nasa\u0027i in \u0027Amalul-Yawm wal-Laylah p. 218, with checking by Dr. Farooq Hamadah.","source":"Hisn al-Muslim 197 - Sunnah.com","source_url":"https://sunnah.com/hisn:197","tags":["forgiveness"]},{"id":"hisn-198","n":198,"title":"To one who does you a favour","chapter_en":"To one who does you a favour","chapter_ar":"الدعاء لمن صنع إليك معروفاً","arabic":"جَزاكَ اللهُ خَـيْراً","transliteration":"Jazākallāhu khayra.","meaning_en":"May Allah reward you with good.","meaning_dv":"","reference":"At-Tirmidhi (no. 2035). See also Al-Albani, Sahih At-Tirmidhi 2/200 and Sahihul-Jami\u0027 (no. 6244).","source":"Hisn al-Muslim 198 - Sunnah.com","source_url":"https://sunnah.com/hisn:198","tags":[]},{"id":"hisn-199","n":199,"title":"Protection from the Dajjal","chapter_en":"Protection from the Dajjal","chapter_ar":"الذكر الذي يعصم الله به من الدجال","arabic":".(مَنْ حَفِظَ عَشْرَ آيَاتٍ مِنْ أَوَّلِ سُورَةِ الْكَهْفِ عُصِمَ مِنَ الدَّجَّالِ) ، وَالْاسْتِعَاذَةُ بِاللَّهِ مِنْ فِتْنَتِهِ عَقِبَ التَّشَهُّدِ الْأَخِيرِ مِنْ كُلِّ صَلاَةٍ.","transliteration":"--","meaning_en":"Whoever memorizes ten \u0027Ayat (Verses) from the beginning of Surat Al-Kahf, will be protected from the False Messiah 1 if he recites in every prayer after the final Tashahhud before ending the prayer, seeking the protection of Allah from the trials of the False Messiah.","meaning_dv":"","reference":"1 Muslim 1/555, another version mentions the last ten \u0027Ayat, Muslim 1/556. 2 See invocations no. 55 and 56 of this book.","source":"Hisn al-Muslim 199 - Sunnah.com","source_url":"https://sunnah.com/hisn:199","tags":["patience","protection","prayer"]},{"id":"hisn-200","n":200,"title":"To one who pronounces his love for you, for Allah’s sake","chapter_en":"To one who pronounces his love for you, for Allah’s sake","chapter_ar":"الدعاء لمن قال إني أحبك في الله","arabic":"أَحَبَّـكَ الّذي أَحْبَبْـتَني لَه","transliteration":"Aḥabbaka ‘lladhī aḥbabtanī lah.","meaning_en":"May He for Whose sake you love me, love you.","meaning_dv":"","reference":"Abu Dawud 4/333. Al-Albani graded it good in Sahih Abu Dawud 3/965.","source":"Hisn al-Muslim 200 - Sunnah.com","source_url":"https://sunnah.com/hisn:200","tags":[]},{"id":"hisn-201","n":201,"title":"To one who has offered you some of his wealth","chapter_en":"To one who has offered you some of his wealth","chapter_ar":"الدعاء لمن عرض عليك ماله","arabic":"بارَكَ اللهُ لَكَ في أَهْلِكَ وَمالِك","transliteration":"Bārakallāhu laka fī ahlika wa mālik.","meaning_en":"May Allah bless you in your family and your property.","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-BAri 4/88.","source":"Hisn al-Muslim 201 - Sunnah.com","source_url":"https://sunnah.com/hisn:201","tags":["financial","family"]},{"id":"hisn-202","n":202,"title":"To the debtor when his debt is settled","chapter_en":"To the debtor when his debt is settled","chapter_ar":"الدعاء لمن أقرض عند القضاء","arabic":"بارَكَ اللهُ لَكَ في أَهْلِكَ وَمالِك، إِنَّما جَـزاءُ السَّلَفِ الْحَمْدُ والأَداء","transliteration":"Bārakallāhu laka fī ahlika wa mālik, innamā jazā\u0027us-salafi ‘l-ḥamdu wa‘l-adā\u0027.","meaning_en":"May Allah bless you in your family and your wealth, surely the reward for a loan is praise and returning (what was borrowed).","meaning_dv":"","reference":"An-Nasa\u0027i, \u0027Amalul-Yawm wal-Laylahp. 300, Ibn Majah 2/809. See also Al-Albani, Sahih Ibn Majah2/55.","source":"Hisn al-Muslim 202 - Sunnah.com","source_url":"https://sunnah.com/hisn:202","tags":["financial","family","gratitude"]},{"id":"hisn-203","n":203,"title":"For fear of shirk","chapter_en":"For fear of shirk","chapter_ar":"دعاء الخوف من الشرك","arabic":"اللّهُـمَّ إِنّـي أَعـوذُبِكَ أَنْ أُشْـرِكَ بِكَ وَأَنا أَعْـلَمْ، وَأَسْتَـغْفِرُكَ لِما لا أَعْـلَم","transliteration":"Allāhumma innī a`ūdhu bika an ushrika bika wa anā a`lam, wa astaghfiruka limā lā a`lam.","meaning_en":"O Allah, I seek refuge in You lest I associate anything with You knowingly, and I seek Your forgiveness for what I know not.","meaning_dv":"","reference":"Ahmad 4/403. See also Al-Albani, Sahihul-Jami\u0027 As-Saghir 3/233 and Sahihut-Targhib wat- Tarhib 1/19.","source":"Hisn al-Muslim 203 - Sunnah.com","source_url":"https://sunnah.com/hisn:203","tags":["anxiety","forgiveness","protection"]},{"id":"hisn-204","n":204,"title":"To someone who says \"May Allah bless you\"","chapter_en":"To someone who says \"May Allah bless you\"","chapter_ar":"الدعاء لمن قال بارك الله فيك","arabic":"وَفيكَ بارَكَ الله","transliteration":"Wafīka bārakallāh.","meaning_en":"And may Allah bless you.","meaning_dv":"","reference":"Ibn As-Sunni, p. 138, (no. 278). See also Ibn Al-Qayyim, Al-Wdbil As-Sayyib, p. 304, with checking by Basheer Muhammad ?Uyoon.","source":"Hisn al-Muslim 204 - Sunnah.com","source_url":"https://sunnah.com/hisn:204","tags":[]},{"id":"hisn-205","n":205,"title":"The scorn of ascribing things to evil omens","chapter_en":"The scorn of ascribing things to evil omens","chapter_ar":"دعاء كراهية الطيرة","arabic":"اللّهُـمَّ لا طَيْـرَ إِلاّ طَيْـرُك، وَلا خَـيْرَ إِلاّ خَـيْرُك، وَلا إِلهَ غَيْـرُك","transliteration":"Allāhumma lā ṭayra illā ṭayruk, wa lā khayra illā khayruk, wa lā ilāha ghayruk.","meaning_en":"O Allah there is no portent other than Your portent, no goodness other than Your goodness, and none worthy of worship other than You.","meaning_dv":"","reference":"Ahmad 2/220, Ibn As-Sunni (no. 292). See also Al-Albani, Silsilatul-\u0027Ahadlth As-Sahihah 3/54, (no. 1065). As for bodings of good, these used to please the Prophet (ﷺ) and so when he heard good words from someone, he used to say: \"We have taken from you a good portent from your mouth,\" Abu Dawud, Ahmad. See also Al-Albani, Silsilatul-\u0027Ahadith As-Sahihah 2/363, and it is with Abu Ash-Shaikh Al-Asfahani in \u0027Akhlaqun-Nabiyy, pg. 270.","source":"Hisn al-Muslim 205 - Sunnah.com","source_url":"https://sunnah.com/hisn:205","tags":["protection"]},{"id":"hisn-206","n":206,"title":"When mounting an animal or any means of transport","chapter_en":"When mounting an animal or any means of transport","chapter_ar":"دعاء ركوب الدابة أو ما يقوم مقامها","arabic":"بِسْـمِ اللهِ وَالْحَمْـدُ لله، ﴿سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ * وَإِنَّا إِلَى رَبِّنَا لَمُنقَلِبُونَ﴾ الحَمْـدُ لله، الحَمْـدُ لله، الحَمْـدُ لله، اللهُ أكْـبَر، اللهُ أكْـبَر، اللهُ أكْـبَر، سُـبْحانَكَ اللّهُـمَّ إِنّي ظَلَـمْتُ نَفْسي فَاغْـفِرْ لي، فَإِنَّهُ لا يَغْفِـرُ الذُّنوبَ إِلاّ أَنْـت","transliteration":"Bismillāh, walḥamdulillāh. Subḥāna ‘lladhī sakhkhara lanā hādhā wa mā kunnā lahu muqrinīn. Wa innā ilā Rabbinā lamunqalibūn. Alḥamdulillāh, alḥamdulillāh, alḥamdulillāh, Allāhu Akbar, Allāhu Akbar, Allāhu Akbar, Subḥānaka ‘llāhumma innī ẓalamtu nafsī, faghfir lī, fa innahu lā yaghfirudh-dhunūba illā ant.","meaning_en":"With the Name of Allah. Praise is to Allah. Glory is to Him Who has provided this for us though we could never have had it by our efforts. Surely, unto our Lord, we are returning. Praise is to Allah. Praise is to Allah. Praise is to Allah. Allah is the Most Great. Allah is the Most Great. Allah is the Most Great. Glory is to You. O Allah, I have wronged my own soul. Forgive me, for surely none forgives sins but You.","meaning_dv":"","reference":"Abu Dawud 3/34, At-Tirmidhi 5/501. See also Al-Albani, Sahih At-Tirmidhi3/156.","source":"Hisn al-Muslim 206 - Sunnah.com","source_url":"https://sunnah.com/hisn:206","tags":["forgiveness","travel","gratitude"]},{"id":"hisn-207","n":207,"title":"For travel","chapter_en":"For travel","chapter_ar":"دعاء السفر","arabic":"\"اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، ﴿سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ * وَإِنَّا إِلَى رَبِّنَا لَمُنقَلِبُونَ﴾ اللَّهُمَّ إِنّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا البِرَّ وَالتَّقْوَى، وَمِنَ الْعَمَلِ مَا تَرْضَى، اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ، اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَليفَةُ فِي الْأَهْلِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمَنْظَرِ، وَسُوءِ الْمُنْقَلَبِ فِي الْمَالِ وَالْأَهْلِ\"، وإذا رَجَعَ قَالَهُنَّ وَزَادَ فِيهِنَّ: \"آيِبُونَ، تائِبُونَ، عَابِدُونَ، لِرَبِّنَا حَامِدُونَ\".","transliteration":"Allāhu Akbar, Allāhu Akbar, Allāhu Akbar, Subḥāna ‘l-ladhi sakhkhara lanā hādhā wa mā kunnā lahu muqrinīn. Wa innā ilā Rabbinā lamunqalibūn. Allāhumma innā nas\u0027aluka fī safarinā hādha ‘l-birra wat-taqwā, Wa mina ‘l-`amali mā tarḍā, Allāhumma hawwin `alaynā safaranā hādhā waṭwi `annā bu`dah, Allāhumma antas-sāḥibu fis-safar, wa ‘l-khalīfatu fil-ahl, Allāhumma innī a`ūdhu bika min wa`thā\u0027is-safar, wa ka\u0027ābati ‘l-manẓar, wa sū\u0027il-munqalabi fil-māli wa ‘l-ahl. (Upon returning recite the same again adding):","meaning_en":"Allah is the Most Great. Allah is the Most Great. Allah is the Most Great. Glory is to Him Who has provided this for us though we could never have had it by our efforts. Surely, unto our Lord we are returning. O Allah, we ask You on this our journey for goodness and piety, and for works that are pleasing to You. O Allah, lighten this journey for us and make its distance easy for us. O Allah, You are our Companion on the road and the One in Whose care we leave our family. O Allah, I seek refuge in You from this journey\u0027s hardships, and from the wicked sights in store and from finding our family and property in misfortune upon returning. (Upon returning recite the same again adding :) We return repentant to our Lord, worshipping our Lord, and praising our Lord.","meaning_dv":"","reference":"Muslim 2/978.","source":"Hisn al-Muslim 207 - Sunnah.com","source_url":"https://sunnah.com/hisn:207","tags":["forgiveness","family","travel","patience","protection","gratitude"]},{"id":"hisn-208","n":208,"title":"Upon entering a town or village","chapter_en":"Upon entering a town or village","chapter_ar":"دعاء دخول القرية أو البلدة","arabic":"أللّـهُمَّ رَبَّ السَّـمواتِ السّـبْعِ وَما أَظْلَلَـن، وَرَبَّ الأَراضيـنَ السّـبْعِ وَما أقْلَلْـن، وَرَبَّ الشَّيـاطينِ وَما أَضْلَلْـن، وَرَبَّ الرِّياحِ وَما ذَرَيْـن، أَسْـأَلُـكَ خَيْـرَ هذهِ الْقَـرْيَةِ وَخَيْـرَ أَهْلِـها، وَخَيْـرَ ما فيها، وَأَعـوذُ بِكَ مِنْ شَـرِّها وَشَـرِّ أَهْلِـها، وَشَـرِّ ما فيها","transliteration":"Allāhumma Rabbas-samāwātis-sab`i wa mā aẓlaln, Wa Rabba ‘l-arāḍīnas-sab`i wa mā aqlaln, wa Rabbash-shayāṭīni wa mā aḍlaln, wa Rabbar-riyāḥi wa mā dharayn. As\u0027aluka khayra hādhihi ‘l-qaryah, wa khayra ahlihā, wa khayra māfīhā, wa a`ūdhu bika min sharrihā, wa sharri ahlihā, wa sharri mā fīhā.","meaning_en":"O Allah, Lord of the seven heavens and all they overshadow, Lord of the seven worlds and all they uphold, Lord of the devils and all they lead astray, Lord of the winds and all they scatter. I ask You for the goodness of this town, and for the goodness of its people, and for the goodness it contains. I seek refuge in You from its evil, from the evil of its people, and from the evil it contains.","meaning_dv":"","reference":"Al-Hakim who graded it authentic and Ath-Tfaahabi agreed 2/100, and Ibn As-Sunni (no. 524). Al-Hafidh graded it good in his checking of Al-\u0027Athkdr 5/154. Ibn Baz said in Tuhfatul-\u0027Akhydr p. 37, that An-Nasa\u0027i recorded it with a good chain of narration.","source":"Hisn al-Muslim 208 - Sunnah.com","source_url":"https://sunnah.com/hisn:208","tags":["travel","protection","weather"]},{"id":"hisn-209","n":209,"title":"When entering the market","chapter_en":"When entering the market","chapter_ar":"دعاء دخول السوق","arabic":"لا إلهَ إلاّ اللّه وحدَهُ لا شريكَ لهُ، لهُ المُلْـكُ ولهُ الحَمْـد، يُحْيـي وَيُميـتُ وَهُوَ حَيٌّ لا يَمـوت، بِيَـدِهِ الْخَـيْرُ وَهوَ على كلّ شيءٍ قدير","transliteration":"Lā ilāha illallāh waḥdahu lā sharīka lah, Lahu ‘l-mulku wa lahu ‘l-ḥamd, Yuḥyī wa yumīt, wa huwa ḥayyun lā yamūt, Biyadihi ‘l-khayr, wa huwa `alā kulli shay\u0027in Qadīr.","meaning_en":"None has the right to be worshipped but Allah alone, Who has no partner. His is the dominion and His is the praise. He brings life and He causes death, and He is living and does not die. In His Hand is all good, and He is Able to do all things.","meaning_dv":"","reference":"At-Tirmidhi 5/291, and Al-Hakim 1/538. Al-Albani graded it good in Sahih Ibn Majah 2/21 and Sahih At-Tirmidhi 3/152.","source":"Hisn al-Muslim 209 - Sunnah.com","source_url":"https://sunnah.com/hisn:209","tags":["travel","gratitude","death"]},{"id":"hisn-210","n":210,"title":"When the mounted animal (or mean of transport) stumbles","chapter_en":"When the mounted animal (or mean of transport) stumbles","chapter_ar":"الدعاء إذا تعس المركوب","arabic":"بِسْـمِ اللهِ","transliteration":"Bismillāh.","meaning_en":"With the Name of Allah.","meaning_dv":"","reference":"Abu Dawud 4/296. Al-Albani graded it authentic in Sahih Abu Dawud 3/941.","source":"Hisn al-Muslim 210 - Sunnah.com","source_url":"https://sunnah.com/hisn:210","tags":["travel"]},{"id":"hisn-211","n":211,"title":"Supplication of the traveller for the resident","chapter_en":"Supplication of the traveller for the resident","chapter_ar":"دعاء المسافر للمقيم","arabic":"أَسْتَـوْدِعُكُـمُ اللَّهَ الَّذي لا تَضـيعُ وَدائِعُـه","transliteration":"Astawdi`ukumu ‘llāha ‘l-ladhi lā taḍī`u wadā\u0027i`uh.","meaning_en":"I place you in the trust of Allah, whose trust is never misplaced.","meaning_dv":"","reference":"Ahmad 2/403, Ibn Majah 2/943. See also Al-Albani, Sahih Ibn Majah 2/133.","source":"Hisn al-Muslim 211 - Sunnah.com","source_url":"https://sunnah.com/hisn:211","tags":["travel"]},{"id":"hisn-212","n":212,"title":"Supplication of the resident for the traveller","chapter_en":"Supplication of the resident for the traveller","chapter_ar":"دعاء المقيم للمسافر","arabic":"أَسْتَـوْدِعُ اللَّهَ ديـنَكَ وَأَمانَتَـكَ، وَخَـواتيـمَ عَمَـلِك","transliteration":"Astawdi`ullāha dīnak, wa amānatak, wa khawātīma `amalik.","meaning_en":"I leave your religion in the care of Allah, as well as your safety, and the last of your deeds.","meaning_dv":"","reference":"Ahmad 2/7, At-Tirmidhi 5/499. See also Al-Albani, Sahih At-Tirmidhi 2/155.","source":"Hisn al-Muslim 212 - Sunnah.com","source_url":"https://sunnah.com/hisn:212","tags":["travel"]},{"id":"hisn-213","n":213,"title":"Supplication of the resident for the traveller","chapter_en":"Supplication of the resident for the traveller","chapter_ar":"دعاء المقيم للمسافر","arabic":"زَوَّدَكَ اللَّهُ التقْوى، وَغَفَـرَذَنْـبَكَ، وَيَسَّـرَ لَكَ الخَـيْرَ حَيْـثُما كُنْـت","transliteration":"Zawwadaka ‘llāhut-taqwā, wa ghafara dhanbak, wa yassara laka ‘l-khayra ḥaythu mā kunt.","meaning_en":"May Allah give you piety as your provision, forgive your sins, and make goodness easy for you wherever you are.","meaning_dv":"","reference":"At-Tirmidhi. See Al-Albani, Sahih At-Tirmidhi, 3/155.","source":"Hisn al-Muslim 213 - Sunnah.com","source_url":"https://sunnah.com/hisn:213","tags":["forgiveness","financial","travel"]},{"id":"hisn-214","n":214,"title":"Takbir and Tasbih during travel","chapter_en":"Takbir and Tasbih during travel","chapter_ar":"التكبير والتسبيح في سير السفر","arabic":"قَالَ جَابِرٌ رضي الله عنه: (كُنَّا إِذَا صَعَدْنَا كَبَّرْنَا، وَإِذَا نَزَلْنَا سَبَّحْنَا)","transliteration":"--","meaning_en":"Jabir (ra), said:","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 6/135.","source":"Hisn al-Muslim 214 - Sunnah.com","source_url":"https://sunnah.com/hisn:214","tags":["travel"]},{"id":"hisn-215","n":215,"title":"Prayer of the traveller as dawn approaches","chapter_en":"Prayer of the traveller as dawn approaches","chapter_ar":"دعاء المسافر إذا أسحر","arabic":"سَمِـعَ سـامِعٌ بِحَمْـدِ اللهِ وَحُسْـنِ بَلائِـهِ عَلَيْـنا. رَبَّنـا صـاحِبْـنا وَأَفْـضِل عَلَيْـنا عائِذاً باللهِ مِنَ النّـار","transliteration":"Sami`a sāmi`un biḥamdillāhi wa ḥusni balā\u0027ihi `alaynā. Rabbanā ṣāḥibnā, wa afḍil `alaynā, `ā\u0027idhan billāhi minan-nār.","meaning_en":"He Who listens has heard that we praise Allah for the good things He gives us. Our Lord, be with us and bestow Your favor upon us. I seek the protection of Allah from the Fire.","meaning_dv":"","reference":"Muslim 4/2086, the meaning of sami`a sāmi`un (who listens has heard) is that \u0027a witness has witnessed our praise of Allah due to His blessings and favor upon us.\u0027 It could also be read samma`a sāmi`un, in which case it means \u0027one who has heard this statement of mine will convey it to another and he will say it as well.\u0027 This is due to the attention given to the Thikr (remembrance of Allah) and supplications made during the early morning hours. The meaning of his saying \u0027Our Lord, be with us and bestow Your favor upon us\u0027 is: \u0027Our Lord, protect us and guard us. Bless us with Your numerous bounties, and avert from us every evil.\u0027 See An-Nawawi, Sharh Sahih Muslim 17/39.","source":"Hisn al-Muslim 215 - Sunnah.com","source_url":"https://sunnah.com/hisn:215","tags":["forgiveness","travel","protection","prayer","gratitude"]},{"id":"hisn-216","n":216,"title":"Stopping or lodging somewhere in travel and otherwise","chapter_en":"Stopping or lodging somewhere in travel and otherwise","chapter_ar":"الدعاء إذا نزل منزلا في سفر أو غيره","arabic":"أَعـوذُ بِكَلِـماتِ اللّهِ التّـامّاتِ مِنْ شَـرِّ ما خَلَـق","transliteration":"A`ūdhu bikalimāti ‘llāhit-tāmmāti min sharri mā khalaq.","meaning_en":"I seek refuge in the Perfect Words of Allah from the evil of what He has created.","meaning_dv":"","reference":"Muslim 4/2080.","source":"Hisn al-Muslim 216 - Sunnah.com","source_url":"https://sunnah.com/hisn:216","tags":["travel","protection"]},{"id":"hisn-217","n":217,"title":"While returning from travel","chapter_en":"While returning from travel","chapter_ar":"ذكر الرجوع من السفر","arabic":"يُكَبِّرُ عَلَى كُلِّ شَرَفٍ ثَلاَثَ تَكْبِيرَاتٍ ثُمَّ يَقُولُ: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، آيِبُونَ، تَائِبُونَ، عَابِدُونَ، لِرَبِّنا حَامِدُونَ، صَدَقَ اللَّهُ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزابَ وَحْدَهُ","transliteration":"From every elevated point say Allāhu Akbar (three times), and then recite:","meaning_en":"From every elevated point say Allāhu Akbar (Allah is the Most Great) three times and then recite: None has the right to be worshipped but Allah alone, Who has no partner. His is the dominion and His is the praise, and He is Able to do all things. We return repentant to our Lord, worshipping our Lord, and praising our Lord. He fulfilled His Promise, He aided His slave, and He alone defeated the Confederates.","meaning_dv":"","reference":"Bukhari 7/163, Muslim 2/980. The Prophet (ﷺ) used to say this when returning from a campaign or from Hajj.","source":"Hisn al-Muslim 217 - Sunnah.com","source_url":"https://sunnah.com/hisn:217","tags":["forgiveness","travel","gratitude","hajj"]},{"id":"hisn-218","n":218,"title":"What to say upon receiving pleasing or displeasing news","chapter_en":"What to say upon receiving pleasing or displeasing news","chapter_ar":"ما يقول من أتاه أمر يسره أو يكرهه","arabic":"كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا أَتَاهُ الْأَمْرُ يَسُرُّهُ قَالَ: (الْحَمْدُ لِلَّهِ الَّذِي بِنِعْمَتِهِ تَتِمُّ الصَّالِحَاتُ) وَإِذَا أَتَاهُ الْأَمْرُ يَكْرَهُهُ قَالَ: (الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ)","transliteration":"When something happened that pleased him, the Prophet (ﷺ) used to say:","meaning_en":"When something happened that pleased him, the Prophet (ﷺ) used to say: Praise is to Allah Who by His blessings all good things are perfected. And if something happened that displeased him, he used to say: Praise is to Allah in all circumstances.","meaning_dv":"","reference":"Ibn As-Sunni, \u0027Amalul-Yawm wal-Laylah, and Al-Hakim who graded it authentic 1/499. See also Al-Albani, Sahihul-Jami\u0027 As-Saghir 4/201.","source":"Hisn al-Muslim 218 - Sunnah.com","source_url":"https://sunnah.com/hisn:218","tags":["forgiveness","gratitude"]},{"id":"hisn-219","n":219,"title":"Excellence of sending prayers upon the Prophet (saws)","chapter_en":"Excellence of sending prayers upon the Prophet (saws)","chapter_ar":"فضل الصلاة على النبي ﷺ","arabic":"قَالَ النَّبِيُّ صلى الله عليه وسلم: (مَنْ صَلَّى عَلَيَّ صَلاَةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْراً)","transliteration":"--","meaning_en":"The Prophet (ﷺ) said:","meaning_dv":"","reference":"Muslim 1/288.","source":"Hisn al-Muslim 219 - Sunnah.com","source_url":"https://sunnah.com/hisn:219","tags":["prayer"]},{"id":"hisn-220","n":220,"title":"Excellence of sending prayers upon the Prophet (saws)","chapter_en":"Excellence of sending prayers upon the Prophet (saws)","chapter_ar":"فضل الصلاة على النبي ﷺ","arabic":"وَقَالَ صلى الله عليه وسلم: (لاَ تَجْعَلُوا قَبْرِي عِيداً وَصَلُّوا عَلَيَّ؛ فَإِنَّ صَلاَتَكُم تَبْلُغُنِي حَيْثُ كُنْتُمْ)","transliteration":"--","meaning_en":"The Prophet (ﷺ) said:","meaning_dv":"","reference":"Abu Dawud 2/218, Ahmad 2/367. Al-Albani graded it authentic in Sahih Abu Dawud 2/383.","source":"Hisn al-Muslim 220 - Sunnah.com","source_url":"https://sunnah.com/hisn:220","tags":["prayer"]},{"id":"hisn-221","n":221,"title":"Excellence of sending prayers upon the Prophet (saws)","chapter_en":"Excellence of sending prayers upon the Prophet (saws)","chapter_ar":"فضل الصلاة على النبي ﷺ","arabic":"وَقَالَ صلى الله عليه وسلم: (الْبَخِيلُ مَنْ ذُكِرْتُ عِنْدَهُ فَلَمْ يُصَلِّ عَلَيَّ)","transliteration":"--","meaning_en":"The Prophet (ﷺ) said:","meaning_dv":"","reference":"At-Tirmidhi 5/551 and others. See also Al-Albani, Sahih At-Tirmidhi 3/177 and Sahihul-Jarai\u0027 As-Saghir 3/25.","source":"Hisn al-Muslim 221 - Sunnah.com","source_url":"https://sunnah.com/hisn:221","tags":["prayer"]},{"id":"hisn-222","n":222,"title":"Excellence of sending prayers upon the Prophet (saws)","chapter_en":"Excellence of sending prayers upon the Prophet (saws)","chapter_ar":"فضل الصلاة على النبي ﷺ","arabic":"وَقَالَ صلى الله عليه وسلم:(إِنَّ لِلَّهِ مَلاَئِكَةً سَيَّاحِينَ فِي الْأَرْضِ يُبَلِّغُونِي مِنْ أُمَّتِي السَّلاَمَ)","transliteration":"--","meaning_en":"The Prophet (ﷺ) said:","meaning_dv":"","reference":"An-Nasa\u0027i, Al-Hakim 2/421. Al-Albani graded it authentic in Sahih An-Nasa\u0027i 1/274.","source":"Hisn al-Muslim 222 - Sunnah.com","source_url":"https://sunnah.com/hisn:222","tags":["prayer"]},{"id":"hisn-223","n":223,"title":"Excellence of sending prayers upon the Prophet (saws)","chapter_en":"Excellence of sending prayers upon the Prophet (saws)","chapter_ar":"فضل الصلاة على النبي ﷺ","arabic":"وَقَالَ صلى الله عليه وسلم: (مَا مِنْ أَحَدٍ يُسَلِّمُ عَلَيَّ إِلاَّ رَدَّ اللَّهُ عَلَيَّ رُوحِيَ حَتَّى أَرُدَّ عَلَيْهِ السَّلاَمَ)","transliteration":"--","meaning_en":"The Prophet (ﷺ) said:","meaning_dv":"","reference":"Abu Dawud (no. 2041). Al-Albani graded it good in Sahih Abu Dawud 1/383.","source":"Hisn al-Muslim 223 - Sunnah.com","source_url":"https://sunnah.com/hisn:223","tags":["prayer"]},{"id":"hisn-224","n":224,"title":"Excellence of spreading the Islamic greeting","chapter_en":"Excellence of spreading the Islamic greeting","chapter_ar":"إفشاء السلام","arabic":"قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: (لاَ تَدْخُلُوا الْجَنَّةَ حَتَّى تُؤْمِنُوا، وَلاَ تُؤْمِنُوا حَتَّى تَحَابُّوا، أَوَلاَ أَدُلُّكُم عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُم، أَفْشُوا السَّلاَمَ بَيْنَكُمْ)","transliteration":"--","meaning_en":"The Prophet (ﷺ) said:","meaning_dv":"","reference":"Muslim 1/74 and others.","source":"Hisn al-Muslim 224 - Sunnah.com","source_url":"https://sunnah.com/hisn:224","tags":[]},{"id":"hisn-225","n":225,"title":"Excellence of spreading the Islamic greeting","chapter_en":"Excellence of spreading the Islamic greeting","chapter_ar":"إفشاء السلام","arabic":"ثَلاَثٌ مَنْ جَمَعَهُنَّ فَقَدْ جَمَعَ الْإِيمَانَ: الْإِنْصَافُ مِنْ نَفْسِكَ، وَبَذْلُ السَّلاَمِ لِلْعَالَمِ، وَالْإِنْفَاقُ مِنَ الإِقْتَارِ","transliteration":"","meaning_en":"Three characteristics, whoever combines them, has completed his faith:","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 1/82 as a statement of the Companion \u0027Ammar (RA).","source":"Hisn al-Muslim 225 - Sunnah.com","source_url":"https://sunnah.com/hisn:225","tags":[]},{"id":"hisn-226","n":226,"title":"Excellence of spreading the Islamic greeting","chapter_en":"Excellence of spreading the Islamic greeting","chapter_ar":"إفشاء السلام","arabic":"وَعَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أنَّ رَجُلاً سَأَلَ النَّبِيَّ صلى الله عليه وسلم أيُّ الْإِسْلاَمِ خَيْرٌ قَالَ: (تُطْعِمُ الطَّعَامَ، وَتَقْرأُ السَّلاَمَ عَلَى مَنْ عَرَفْتَ وَمَنْ لَمْ تَعْرِفْ)","transliteration":"--","meaning_en":"`Abdullah bin `Umar (RA) said:","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 1/55, Muslim 1/65.","source":"Hisn al-Muslim 226 - Sunnah.com","source_url":"https://sunnah.com/hisn:226","tags":[]},{"id":"hisn-227","n":227,"title":"Returning a greeting to a disbeliever","chapter_en":"Returning a greeting to a disbeliever","chapter_ar":"كيف يرد السلام على الكافر إذا سلم","arabic":"إذَا سَلَّمَ عَلَيْكُمْ أَهْلُ الْكِتَابِ فَقُولُوا: وَعَلَيْكُمْ","transliteration":"If one of the People of the Scripture (i.e. Christians and Jews) greets you, saying As-Salāmu `alaykum, then say (to him):","meaning_en":"If one of the People of the Scripture (i.e. Christians and Jews) greets you saying As-Salaamu `alaykum, then say (to him): And upon you .","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 11/42, Muslim 4/1705.","source":"Hisn al-Muslim 227 - Sunnah.com","source_url":"https://sunnah.com/hisn:227","tags":[]},{"id":"hisn-228","n":228,"title":"Upon hearing a rooster crow or the braying of a donkey","chapter_en":"Upon hearing a rooster crow or the braying of a donkey","chapter_ar":"دعاء عند سماع صياح الديك ونهيق الحمار","arabic":"إِذَا سَمِعْتُمْ صِيَاحَ الدِّيَكَةِ فَاسْأَلُوا اللَّهَ مِنْ فَضْلِهِ؛ فَإِنَّهَا رَأَتْ مَلَكاً وَإِذَا سَمِعْتُمْ نَهِيقَ الْحِمَارِ فَتَعَوَّذُوا بِاللَّهِ مِنَ الشَّيطَانِ؛ فَإِنَّهُ رَأَى شَيْطَاناً","transliteration":"--","meaning_en":"When you hear the cock\u0027s crow, ask Allah for His favor upon you for surely it has seen an angel. When you hear the bray of a donkey, seek refuge in Allah from Satan, for surely it has seen a devil.","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 6/350, Muslim 4/2092.","source":"Hisn al-Muslim 228 - Sunnah.com","source_url":"https://sunnah.com/hisn:228","tags":["protection"]},{"id":"hisn-229","n":229,"title":"Upon hearing the barking of dogs at night","chapter_en":"Upon hearing the barking of dogs at night","chapter_ar":"دعاء عند سماع نباح الكلاب بالليل","arabic":"إِذَا سَمِعْتُمْ نُبَاحَ الْكِلاَبِ وَنَهِيقَ الْحَمِيرِ بِاللَّيْلِ فَتَعَوَّذُوا بِاللَّهِ مِنْهُنَّ؛ فَإِنَّهُنَّ يَرَيْنَ مَا لاَ تَرَوْنَ","transliteration":"","meaning_en":"When you hear a dog barking or a donkey braying in the night, then seek refuge in Allah from them, for surely they have seen what you see not.","meaning_dv":"","reference":"Abu Dawud 4/327, Ahmad 3/306. Al-Albani graded it authentic in Sahih Abu Dawud 3/961.","source":"Hisn al-Muslim 229 - Sunnah.com","source_url":"https://sunnah.com/hisn:229","tags":["protection"]},{"id":"hisn-230","n":230,"title":"For one you have insulted","chapter_en":"For one you have insulted","chapter_ar":"الدعاء لمن سببته","arabic":"قال صلى الله عليه وسلم: \"اللَّهُم فأيما مؤمن سببته فاجعل ذلك له قربة إليك يوم القيامة\"","transliteration":"Allāhumma fa\u0027ayyumā mu\u0027minin sababtuhu faj`al dhālika lahu qurbatan ilayka yawma ‘l-qiyāmah.","meaning_en":"O Allah, whomever of the believers I have abused, give him the reward of a sacrificial slaughter for it on the Day of Resurrection.","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 11/171, Muslim 4/2007. The wording in Muslim\u0027s report is: \u0027make it a purification for him and a source of mercy.","source":"Hisn al-Muslim 230 - Sunnah.com","source_url":"https://sunnah.com/hisn:230","tags":["daily"]},{"id":"hisn-231","n":231,"title":"The etiquette of praising a fellow Muslim","chapter_en":"The etiquette of praising a fellow Muslim","chapter_ar":"ما يقول المسلم إذا مدح المسلم","arabic":"قال صلى الله عليه وسلم: \"إِذَا كَانَ أَحَدُكُم مَادِحاً صَاحِبَهُ لاَ مَحَالَةَ فَلْيَقُلْ: أَحْسِبُ فُلاَناً وَاللَّهُ حَسِيبُهُ، وَلاَ أُزَكِّي عَلَى اللَّهِ أَحَداً، أَحْسِبُهُ – إِنْ كَانَ يَعْلَمُ ذَاكَ – كَذَا وَكَذَا\"","transliteration":"If any of you praises his companion then let him say:","meaning_en":"If any of you praises his companion then let him say: I consider (such and such a person), and Allah is his Assessor, (meaning: and I cannot claim anyone to be pious before Allah) if you know of this (good character trait in the person) to be such and such (saying what he thinks is praiseworthy in that person).","meaning_dv":"","reference":"Muslim 4/2296.","source":"Hisn al-Muslim 231 - Sunnah.com","source_url":"https://sunnah.com/hisn:231","tags":["forgiveness","gratitude"]},{"id":"hisn-232","n":232,"title":"For the one that have been praised","chapter_en":"For the one that have been praised","chapter_ar":"ما يقول المسلم إذا زكي","arabic":"اللَّهُمَّ لاَ تُؤَاخِذْنِي بِمَا يَقُولُونَ وَاغْفِرْ لِي مَا لاَ يَعْلَمُونَ [وَاجْعَلْنِي خَيْرًا مِمَّا يَظُّنُّونَ]","transliteration":"Allāhumma lā tu\u0027ākhidhnī bimā yaqūlūn, waghfir lī mā lā ya`lamūn [waj`alnī khayran mimmā yaẓunnūn].","meaning_en":"O Allah, do not call me to account for what they say and forgive me for what they have no knowledge of [and make me better than they imagine].","meaning_dv":"","reference":"Al-Bukhari, Al-\u0027Adabul-Mufrad no. 761. See Al-Albani, Sahih Al-\u0027Adabul-Mufrad (no. 585). The portion between brackets if from Al-Bayhaqi, Shu\u0027ab Al-Iman 4/228, and comes another account.","source":"Hisn al-Muslim 232 - Sunnah.com","source_url":"https://sunnah.com/hisn:232","tags":["forgiveness","gratitude"]},{"id":"hisn-233","n":233,"title":"The Talbiya for the one doing Hajj or \u0027Umrah","chapter_en":"The Talbiya for the one doing Hajj or \u0027Umrah","chapter_ar":"كيف يلبي المحرم في الحج أو العمرة","arabic":"لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ والنِّعْمَة لَكَ والمُلْكُ، لَا شَرِيكَ لَكَ","transliteration":"Labbayk-Allāhumma labbayk, labbayka lā sharīka laka labbayk, inna ‘l-ḥamda, wanni`mata, laka wa ‘l-mulk, lā sharīka lak.","meaning_en":"I am here at Your service, O Allah, I am here at Your service. I am here at Your service, You have no partner, I am here at Your service. Surely the praise, and blessings are Yours, and the dominion. You have no partner.","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 3/408, Muslim 2/841.","source":"Hisn al-Muslim 233 - Sunnah.com","source_url":"https://sunnah.com/hisn:233","tags":["forgiveness","gratitude","hajj"]},{"id":"hisn-234","n":234,"title":"The Takbîr passing the black stone","chapter_en":"The Takbîr passing the black stone","chapter_ar":"التكبير إذا أتي الركن الأسود","arabic":"طَافَ النَّبيُّ صلى الله عليه وسلم بِالْبَيْتِ عَلَى بَعِيرٍ كُلَّمَا أَتَى الرُّكْنَ أَشَارَ إِلَيْهِ بِشَيْءٍ عِنْدَهُ وَكَبَّرَ","transliteration":"--","meaning_en":"The Prophet (ﷺ) performed Tawaf riding a camel. Every time he passed the corner (containing the Black Stone), he would point to it with something that he was holding and say:","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 3/476. See also 472. The \u0027something\u0027 that was referred to in this Hadith was a cane.","source":"Hisn al-Muslim 234 - Sunnah.com","source_url":"https://sunnah.com/hisn:234","tags":["forgiveness","travel","hajj"]},{"id":"hisn-235","n":235,"title":"Between the Yemeni corner and the black stone","chapter_en":"Between the Yemeni corner and the black stone","chapter_ar":"الدعاء بين الركن اليماني والحجر الأسود","arabic":"﴿رَبَّنَا آتِنَا في الدُّنْيَا حسَنَةً وفي الآخِرَةِ حسَنةً وقِنَا عذَابَ النَّارِ﴾","transliteration":"Rabbanā ātinā fid-dunyā ḥasanah wa fi ‘l-ākhirati ḥasanah wa qinā `adhāban-nār.","meaning_en":"Our Lord, grant us the good things in this world, and the good things in the next life, and save us from the punishment of the Fire.","meaning_dv":"","reference":"Abu Dawud 2/179, Ahmad 3/411, Al-Baghawi, Sharhus-Sunnah 7/128. Al-Albani graded it good in Sahih Abu Dawud 1/354. The Ayat is from Surat Al-Baqarah, 2:201.","source":"Hisn al-Muslim 235 - Sunnah.com","source_url":"https://sunnah.com/hisn:235","tags":["hajj"]},{"id":"hisn-236","n":236,"title":"When at Mount Safa and Mount Marwah","chapter_en":"When at Mount Safa and Mount Marwah","chapter_ar":"دعاء الوقوف على الصفا والمروة","arabic":"(لَمَّا دَنَا النَّبِيُّ صلى الله عليه وسلم مِنَ الصَّفَا قَرَأَ: ﴿إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَآئِرِ اللَّهِ﴾ \"أَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ\" فَبَدَأَ بِالصَّفَا فَرَقِيَ عَلَيْهِ حَتَّى رَأَى الْبَيْتَ، فَاسْتَقْبَلَ الْقِبْلَةَ، فَوَحَّدَ اللَّهَ وَكبَّرَهُ وَقَالَ: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ، أَنْجَزَ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزَابَ وَحْدَهُ، ثُمَّ دَعَا بَيْنَ ذلكَ. قَالَ مِثْلَ هَذَا ثَلاَثَ مَرَّاتٍ) الْحَدِيثُ. وَفِيهِ: (فَفَعَلَ عَلَى الْمَرْوَةِ كَمَا فَعَلَ عَلَى الصَّفَا)","transliteration":"Whenever the Prophet (ﷺ) approached Mount Safa, he would recite:","meaning_en":"Whenever the Prophet (ﷺ) approached Mount Safa, he would recite: Surely Safa and Marwah are among the signs of Allah. I begin by that which Allah began. He began (his Sa\u0027y) at Mount Safa climbing it until he could see the House. He then faced the Qiblah repeating the words: There is none worthy of worship but Allah, and Allah is the Most Great. Then he said: None has the right to be worshipped but Allah alone, Who has no partner, His is the dominion and His is the praise, and He is Able to do all things. None has the right to be worshipped but Allah alone, He fulfilled His Promise, He aided His slave, and He alone defeated Confederates. Then he would ask Allah for what he liked, repeating the same thing like this three times. He did at Mount Marwah as he did at Mount Safa.","meaning_dv":"","reference":"Muslim 2/888.","source":"Hisn al-Muslim 236 - Sunnah.com","source_url":"https://sunnah.com/hisn:236","tags":["travel","daily","gratitude","hajj"]},{"id":"hisn-237","n":237,"title":"The Day of \u0027Arafah","chapter_en":"The Day of \u0027Arafah","chapter_ar":"الدعاء يوم عرفة","arabic":"خير الدعاء دعاء يوم عرفة ، وخيرُ ما قلت أنا والنبيُّون من قبلي : لا إله إلا الله وحدهُ لا شريك لهُ ، لهُ الملكُ ولهُ الحمدُ وهو على كل شيء قدير.","transliteration":"Lā \u0027ilāha \u0027illallāhu waḥdahu lā sharīka lahu, lahul-mulku wa lahul-ḥamdu wa huwa `alā kulli shay\u0027in qadīr.","meaning_en":"None has the right to be worshipped but Allah Alone, Who has no partner. His is the dominion and His is the praise, and He is Able to do all things.","meaning_dv":"","reference":"At-Tirmidhi. Al-Albani graded it good in Sahih At-Tirmidhi 3/184, and also Silsilatul-\u0027Ahadith As-Sahihah 4/6.","source":"Hisn al-Muslim 237 - Sunnah.com","source_url":"https://sunnah.com/hisn:237","tags":["gratitude","hajj"]},{"id":"hisn-238","n":238,"title":"Remembrance at Muzdalifa","chapter_en":"Remembrance at Muzdalifa","chapter_ar":"الذكر عند المشعر الحرام","arabic":"رَكِبَ صلى الله عليه وسلم الْقَصْوَاءَ حَتَّى أَتَى الْمَشْعَرَ الْحَرَامَ فَاسْتَقْبَلَ الْقِبْلَةَ (فَدَعَاهُ، وَكَبَّرَهُ، وَهَللَّهُ، وَوَحَّدَهُ) فَلَمْ يَزَلْ وَاقِفاً حَتَّى أَسْفَرَ جِدَّاً فَدَفَعَ قَبْلَ أَنْ تَطْلُعَ الشَّمسُ.","transliteration":"","meaning_en":"\u0027He (ﷺ) rode Al-Qaswa until he reached Al-MashAAar Al-Haram, he then faced the qiblah, supplicated to Allah, and extoled His greatness and oneness. He stood until the sun shone but left before it rose.\u0027","meaning_dv":"","reference":"Muslim 2/891.","source":"Hisn al-Muslim 238 - Sunnah.com","source_url":"https://sunnah.com/hisn:238","tags":[]},{"id":"hisn-239","n":239,"title":"Takbir when throwing each pebble at the Jamarat","chapter_en":"Takbir when throwing each pebble at the Jamarat","chapter_ar":"التكبير عند رمي الجمار مع كل حصاة","arabic":"يُكَبِّرُ كُلَّمَا رَمَى بِحَصَاةٍ عِنْدَ الْجِمَارِ الثَّلاَثِ، ثُمَّ يَتَقَدَّمُ، ويَقِفُ يَدْعُو مُسْتَقْبِلَ الْقِبلَةِ، رَافِعاً يَدَيْهِ بَعْدَ الْجَمْرَةِ الْأُولَى وَالثَّانِيَةِ. أَمَّا جَمْرَةُ الْعَقَبَةِ فَيَرْمِيهَا وَيُكَبِّرُ عِنْدَ كُلِّ حَصَاةٍ وَيَنْصَرِفُ وَلاَ يَقِفُ عِنْدَهَا","transliteration":"--","meaning_en":"The Prophet (ﷺ) said Allāhu Akbar (Allah is the Most Great) with each pebble he threw at the three pillars. Then he went forward, stood facing the Qiblah, and raised his hands and called upon Allah. That was after (stoning) the first and second pillars. As for the third, he stoned it and called out Allāhu Akbar with every pebble he threw, but when he was finished he left without standing at it (for supplications).","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 3/581, 3, 4, and Muslim","source":"Hisn al-Muslim 239 - Sunnah.com","source_url":"https://sunnah.com/hisn:239","tags":["hajj"]},{"id":"hisn-240","n":240,"title":"At times of amazement and that which delights","chapter_en":"At times of amazement and that which delights","chapter_ar":"ما يقول عند التعجب والأمر السار","arabic":"سُـبْحانَ الله","transliteration":"Subḥānallāh!","meaning_en":"(Glory is to Allah).","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 1/210, 390, 414 and Muslim 4/1857.","source":"Hisn al-Muslim 240 - Sunnah.com","source_url":"https://sunnah.com/hisn:240","tags":[]},{"id":"hisn-241","n":241,"title":"At times of amazement and that which delights","chapter_en":"At times of amazement and that which delights","chapter_ar":"ما يقول عند التعجب والأمر السار","arabic":"اللهُ أَكْـبَر","transliteration":"Allāhu Akbar!","meaning_en":"(Allah is the Most Great)","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 8/441. See also Al-Albani, Sahih At-Tirmidhi 2/103, 235, Ahmad 5/218.","source":"Hisn al-Muslim 241 - Sunnah.com","source_url":"https://sunnah.com/hisn:241","tags":[]},{"id":"hisn-242","n":242,"title":"Upon receiving pleasant news","chapter_en":"Upon receiving pleasant news","chapter_ar":"ما يفعل من أتاه أمر يسره","arabic":"كَانَ النَّبيُّ صلى الله عليه وسلم إِذَا أَتَاهُ أَمْرٌ يَسُرُّهُ أَوْ يُسَرُّ بِهِ خَرَّ سَاجِداً شُكْراً لِلَّهِ تَبَارَكَ وَتَعَالَى","transliteration":"","meaning_en":"The Prophet (ﷺ), upon receiving news which pleased him or which caused pleasure, would prostrate in gratitude to Allah blessed and exalted.","meaning_dv":"","reference":"Abu Dawud, Ibn Majah, At-Tirmidhi. See also Al-Albani, Sahih Ibn Majah 1/233, and \u0027Irwa\u0027ul-Ghalil 2/226.","source":"Hisn al-Muslim 242 - Sunnah.com","source_url":"https://sunnah.com/hisn:242","tags":["prayer","gratitude"]},{"id":"hisn-243","n":243,"title":"When feeling some pain in the body","chapter_en":"When feeling some pain in the body","chapter_ar":"ما يفعل ويقول من أحس وجعاً في جسده","arabic":"ضَعْ يَدَكَ عَلَى الَّذِي تَألَّمَ مِنْ جَسَدِكَ وَقُلْ: \"بِسْمِ اللَّهِ\" ثَلاَثاً، وَقُلْ سَبْعَ مَرَّاتٍ: \"أَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ\"","transliteration":"Put your hand on the place where you feel pain and say:","meaning_en":"Put your hand on the place where you feel pain and say: With the Name of Allah (three times). Then say seven times: I seek refuge in Allah and in His Power from the evil of what I find and of what I guard against.","meaning_dv":"","reference":"Muslim 4/1728.","source":"Hisn al-Muslim 243 - Sunnah.com","source_url":"https://sunnah.com/hisn:243","tags":["illness","protection"]},{"id":"hisn-244","n":244,"title":"When in fear of afflicting something with an (evil) eye from oneself","chapter_en":"When in fear of afflicting something with an (evil) eye from oneself","chapter_ar":"ما يقول من خشي أن يصيب شيئاً بعينه","arabic":"إِذَا رَأَى أَحَدُكُم مِنْ أَخِيهِ، أَوْ مِنْ نَفْسِهِ، أَوْ مِنْ مَالِهِ مَا يُعْجِبُهُ [فَلْيَدْعُ لَهُ بِالْبَرَكَةِ] فَإِنَّ الْعَيْنَ حَقٌّ","transliteration":"","meaning_en":"If you see something from your brother, yourself or wealth which you find impressing, then invoke blessings for it, for the evil eye is indeed true.","meaning_dv":"","reference":"Ahmad 4/447, Ibn Majah, Malik. Al-Albani graded it authentic in Sahihul-Jami\u0027 As-Saghir 1/212. Also see Al-Arna\u0027ut\u0027s checking of Ibn Al-Qayyim\u0027s Zadul-Ma\u0027ad 4/170.","source":"Hisn al-Muslim 244 - Sunnah.com","source_url":"https://sunnah.com/hisn:244","tags":["anxiety","forgiveness","financial","protection","gratitude"]},{"id":"hisn-245","n":245,"title":"When startled","chapter_en":"When startled","chapter_ar":"ما يقال عند الفزع","arabic":"لا إلهَ إلاّ اللّهُ","transliteration":"Lā ilāha illallāh!","meaning_en":"There is none worthy of worship but Allah!","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 6/181, Muslim 4/2208.","source":"Hisn al-Muslim 245 - Sunnah.com","source_url":"https://sunnah.com/hisn:245","tags":[]},{"id":"hisn-246","n":246,"title":"When slaughtering or offering a sacrifice","chapter_en":"When slaughtering or offering a sacrifice","chapter_ar":"ما يقول عند الذبح أو النحر","arabic":"بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ [اللَّهُمَّ مِنْكَ وَلَكَ] اللَّهُمَّ تَقَبَّلْ مِنِّي","transliteration":"Bismillāh wallāhu Akbar [Allāhumma minka wa lak] Allāhumma taqabbal minnī.","meaning_en":"With the Name of Allah, Allah is the Most Great! [O Allah, from You and to You.] O Allah, accept it from me.","meaning_dv":"","reference":"Muslim 3/ 1557, Al-Bayhaqi 9/287.","source":"Hisn al-Muslim 246 - Sunnah.com","source_url":"https://sunnah.com/hisn:246","tags":[]},{"id":"hisn-247","n":247,"title":"To ward off the plot of the rebellious devils","chapter_en":"To ward off the plot of the rebellious devils","chapter_ar":"ما يقول لرد كيد مردة الشياطين","arabic":"أَعُوذُ بكَلِمَاتِ اللهِ التَّامَّاتِ الَّتِي لَا يُجَاوِزُهُنَّ بَرٌّ ولَا فَاجرٌ مِنْ شّرِّ مَا خَلقَ، وبَرَأَ وذَرَأَ، ومِنْ شَرِّ مَا يَنْزِلُ مِنَ السَّمَاءِ وِمنْ شَرِّ مَا يَعْرُجُ فيهَا، ومِن شَرِّ مَا ذَرَأَ في الأَرْضِ ومِنْ شَرِّ مَا يَخْرُجُ مِنْهَا، وِمنْ شَرِّ فِتَنِ اللَّيْلِ والنَّهارِ، ومِنْ شَرِّ كُلِّ طارِقٍ إِلَّا طَارِقاً يَطْرُقُ بخَيْرٍ يَا رَحْمَنُ","transliteration":"A`ūdhu bikalimāti ‘llāhit-tāmmāti ‘llatī lā yujāwizuhunna barrun wa lā fājirun min sharri mā khalaq, wa bara\u0027a wa dhara\u0027, wa min sharri mā yanzilu minas-samā\u0027, wa min sharri mā ya`ruju fīhā, wa min sharri mā dhara\u0027a fi ‘l-arḍ, wa min sharri ma yakhruju minhā, wa min sharri fitani ‘llayli wannahār, wa min sharri kulli ṭāriqin illā ṭāriqan yaṭruqu bikhayr yā Rahmān.","meaning_en":"I seek refuge in the Perfect Words of Allah -which neither the upright nor the corrupt may overcome - from the evil of what He created, of what He made, and of what He scattered, from the evil of what descends from the heavens, and of what rises up to them, from the evil of what He scattered in the earth, and of what emerges from it, from the evil trials of night and day, and from the evil of every night visitor, except the night visitor who comes with good. O Merciful One.","meaning_dv":"","reference":"Ahmad 3/419, with an authentic chain of narration, and Ibn As-Sunni (no. 637). Al-Arna\u0027ut, graded its chain authentic in his checking of Al-\u0027Aqidah At-Tahawiyyah p. 133. See also Majma\u0027uz-Zawa\u0027id, 10/127.","source":"Hisn al-Muslim 247 - Sunnah.com","source_url":"https://sunnah.com/hisn:247","tags":["patience","protection"]},{"id":"hisn-248","n":248,"title":"Seeking forgiveness and repentance","chapter_en":"Seeking forgiveness and repentance","chapter_ar":"الاستغفار والتوبة","arabic":"قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: \"وَاللَّهِ إِنِّي لأَسْتَغفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ فِي الْيَوْمِ أَكْثَرَ مِنْ سَبْعِينَ مَرَّةٍ\"","transliteration":"--","meaning_en":"Allah\u0027s Messenger (ﷺ) said:","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 11/101.","source":"Hisn al-Muslim 248 - Sunnah.com","source_url":"https://sunnah.com/hisn:248","tags":["forgiveness"]},{"id":"hisn-249","n":249,"title":"Seeking forgiveness and repentance","chapter_en":"Seeking forgiveness and repentance","chapter_ar":"الاستغفار والتوبة","arabic":"وَقَالَ صلى الله عليه وسلم: (يَا أَيُّهَا النَّاسُ تُوبُوا إِلَى اللَّهِ فَإِنِّي أَتُوبُ فِي الْيَوْمِ إِلَيْهِ مِائَةَ مَرَّةٍ)","transliteration":"--","meaning_en":"Allah\u0027s Messenger (ﷺ) said:","meaning_dv":"","reference":"Muslim 4/2076.","source":"Hisn al-Muslim 249 - Sunnah.com","source_url":"https://sunnah.com/hisn:249","tags":["forgiveness"]},{"id":"hisn-250","n":250,"title":"Seeking forgiveness and repentance","chapter_en":"Seeking forgiveness and repentance","chapter_ar":"الاستغفار والتوبة","arabic":"وَقَالَ صلى الله عليه وسلم: مَنْ قَالَ (أَسْتَغْفِرُ اللَّهَ الْعَظيمَ الَّذِي لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ القَيّوُمُ وَأَتُوبُ إِلَيهِ)، غَفَرَ اللَّهُ لَهُ وَإِنْ كَانَ فَرَّ مِنَ الزَّحْفِ.","transliteration":"Allah\u0027s Messenger (ﷺ) said:","meaning_en":"Allah\u0027s Messenger (ﷺ) said: Whoever says: I seek the forgiveness of Allah the Mighty, Whom there is none worthy of worship except Him, the Living, the Eternal, and I repent to Him, Allah will forgive him even if he has deserted the army\u0027s ranks.","meaning_dv":"","reference":"Abu Dawud 2/85, At-Tirmidhi 5/569, and Al-Hakim who declared it authentic and Ath-Thahabi agreed with him 1/511. Al-Albani graded it authentic in Sahih At-Tirmidhi 3/182. See also Jami\u0027ul-\u0027Usool li-\u0027Ahdaith Ar-Rasool 4/ 389-90 checked by Al-Arna\u0027ut.","source":"Hisn al-Muslim 250 - Sunnah.com","source_url":"https://sunnah.com/hisn:250","tags":["forgiveness"]},{"id":"hisn-251","n":251,"title":"Seeking forgiveness and repentance","chapter_en":"Seeking forgiveness and repentance","chapter_ar":"الاستغفار والتوبة","arabic":"وَقَالَ صلى الله عليه وسلم: أَقْرَبُ مَا يَكُونُ الرَّبُّ مِنَ الْعَبْدِ فِي جَوْفِ اللَّيْلِ الآخِرِ فَإِنِ اسْتَطَعْتَ أَنْ تَكُونَ مِمَّنْ يَذْكُرُ اللَّهَ فِي تِلْكَ السَّاعَةِ فَكُنْ","transliteration":"--","meaning_en":"Allah\u0027s Messenger (ﷺ) said:","meaning_dv":"","reference":"At-Tirmidhi, An-Nasa\u0027i 1/279 and Al-Hakim. See also Al-Albani, Sahih At-Tirmidhi 3/183, and Jdmi\u0027ul-\u0027Usool with Al-Arna\u0027ut\u0027s checking 4/144.","source":"Hisn al-Muslim 251 - Sunnah.com","source_url":"https://sunnah.com/hisn:251","tags":["forgiveness"]},{"id":"hisn-252","n":252,"title":"Seeking forgiveness and repentance","chapter_en":"Seeking forgiveness and repentance","chapter_ar":"الاستغفار والتوبة","arabic":".وَقَالَ صلى الله عليه وسلم: أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ فَأَكثِرُوا الدُّعَاءَ.","transliteration":"--","meaning_en":"Allah\u0027s Messenger (ﷺ) said:","meaning_dv":"","reference":"Muslim 1/350.","source":"Hisn al-Muslim 252 - Sunnah.com","source_url":"https://sunnah.com/hisn:252","tags":["forgiveness"]},{"id":"hisn-253","n":253,"title":"Seeking forgiveness and repentance","chapter_en":"Seeking forgiveness and repentance","chapter_ar":"الاستغفار والتوبة","arabic":".وَقَالَ صلى الله عليه وسلم: إِنَّهُ لَيُغَانُ عَلَى قَلْبِي وَإِنِّي لأَسْتَغْفِرُ اللَّهَ فِي الْيَوْمِ مِائَةَ مَرَّةٍ.","transliteration":"--","meaning_en":"Allah\u0027s Messenger (ﷺ) said:","meaning_dv":"","reference":"Muslim 4/2075. Ibn \u0027Athir explains that the Prophet (ﷺ) was always vigilant in his remembrance and drawing near to Allah, and if he forgot to do any of what he normally did from time to time, or it slipped his mind, he felt as if he had wronged himself and so he would begin to seek the forgiveness of Allah. See Jami\u0027ul-\u0027Usool 4/386.","source":"Hisn al-Muslim 253 - Sunnah.com","source_url":"https://sunnah.com/hisn:253","tags":["forgiveness"]},{"id":"hisn-254","n":254,"title":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_en":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_ar":"من فضل التسبيح والتحميد ، والتهليل ، والتكبير","arabic":"قَالَ صلى الله عليه وسلم: مَنْ قَالَ (سُبْحَانَ اللَّهِ وَبِحَمْدِهِ) فِي يَوْمٍ مِائَةَ مَرَّةٍ حُطَّتْ خَطَايَاهُ وَلَوْ كَانَتْ مِثْلَ زَبَدِ الْبَحْر.","transliteration":"Allah\u0027s Messenger (ﷺ) said:","meaning_en":"Allah\u0027s Messenger (ﷺ) said: Whoever says: Glorified is Allah and praised is He. one hundred times a day, will have his sins forgiven even if they are like the foam of the sea.","meaning_dv":"","reference":"Al-Bukhari 7/168, Muslim 4/2071, see also invocation no. 91 of this book.","source":"Hisn al-Muslim 254 - Sunnah.com","source_url":"https://sunnah.com/hisn:254","tags":["forgiveness","gratitude"]},{"id":"hisn-255","n":255,"title":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_en":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_ar":"من فضل التسبيح والتحميد ، والتهليل ، والتكبير","arabic":"وَقَالَ صلى الله عليه وسلم: مَنْ قَالَ (لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) عَشْرَ مِرَارٍ، كَانَ كَمَنْ أَعْتَقَ أَرْبَعَةَ أَنْفُسٍ مِنْ وَلَدِ إِسْمَاعِيلَ","transliteration":"Allah\u0027s Messenger (ﷺ) said:","meaning_en":"Allah\u0027s Messenger (ﷺ) said: Whoever says: None has the right to be worshipped but Allah alone, Who has no partner. His is the dominion and His is the praise, and He is Able to do all things. ten times, will have the reward for freeing four slaves from the Children of Isma\u0027il.","meaning_dv":"","reference":"Al-Bukhari 7/67, Muslim 4/2071, see also invocation no. 93 of this book.","source":"Hisn al-Muslim 255 - Sunnah.com","source_url":"https://sunnah.com/hisn:255","tags":["family","gratitude"]},{"id":"hisn-256","n":256,"title":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_en":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_ar":"من فضل التسبيح والتحميد ، والتهليل ، والتكبير","arabic":"وَقَالَ صلى الله عليه وسلم: كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي الْمِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ: (سُبْحَانَ اللَّهِ وَبِحَمْدِهِ)، (سُبْحانَ اللَّهِ الْعَظِيمِ)","transliteration":"Allah\u0027s Messenger (ﷺ) said:","meaning_en":"Allah\u0027s Messenger (ﷺ) said: Two words are light on the tongue, weigh heavily in the balance, and are loved by the Most Merciful One: Glorified is Allah and praised is He, Glorified is Allah the Most Great.","meaning_dv":"","reference":"Al-Bukhari 7/168, Muslim 4/2072.","source":"Hisn al-Muslim 256 - Sunnah.com","source_url":"https://sunnah.com/hisn:256","tags":["gratitude"]},{"id":"hisn-257","n":257,"title":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_en":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_ar":"من فضل التسبيح والتحميد ، والتهليل ، والتكبير","arabic":"وَقَالَ صلى الله عليه وسلم: لَأَنْ أَقُولَ (سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ)، أَحَبُّ إِلَيَّ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمسُ.","transliteration":"Allah\u0027s Messenger (ﷺ) said:","meaning_en":"Allah\u0027s Messenger (ﷺ) said: For me to say: Glory is to Allah, and praise is to Allah, and there is none worthy of worship but Allah, and Allah is the Most Great. is dearer to me than all that the sun rises upon (i.e. the whole world).","meaning_dv":"","reference":"Muslim 4/2072.","source":"Hisn al-Muslim 257 - Sunnah.com","source_url":"https://sunnah.com/hisn:257","tags":["gratitude"]},{"id":"hisn-258","n":258,"title":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_en":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_ar":"من فضل التسبيح والتحميد ، والتهليل ، والتكبير","arabic":"وَقَالَ صلى الله عليه وسلم: أَيَعْجِزُ أَحَدُكُم أَنْ يَكْسِبَ كُلَّ يَوْمٍ أَلْفَ حَسَنَةٍ؟ فَسَأَلَهُ سَائِلٌ مِنْ جُلَسَائِهِ كَيْفَ يَكْسِبُ أَحَدُنَا أَلْفَ حَسَنَةٍ؟ قَالَ: يُسَبِّحُ مِائَةَ تَسْبِيحَةٍ، فَيُكتَبُ لَهُ أَلْفُ حَسَنَةٍ أَوْ يُحَطُّ عَنْهُ أَلْفُ خَطِيئَةٍ.","transliteration":"--","meaning_en":"Allah\u0027s Messenger (ﷺ) said:","meaning_dv":"","reference":"Muslim 4/2073.","source":"Hisn al-Muslim 258 - Sunnah.com","source_url":"https://sunnah.com/hisn:258","tags":[]},{"id":"hisn-259","n":259,"title":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_en":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_ar":"من فضل التسبيح والتحميد ، والتهليل ، والتكبير","arabic":"مَنْ قَالَ (سُبْحَانَ اللَّهِ الْعَظِيمِ وَبِحَمْدِهِ) غُرِسَتْ لَهُ نَخْلَةٌ فِي الْجَنَّةِ","transliteration":"Whoever says:","meaning_en":"Whoever says: Glorified is Allah the Most Great and praised is He. will have a date palm planted for him in Paradise.","meaning_dv":"","reference":"At-Tirmidhi 5/511, and Al-Hakim who graded it authentic and Ath-Thahabi agreed 1/501. See also Al-Albani, Sahihul-Jami\u0027 As-Saghir 5/531 and Sahih At-Tirmidhi3/160.","source":"Hisn al-Muslim 259 - Sunnah.com","source_url":"https://sunnah.com/hisn:259","tags":["gratitude"]},{"id":"hisn-260","n":260,"title":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_en":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_ar":"من فضل التسبيح والتحميد ، والتهليل ، والتكبير","arabic":"وَقَالَ صلى الله عليه وسلم: يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ أَلاَ أَدُلُّكَ عَلَى كَنْزٍ مِنْ كُنُوزِ الْجَنَّةِ؟ فَقُلْتُ: بَلَى يَا رَسُولَ اللَّهِ، قَالَ: قُلْ (لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ).","transliteration":"Allah\u0027s Messenger (ﷺ) said:","meaning_en":"Allah\u0027s Messenger (ﷺ) said: \"O Abdullah bin Qais, should I not point you to one of the treasures of Paradise?\" I said, \"Yes, O Messenger of Allah.\" So he told me to say: There is no power and no might except by Allah.","meaning_dv":"","reference":"Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 11/213, Muslim 4/2076.","source":"Hisn al-Muslim 260 - Sunnah.com","source_url":"https://sunnah.com/hisn:260","tags":[]},{"id":"hisn-261","n":261,"title":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_en":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_ar":"من فضل التسبيح والتحميد ، والتهليل ، والتكبير","arabic":"وَقَالَ صلى الله عليه وسلم: أَحَبُّ الْكَلاَمِ إِلَى اللَّهِ أَرْبَعٌ: (سُبْحَانَ اللَّهِ)، وَ(الْحَمْدُ لِلَّهِ)، وَ(لاَ إِلَهَ إِلاَّ اللَّهُ)، وَ(اللَّهُ أَكْبَرُ)، لاَ يَضُرُّكَ بِأَيِّهِنَّ بَدَأتَ","transliteration":"Allah\u0027s Messenger (ﷺ) said:","meaning_en":"Allah\u0027s Messenger (ﷺ) said: The most beloved words to Allah are four: Glorified is Allah, and The praise is for Allah, and There is none worthy of worship but Allah, and Allah is the Most Great.","meaning_dv":"","reference":"Muslim 3/1685.","source":"Hisn al-Muslim 261 - Sunnah.com","source_url":"https://sunnah.com/hisn:261","tags":["gratitude"]},{"id":"hisn-262","n":262,"title":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_en":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_ar":"من فضل التسبيح والتحميد ، والتهليل ، والتكبير","arabic":"جَاءَ أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ: عَلِّمْنِي كَلاماً أَقُولُهُ: قَالَ: قُلْ (لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، اللَّهُ أَكْبَرُ كَبِيراً، وَالْحَمْدُ لِلَّهِ كَثِيراً، سُبْحَانَ اللَّهِ رَبِّ العَالَمِينَ، لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ الْعَزِيزِ الْحَكِيمِ). قَالَ: فَهَؤُلاَءِ لِرَبِّي، فَمَا لِي؟ قَالَ: قُلْ (اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَارْزُقْنِي).","transliteration":"A desert Arab came to Allah\u0027s Messenger (ﷺ) and said, \"Teach me a word that I can say. \" The Prophet told him to say:","meaning_en":"A desert Arab came to Allah\u0027s Messenger (ﷺ) and said, \"Teach me a word that I can say. \" The Prophet told him to say: There is none worthy of worship but Allah, Who has no partner, Allah is the Great, the Most Great, and praise is to Allah in abundance, glory is to Allah, Lord of the worlds. There is no power and no might but by Allah the Mighty, the Wise. He said, \"That is for my Lord, but what about me?\" The Prophet (ﷺ) told him to say: O Allah forgive me, and have mercy on me and guide me, and provide for me.","meaning_dv":"","reference":"Muslim 4/2072, Abu Dawud reports the same Hadith with the addition: and when the Arab left, the Prophet (ﷺ) said: \"He has filled his hands with goodness.\" 1/220.","source":"Hisn al-Muslim 262 - Sunnah.com","source_url":"https://sunnah.com/hisn:262","tags":["forgiveness","gratitude"]},{"id":"hisn-263","n":263,"title":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_en":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_ar":"من فضل التسبيح والتحميد ، والتهليل ، والتكبير","arabic":"كَانَ الرَّجُلُ إِذَا أَسْلَمَ عَلَّمَهُ النَّبيُّ صلى الله عليه وسلم الصَّلاَةَ ثُمَّ أَمَرَهُ أَنْ يَدْعُوَ بِهَؤُلاَءِ الْكَلِمَاتِ: (اللَّهُمَّ اغْفِرِ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَعَافِنِي وَارْزُقْنِي)","transliteration":"Whenever anyone accepted Islam, the Prophet (ﷺ) used to teach him how to pray then he would instruct him to invoke Allah with the following words:","meaning_en":"Whenever anyone accepted Islam, the Prophet (ﷺ) used to teach him how to pray then he would instruct him to invoke Allah with the following words: O Allah forgive me, and have mercy on me and guide me and give me good health and provide for me.","meaning_dv":"","reference":"Muslim 4/2073, and in one of Muslim\u0027s reports there is the addition: \u0027For these words combine [the goodness of] this world and the next.\u0027","source":"Hisn al-Muslim 263 - Sunnah.com","source_url":"https://sunnah.com/hisn:263","tags":["forgiveness","illness"]},{"id":"hisn-264","n":264,"title":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_en":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_ar":"من فضل التسبيح والتحميد ، والتهليل ، والتكبير","arabic":"إِنَّ أَفْضَلَ الدُّعَاءِ (الْحَمْدُ لِلَّهِ)، وَأَفْضَلَ الذِّكْرِ (لاَ إِلَهَ إِلاَّ اللَّهُ)","transliteration":"The most excellent invocation is:","meaning_en":"The most excellent invocation is: Praise is for Allah. and the most excellent words of remembrance are: There is none worthy of worship but Allah.","meaning_dv":"","reference":"At-Tirmidhi 5/462, Ibn Majah 2/1249, and Al-Hakim who graded it authentic and Ath-Tbahabi agreed 1/503. See Al-Albani, Sahihul-Jami\u0027 As-Saghir 1/362.","source":"Hisn al-Muslim 264 - Sunnah.com","source_url":"https://sunnah.com/hisn:264","tags":["gratitude"]},{"id":"hisn-265","n":265,"title":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_en":"Excellence of Tasbih, Tahmid, Tahlil, and Takbir","chapter_ar":"من فضل التسبيح والتحميد ، والتهليل ، والتكبير","arabic":"الباقيات الصالحات : (سبحان الله) و(الحمد لله )، و(لا إله إلا الله)، و(الله أكبر) ،و (لا حول ولا قوة إلا بالله).","transliteration":"The good deeds which endure are:","meaning_en":"The good deeds which endure are: Glorified is Allah, and The praise is for Allah, and There is none worthy of worship but Allah, and Allah is the Most Great, and There is no power and no might except by Allah.","meaning_dv":"","reference":"Ahmad (no. 513) (Ahmad Shakir, ed.) and its chain of narration is authentic. See Majma\u0027uz-Zawa\u0027id 1/297. Ibn Hajar mentions it in Bulughul-Maram saying that Ibn Hibban and Al-Hakim considered it authentic.","source":"Hisn al-Muslim 265 - Sunnah.com","source_url":"https://sunnah.com/hisn:265","tags":["gratitude"]},{"id":"hisn-266","n":266,"title":"How the Prophet ﷺ made tasbeeh","chapter_en":"How the Prophet ﷺ made tasbeeh","chapter_ar":"كيف كان النبي ﷺ يسبح ؟","arabic":"عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رضي الله عنهما قَالَ: رَأَيْتُ النَّبيَّ صلى الله عليه وسلم يَعْقِدُ التَّسْبِيحَ بِيَمِينِهِ.","transliteration":"","meaning_en":"Abdullah bin \u0027Amr (RA) said:","meaning_dv":"","reference":"Abu Dawud with a different wording 2/81, and At-Tirmidhi 5/521. See also Al-Albani, Sahihul-Jami\u0027As-Saghir 4/271 (no. 4865).","source":"Hisn al-Muslim 266 - Sunnah.com","source_url":"https://sunnah.com/hisn:266","tags":[]},{"id":"hisn-267","n":267,"title":"Comprehensive types of good and manners","chapter_en":"Comprehensive types of good and manners","chapter_ar":"من أنواع الخير والآداب الجامعة","arabic":"إِذَا كَانَ جُنْحُ اللَّيْلِ – أَوْ أَمْسَيْتُم – فَـكُفُّوا صِبْيانَـكُم، فَإِنَّ الشَّيَاطِينَ تَنْتَشِرُ حِينَئِذٍ، فَإِذَا ذَهَبَ سَاعَةٌ مِنَ اللَّيلِ فَخَلُّوهُمْ، وَأَغْلِقُوا الأَبْوَابَ وَاذْكُرُوا اسْمَ اللَّهِ؛ فَإِنَّ الشَّيطَانَ لاَ يَفْتَحُ بَاباً مُغلَقاً، وَأَوْكُوا قِرَبَكُمْ، وَاذْكُرُوا اسْمَ اللَّهِ، وَخَمِّرُوا آنِيَتَكُم، وَاذْكُرُوا اسْمَ اللَّهِ، وَلَوْ أَنْ تَعْرُضُوا عَلَيْهَا شَيْئاً، وَأَطْفِئُوا مَصَابِيحَكُمْ.","transliteration":"","meaning_en":"When night falls, restrain your children (from going out) because at such time the devils spread about. After a period of time has passed, let them be. Shut your doors and mention Allah’s name, for verily the devil does not open a shut door, tie up your water-skins and mention Allah’s name, cover your vessels with anything and mention Allah’s name and put out your lamps.","meaning_dv":"","reference":"Al-Bukhari with Al-Fath 10/88 and Muslim 3/1595.","source":"Hisn al-Muslim 267 - Sunnah.com","source_url":"https://sunnah.com/hisn:267","tags":["family","protection","weather"]}];
